/* ---------- reading the files ----------
   Two kinds of EfL file come in through the same door, one or many at a time:
   - the Learner Assessment Books export (.xlsx): where every pupil is now, dated the export day;
   - assessment transaction logs (.csv, one per framework): every judgement ever made, with its own
     date, the teacher who made it and any evidence note. Change-log lines in them are skipped: the
     judgement lines already show the value after any change. */
function eflRowsFromXlsx(wb, fname){
  const ws = wb.Sheets[wb.SheetNames[0]];
  const aoa = XLSX.utils.sheet_to_json(ws, {header:1, defval:"", raw:true});
  const hi = aoa.findIndex(function(r){ return r.some(function(c){ return /assessment book name/i.test(String(c)); }); });
  if(hi < 0) return {error:fname + ": this isn’t an Evidence for Learning assessment data export (there is no Assessment Book Name column)."};
  const H = aoa[hi].map(function(h){ return String(h); });
  const col = function(re){ return H.findIndex(function(h){ return re.test(h); }); };
  const c = {first:col(/learner\s*first/i), last:col(/learner\s*last/i), book:col(/assessment book name/i), path:col(/framework path/i),
             item:col(/framework item/i), aspect:col(/^aspect\d*\s*name/i), value:col(/aspect\d*\s*value\s*name/i)};
  if(c.first < 0 || c.last < 0 || c.path < 0 || c.item < 0 || c.value < 0) return {error:fname + ": some of the columns EfL normally includes are missing (Learner FirstName, Learner LastName, Framework Path, Framework Item, Aspect Value Name). Export again with those ticked."};
  const dm = /(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(H[c.value]);
  const asOf = dm ? dm[3] + "-" + String(dm[2]).padStart(2, "0") + "-" + String(dm[1]).padStart(2, "0") : todayIso();
  const rows = [];
  aoa.slice(hi + 1).forEach(function(r){
    rows.push({book:eflTidy(r[c.book]), first:eflTidy(r[c.first]), last:eflTidy(r[c.last]), path:eflFixText(r[c.path]), item:eflFixText(r[c.item]),
               aspect:eflTidy(c.aspect >= 0 ? r[c.aspect] : ""), value:eflTidy(r[c.value]), d:asOf, ts:asOf + " ~", by:"EfL", note:"", src:"snap"});
  });
  return {kind:"snap", name:fname, asOf:asOf, rows:rows};
}
/* bytes -> text: EfL writes its logs as UTF-16 */
