  if(typeof TextDecoder !== "undefined") return new TextDecoder("utf-8").decode(u8.subarray(start));
  let s = ""; for(let i = start; i < u8.length; i += 8192) s += String.fromCharCode.apply(null, u8.subarray(i, i + 8192));
