  const drop = latestStartedDrop() || dps[dps.length - 1] || null, ay = drop ? (acYearOf(drop.date) || currentAY()) : currentAY();
  const prevLast = dps.filter(function(d){ return (acYearOf(d.date) || "") < ay; }).pop();
