    (function(){ try { const h = profileFwHtml(p); return h ? '<div class="dsec">' + h.replace(/^<div class="panel">/, "<div>") + '</div>' : ''; } catch(e){ return ''; } })() +
    '<div class="dsec"><h3>Assessment results</h3>' + (res ? '<div class="tablewrap"><table><thead><tr>' + head + '</tr></thead><tbody>' + res + '</tbody></table></div>' : '<p class="hint">No assessment results yet.</p>') + '</div>' +
    '<div class="dsec"><h3>AAA pathway</h3>' + (logs.length ? logs.map(function(l){ return '<div class="histitem"><div><b>' + esc(fmtDateTime(l.ts)) + '</b> · ' + (l.from && l.from !== l.to ? pathwayTag(l.from, true) + ' → ' : '') + pathwayTag(l.to, true) + (l.staff ? ' <span class="muted">by ' + esc(l.staff) + '</span>' : '') + '</div><div class="evidence">' + esc(reasonLabel(l.reason)) + (l.notes ? ' — ' + esc(l.notes) : '') + '</div></div>'; }).join("") : '<p class="hint">Nothing logged yet.</p>') + '</div>';
  document.getElementById("drawerFoot").innerHTML = (ENTRY_MODE && entryAaaOff ? '' : '<button class="btn" data-act="card-aaa" data-pid="' + p.id + '">Log an AAA update</button>') + '<button class="btn ghost" data-act="drawer-close">Close</button>';
