    if(!scrim){ reject(new Error("a passphrase is needed")); return; }
    document.getElementById("passIntro").innerHTML = (STAFF_MODE || ENTRY_MODE)
      ? "The tracker needs the staff passphrase before it can open the data. Ask SLT if you don\u2019t have it."
      : "The tracker needs its passphrase before it can open the data. It is not kept in the file, so a copied file is no use on its own.";
