/* --- assessment edit panel ---
   Edits are made on a draft and only reach the tracker (and SharePoint) on Save. */
let draft = null;
function openAssessmentEditor(id, duplicate){
  aaaPupil = null;
  const src = id ? byId(state.assessments, id) : null;
  if(src){
    draft = JSON.parse(JSON.stringify(src));
    if(duplicate){ draft.id = uid("as"); draft.name = src.name + " (copy)"; draft.isNew = true; }
  } else {
    draft = {id:uid("as"), name:"", subject:"", type:"sas", active:true, cfg:Object.assign({}, SCORE_TYPES.sas.defaults), isNew:true};
  }
  draft.origType = src && !duplicate ? src.type : null;
  renderDrawer();
  document.getElementById("drawer").classList.add("open");
  document.getElementById("drawer").setAttribute("aria-hidden","false");
  document.getElementById("drawerScrim").classList.add("open");
  setTimeout(function(){ const f = document.querySelector('#drawerBody [data-dr="name"]'); if(f) f.focus(); }, 60);
}
let drawerReturnFocus = null;
function closeDrawer(){
  if(drawerReturnFocus && drawerReturnFocus.focus){ const f = drawerReturnFocus; drawerReturnFocus = null; setTimeout(function(){ try { f.focus(); } catch(e){} }, 0); }
  draft = null;
  aaaPupil = null;
  settingsPupil = null;
  cardPid = null;
  document.getElementById("drawer").classList.remove("wide");
  document.getElementById("drawer").classList.remove("open");
  document.getElementById("drawer").setAttribute("aria-hidden","true");
  document.getElementById("drawerScrim").classList.remove("open");
}
function changeDraftType(type){
  if(!draft || !SCORE_TYPES[type]) return;
  const keep = {};
  CFG_KEEP.forEach(function(k){ if(draft.cfg[k]!=null && draft.cfg[k]!=="") keep[k] = draft.cfg[k]; });
  draft.type = type;
  draft.cfg = Object.assign({}, SCORE_TYPES[type].defaults, keep);
  renderDrawer();
}
function drawerYears(){
  const s = {};
  state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) s[String(p.year)] = true; });
  yearsList(draft).forEach(function(y){ s[y] = true; });
  return Object.keys(s).sort(function(a,b){ return yearSortKey(a)-yearSortKey(b); });
}
function bandWarning(){
  if(!draft || draft.type!=="band") return "";
  const scale = splitList(draft.cfg.options).map(function(x){ return x.toLowerCase(); });
  if(!scale.length) return "";
  const off = splitList(draft.cfg.concernValues).concat(splitList(draft.cfg.watchValues))
    .filter(function(v){ return scale.indexOf(v.toLowerCase()) < 0; });
  return off.length ? "Not on the scale, so these will never match: " + off.join(", ") + "." : "";
}
function renderDrawer(){
  if(!draft) return;
  const t = SCORE_TYPES[draft.type];
  const nRes = state.results.filter(function(r){ return r.assessmentId===draft.id && r.value!==""; }).length;
  document.getElementById("drawerTitle").textContent = draft.isNew ? "New assessment" : "Edit assessment";
  const field = function(f){
    const k = f[0], v = draft.cfg[k]==null ? "" : draft.cfg[k];
    if(k==="direction"){
      return '<label class="fld">'+esc(f[1])+'<select data-drc="direction"><option value="higher"'+(v!=="lower"?" selected":"")+'>Higher</option>'+
        '<option value="lower"'+(v==="lower"?" selected":"")+'>Lower</option></select></label>';
    }
    if(k==="options" || k==="concernValues" || k==="watchValues"){
      return '<label class="fld" style="width:100%">'+esc(f[1])+' <small>separate with commas</small><textarea data-drc="'+k+'" rows="2" style="width:100%">'+esc(v)+'</textarea></label>';
    }
    return '<label class="fld">'+esc(f[1])+'<input data-drc="'+k+'" value="'+esc(v)+'" style="width:'+(k==="unit"?"120":"110")+'px"></label>';
  };
  const ys = drawerYears(), picked = {};
  yearsList(draft).forEach(function(y){ picked[y] = true; });
  const bw = bandWarning();
  document.getElementById("drawerBody").innerHTML =
    '<div class="dsec"><div class="row">'+
      '<label class="fld" style="flex:1;min-width:220px">Name<input data-dr="name" value="'+esc(draft.name)+'" placeholder="e.g. GL Progress Test in Science"></label>'+
      '<label class="fld">Subject<input data-dr="subject" value="'+esc(draft.subject)+'" style="width:140px" placeholder="Science"></label>'+
      (function(){
        const auto = asmSubjectId({subject:draft.subject, cfg:{}}), autoSu = auto ? byId(state.subjects, auto) : null;
        const cur = draft.cfg.subjectId || "";
        return '<label class="fld" title="Shown beside this subject on pupil profiles, and checked against its levels">Curriculum subject<select data-drc="subjectId">'+
          '<option value=""'+(cur===""?" selected":"")+'>Match by name'+(autoSu ? ' ('+esc(autoSu.name)+')' : ' (none found)')+'</option>'+
          (state.subjects||[]).filter(function(s){ return s.active !== false; }).map(function(s){ return '<option value="'+esc(s.id)+'"'+(cur===s.id?" selected":"")+'>'+esc(s.name)+'</option>'; }).join("")+
          '<option value="none"'+(cur==="none"?" selected":"")+'>Not linked to a subject</option></select></label>';
      })()+
      '<label class="fld">Who enters it in staff entry<select data-drc="entryWho">'+
        '<option value=""'+(draft.cfg.entryWho!=="all"?" selected":"")+'>Teachers of this subject</option>'+
        '<option value="all"'+(draft.cfg.entryWho==="all"?" selected":"")+'>All staff</option></select></label></div>'+
      '<p class="hint" style="margin:-4px 0 8px">Choose All staff for things tutors or TAs enter, like a reading test. An assessment with no subject, or one that isn\u2019t a subject on your list, goes to all staff anyway.</p>'+
      '<label style="display:flex;align-items:center;gap:8px;font-size:13px"><input type="checkbox" data-dr="active"'+(draft.active?" checked":"")+'>In use (switched-off assessments keep their results but are left out of flags and missing results)</label></div>'+

    '<div class="dsec"><h3>Score type</h3><div class="row">'+
      '<label class="fld" style="flex:1;min-width:220px">How it is scored<select id="drType">'+
        Object.keys(SCORE_TYPES).map(function(k){ return '<option value="'+k+'"'+(k===draft.type?" selected":"")+'>'+esc(SCORE_TYPES[k].label)+'</option>'; }).join("")+
      '</select></label>'+
      '<label class="fld" style="flex:1;min-width:200px">Display name <small>optional</small><input data-drc="typeLabel" value="'+esc(draft.cfg.typeLabel||"")+'" placeholder="'+esc(t.label)+'"></label></div>'+
      '<div class="typeinfo">'+esc(t.hint)+'</div>'+
      (draft.origType && draft.origType!==draft.type && nRes ? '<div class="warn" style="margin:10px 0 0">'+nRes+' existing result'+(nRes===1?'':'s')+' will be kept and read using the new score type. Check they still make sense after saving.</div>' : '')+
    '</div>'+

    '<div class="dsec"><h3>Thresholds</h3>'+
      (t.fields.length ? '<div class="row">'+t.fields.map(field).join("")+'</div>' : '<p class="hint">Nothing to set: fail is a concern and working towards is a watch.</p>')+
      (draft.type==="level" ? '<label class="fld" style="width:100%">Level names <small>optional, lowest first, separated by commas</small><input data-drc="levelNames" value="'+esc(draft.cfg.levelNames||"")+'" placeholder="e.g. Naming, Describing, Retelling, Reasoning" style="width:100%"></label>' : '')+
      '<div class="warn" id="drBandWarn" style="margin:10px 0 0"'+(bw ? '' : ' hidden')+'>'+esc(bw)+'</div>'+
      '<p class="hint" data-rule style="margin:10px 0 0">In words: '+ruleText(draft)+'</p>'+
    '</div>'+

    '<div class="dsec"><h3>Year groups</h3>'+
      '<p class="hint" style="margin:0 0 8px">Who should sit this. Pupils in these year groups with no result are listed as missing once the assessment has been started in a data drop. Leave all unticked to work it out from the results entered so far.</p>'+
      (ys.length ? '<div class="yearpick">'+ys.map(function(y){
        return '<label class="'+(picked[y]?'on':'')+'"><input type="checkbox" data-dryear="'+esc(y)+'"'+(picked[y]?" checked":"")+'>Year '+esc(y)+'</label>';
      }).join("")+'</div>' : '<p class="hint">Add pupils with year groups first.</p>')+
    '</div>'+

    '<div class="dsec"><h3>How often it is sat</h3>'+
      '<label class="fld">Counts as missing<select data-drc="frequency">'+
        '<option value="year"'+(draft.cfg.frequency!=="drop"?" selected":"")+'>Once a year: until the pupil has a result in any drop this year</option>'+
        '<option value="drop"'+(draft.cfg.frequency==="drop"?" selected":"")+'>Every data drop: in each drop it has been started in</option>'+
      '</select></label></div>'+
    '<div class="dsec"><h3>Notes for staff</h3>'+
      '<textarea data-drc="notes" rows="3" style="width:100%" placeholder="How it is administered, where scores come from, who enters them">'+esc(draft.cfg.notes||"")+'</textarea>'+
      '<p class="hint" style="margin:4px 0 0">Shown on the Enter results screen.</p></div>';

  document.getElementById("drawerFoot").innerHTML =
    '<button class="btn" data-act="drawer-save">Save</button>'+
    '<button class="btn ghost" data-act="drawer-close">Cancel</button>'+
    '<span class="spacer"></span>'+
    (draft.isNew ? '' : '<button class="btn subtle" data-dup-as="'+draft.id+'"><svg class="ic sm"><use href="#i-copy"/></svg>Duplicate</button>'+
      '<button class="btn danger" data-del-as="'+draft.id+'"><svg class="ic sm"><use href="#i-delete"/></svg>Remove</button>');
}
function saveDraft(){
  if(!draft) return;
  const name = String(draft.name||"").trim();
  if(!name){ alert("Give the assessment a name."); return; }
  const clash = state.assessments.some(function(a){ return a.id!==draft.id && String(a.name).trim().toLowerCase()===name.toLowerCase(); });
  if(clash && !confirm("Another assessment is already called “"+name+"”. Save anyway?")) return;
  const rec = {id:draft.id, name:name, subject:String(draft.subject||"").trim(), type:draft.type, active:!!draft.active, cfg:{}};
  Object.keys(draft.cfg).forEach(function(k){
    const v = draft.cfg[k];
    if(CFG_KEEP.indexOf(k) >= 0 && (v==="" || v==null)) return;   /* keep the cfg column tidy */
    rec.cfg[k] = typeof v === "string" ? v.trim() : v;
  });
  const existing = byId(state.assessments, draft.id);
  if(existing){ Object.keys(rec).forEach(function(k){ existing[k] = rec[k]; }); }
  else state.assessments.push(rec);
  closeDrawer();
  markDirty(); renderAll();
}

