/* ---------------- CSV ---------------- */
/* Splits a pasted line. If the line contains tabs it came from a spreadsheet,
   so only tabs separate fields and commas inside names are left alone. */
function parseCsvLine(line){
  const tabbed = line.indexOf("\t") >= 0;
  const out=[]; let cur=""; let q=false;
  for(let i=0;i<line.length;i++){
    const ch=line[i];
    if(q){
      if(ch==='"'){ if(line[i+1]==='"'){cur+='"';i++;} else q=false; }
      else cur+=ch;
    } else {
      if(ch==='"') q=true;
      else if(ch==="\t" || (ch==="," && !tabbed)) { out.push(cur.trim()); cur=""; }
      else cur+=ch;
    }
  }
  out.push(cur.trim());
  return out;
}
/* One CSV cell. A cell starting = + - @ (or a tab / return) would run as a formula when
   the file is opened in Excel, so it gets a leading apostrophe, which Excel shows as plain
   text. Plain numbers such as -1.5 or +0.7 are left alone. */
function csvSafe(v){
  if(typeof v === "number") return String(v);
  const s = String(v==null?"":v);
  if(/^[=+\-@\t\r]/.test(s) && !/^[+\-]?\d+(\.\d+)?%?$/.test(s)) return "'" + s;
  return s;
}
function csvCell(v){
  const s = csvSafe(v);
  return /[",\n\r]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s;
}
function downloadBlob(name, content, type){
  /* exports use this school's own name in their headings */
  if(typeof content === "string" && /csv/.test(type || "") && typeof schoolText === "function"){
    const nl = content.indexOf("\n"); content = nl < 0 ? schoolText(content) : schoolText(content.slice(0, nl)) + content.slice(nl);
  }
  const blob = new Blob([content], {type:type||"text/plain;charset=utf-8"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(function(){ URL.revokeObjectURL(url); }, 1500);
}
function normaliseName(s){
  return String(s||"").toLowerCase().replace(/[^a-z\s]/g,"").replace(/\s+/g," ").trim();
}
function nameKeys(name){
  const n = normaliseName(name);
  const parts = n.split(" ");
  const keys = [n];
  if(parts.length>1) keys.push(parts.slice(1).join(" ")+" "+parts[0]);
  return keys;
}
function findPupilByName(name){
  const keys = nameKeys(name);
  for(let i=0;i<state.pupils.length;i++){
    const pk = nameKeys(state.pupils[i].name);
    for(let a=0;a<keys.length;a++) for(let b=0;b<pk.length;b++) if(keys[a]===pk[b]) return state.pupils[i];
  }
  return null;
}
function parseDobCell(v){
  const s = String(v||"").trim();
  if(!s) return "";
  let m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
  if(m) return m[3]+"-"+m[2].padStart(2,"0")+"-"+m[1].padStart(2,"0");
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(m) return s;
  return "";
}
function truthy(v){ return /^(y|yes|true|1|x)$/i.test(String(v||"").trim()); }

function exportFlagsCsv(){
  const rows = buildFlagRows();
  const sums = pupilSummaries(rows);
  const flagged = rows.filter(function(r){ return r.eval.status==="concern"||r.eval.status==="watch"||r.cmp.status==="decline"; });
  const head = ["Pupil","Surname","First name","UPN","Year","Class","Tutor","DOB","Age","Start date","Time at RMS"]
    .concat(MARKERS.map(function(m){ return m[1]; }))
    .concat(["Subject","Assessment","Data drop","Result","Status","Movement","Evidence",
             "Priority pupil","Concern flags","Declines"]);
  const lines = [head.map(csvCell).join(",")];
  flagged.forEach(function(r){
    const s = sums[r.pupil.id], p = r.pupil;
    lines.push([p.name, p.surname||"", p.firstName||"", p.upn, p.year, p.group, p.tutor||"",
      p.dob ? fmtDate(p.dob) : "", currentAge(p), p.startDate ? fmtDate(p.startDate) : "", timeAtSchool(p)]
      .concat(MARKER_KEYS.map(function(k){ return p[k] ? "Y" : ""; }))
      .concat([r.assessment.subject, r.assessment.name, r.dp.name, r.eval.display||r.result.value,
        {concern:"Concern",watch:"Watch",secure:"Secure",na:""}[r.eval.status]||"",
        {decline:"Declining",stalled:"Stalled",progress:"Progress",na:"First entry"}[r.cmp.status]||"",
        (r.eval.detail + (r.cmp.detail? " · "+r.cmp.detail : "")),
        s&&s.priority?"Y":"", s?s.concerns:0, s?s.declines:0])
      .map(csvCell).join(","));
  });
  downloadBlob("flagged_pupils_"+state.meta.academicYear.replace(/[^0-9a-z\-]/gi,"")+".csv", lines.join("\n"), "text/csv;charset=utf-8");
}
function exportAllCsv(){
  const head = ["Pupil","UPN","Year","Group","Assessment","Subject","Data drop","Date","Result","Status","Evidence"];
  const lines = [head.map(csvCell).join(",")];
  orderedDataPoints().forEach(function(dp){
    state.pupils.forEach(function(p){
      state.assessments.forEach(function(a){
        const r = resultFor(p.id,a.id,dp.id);
        if(!r||r.value==="") return;
        const ev = evaluate(p,a,r,dp);
        lines.push([p.name,p.upn,p.year,p.group,a.name,a.subject,dp.name,dp.date,r.value,
          {concern:"Concern",watch:"Watch",secure:"Secure",na:""}[ev.status]||"",ev.detail].map(csvCell).join(","));
      });
    });
  });
  downloadBlob("all_results_"+state.meta.academicYear.replace(/[^0-9a-z\-]/gi,"")+".csv", lines.join("\n"), "text/csv;charset=utf-8");
}

/* ---------------- importing an old data file ---------------- */
/* Accepts either the tracker_data.js wrapper or a plain JSON export. */
function parsePayload(text){
  const s = String(text||"").trim();
  try { return migrate(JSON.parse(s)); } catch(e){}
  const m = s.match(/window\.TRACKER_DATA\s*=\s*([\s\S]*?);?\s*$/);
  if(m){
    let body = m[1].trim().replace(/;$/,"");
    try { return migrate(JSON.parse(body)); } catch(e){}
  }
  return null;
}
function report(hostId, msg, kind){
  const el = document.getElementById(hostId);
  if(!el) return;
  el.innerHTML = '<div class="warn" style="margin-top:12px'+(kind==="ok"?';background:var(--secure-bg);border-color:var(--secure-line);color:var(--secure)':'')+'">'+esc(msg)+'</div>';
}

/* ======================= PATHWAYS (AAA) =======================
   Attain · Attune to Learn · Attune to School · Attend. Each pupil's current
   pathway is kept on the Pupils list; every update is a dated entry in the
   PathwayLog list with a reason, notes, the action taken and who logged it. */
const PATHWAYS = ["attain", "attune_learn", "attune_school", "attend"];
const PATHWAY_LABELS = {attain:"Attain", attune_learn:"Attune to Learn", attune_school:"Attune to School", attend:"Attend"};
const PATHWAY_DESC = {
  attain: "Positive pathway apparent. On track for core GCSEs (English x2, Maths, Science) plus 4 options subjects (GCSE-equivalent).",
  attune_school: "Pathway of concern: attuning to school. Behaviour, attendance and/or emotional regulation are getting in the way of being settled and present.",
  attune_learn: "Pathway of concern: attuning to learning. Settled in school but not yet engaging consistently with the curriculum; complemented with vocational options.",
  attend: "Major attendance issues or non-attendance. Focus: securing some qualifications and keeping them in education."
};
const PATHWAY_COLOURS = {attain:["var(--secure)","var(--secure-bg)","var(--secure-line)"], attune_learn:["var(--above)","var(--above-bg)","var(--above-line)"],
                         attune_school:["var(--watch)","var(--watch-bg)","var(--watch-line)"], attend:["var(--concern)","var(--concern-bg)","var(--concern-line)"]};
const PATHWAY_REASONS = [
  ["academic_progress","Academic progress — on track for GCSEs"],
  ["academic_concern","Academic concern — falling behind target grades"],
  ["attendance_up","RPI up"], ["attendance_down","RPI down"],
  ["behaviour_positive","Behaviour positive"], ["behaviour_concern","Behaviour negative"],
  ["wellbeing_concern","Emotional wellbeing concern (Motional snapshot)"],
  ["clinical_welfare","Clinical / welfare intervention"], ["ehcp_provision","EHCP / provision change"],
  ["curriculum_change","Curriculum or options pathway change"], ["family_home","Family / home circumstances"],
  ["engagement_up","Engagement improved"], ["engagement_down","Engagement declined"],
  ["review","Review — no change"], ["other","Other (please specify in notes)"], ["imported","Imported baseline"]
];
function reasonLabel(code){ for(let i=0;i<PATHWAY_REASONS.length;i++) if(PATHWAY_REASONS[i][0]===code) return PATHWAY_REASONS[i][1]; return code || ""; }
function pathwayTag(pw, small){
  if(!pw || !PATHWAY_COLOURS[pw]) return '<span class="tag t-none">No pathway</span>';
  const c = PATHWAY_COLOURS[pw];
  return '<span class="tag" style="color:'+c[0]+';background:'+c[1]+';border-color:'+c[2]+(small?';font-weight:600':'')+'">'+esc(PATHWAY_LABELS[pw])+'</span>';
}
function logsFor(pid){
  const m = memoMap("logs");
  if(m){
    if(!m.has("")){ const by = {}; (state.pathwayLogs||[]).forEach(function(l){ (by[l.pupilId] = by[l.pupilId] || []).push(l); });
      Object.keys(by).forEach(function(k){ by[k].sort(function(a, b){ return String(b.ts).localeCompare(String(a.ts)); }); }); m.set("", by); }
    return (m.get("")[pid] || []).slice();
  }
  return (state.pathwayLogs||[]).filter(function(l){ return l.pupilId===pid; })
    .sort(function(a, b){ return String(b.ts).localeCompare(String(a.ts)); });
}
/* the pathway a pupil was on at a date: the last logged change on or before it */
function pathwayAt(pid, dateStr){ return memoGet("pwa", pid + "|" + (dateStr || ""), function(){ return pathwayAt__raw(pid, dateStr); }); }
function pathwayAt__raw(pid, dateStr){
  const p = byId(state.pupils, pid);
  if(!dateStr) return p ? (p.pathway || "") : "";
  const end = String(dateStr).slice(0,10) + "T23:59:59";
  const logs = logsFor(pid).slice().reverse();      /* oldest first */
  let pw = null;
  logs.forEach(function(l){ if(String(l.ts) <= end) pw = l.to; });
  if(pw!=null) return pw;
  if(logs.length) return logs[0].from || logs[0].to || "";
  return p ? (p.pathway || "") : "";
}
function lastRealLog(pid){ return logsFor(pid).filter(function(l){ return l.reason!=="imported"; })[0] || null; }
function daysSinceIso(iso){ const d = new Date(iso); return isNaN(d) ? null : Math.max(0, Math.floor((Date.now() - d) / 86400000)); }

let aaaYear = "", aaaStaleOnly = false, aaaPupil = null, aaaChoice = null;
function renderPathways(){
  const host = document.getElementById("aaaBoard");
  if(!host) return;
  const note = document.getElementById("aaaSetupNote");
  if(note) note.innerHTML = spLegacy && hasSheet() ? needsSetupHtml() : "";
  const c = curCfg();
  const yrs = {};
  state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) yrs[String(p.year)] = true; });
  const yl = Object.keys(yrs).sort(function(a,b){ return yearSortKey(b)-yearSortKey(a); });
  document.getElementById("aaaYears").innerHTML = ['<button data-aaayear=""'+(aaaYear===""?' class="on"':'')+'>Whole school</button>']
    .concat(yl.map(function(y){ return '<button data-aaayear="'+esc(y)+'"'+(aaaYear===y?' class="on"':'')+'>Year '+esc(y)+'</button>'; })).join("");
  document.getElementById("aaaStale").checked = aaaStaleOnly;
  const q = String(document.getElementById("aaaSearch").value||"").toLowerCase();
  const isStale = function(p){ const l = lastRealLog(p.id); const d = l ? daysSinceIso(l.ts) : null; return d==null || d > c.staleDays; };
  let pupils = state.pupils.filter(function(p){ return !aaaYear || String(p.year)===aaaYear; });
  const base = pupils.slice();
  if(q) pupils = pupils.filter(function(p){ return String(p.name).toLowerCase().indexOf(q) >= 0; });
  if(aaaStaleOnly) pupils = pupils.filter(isStale);
  /* tiles */
  const count = function(pw){ return base.filter(function(p){ return (p.pathway||"")===pw; }).length; };
  const since = Date.now() - 30*86400000;
  const moves = (state.pathwayLogs||[]).filter(function(l){ return l.from && l.to && l.from!==l.to && l.reason!=="imported" && new Date(l.ts) >= since &&
    base.some(function(p){ return p.id===l.pupilId; }); }).length;
  document.getElementById("aaaStats").innerHTML = PATHWAYS.map(function(pw){
      const col = PATHWAY_COLOURS[pw];
      return '<div class="stat" style="border-top-color:'+col[0]+'"><div class="n" style="color:'+col[0]+'">'+count(pw)+'</div><div class="l">'+esc(PATHWAY_LABELS[pw])+'</div></div>';
    }).join("")+
    '<div class="stat"><div class="n">'+moves+'</div><div class="l">Pathway changes in the last 30 days</div></div>'+
    '<div class="stat'+(base.filter(isStale).length ? ' watch' : '')+'"><div class="n">'+base.filter(isStale).length+'</div><div class="l">No update for '+c.staleDays+'+ days</div></div>';
  renderAaaOverview(c);
  /* board */
  const idx = curIndex();
  const sums = pupilSummaries(buildFlagRows());
  const gaps = gapInfo(currentGapKey());
  const card = function(p){
    const l = lastRealLog(p.id);
    const d = l ? daysSinceIso(l.ts) : null;
    const stale = d==null || d > c.staleDays;
    const cc = curConcerns(p, idx);
    const s = sums[p.id];
    const miss = (gaps.byPupil[p.id]||[]).length;
    return '<button class="aaacard'+(stale?' stale':'')+'" data-aaa-pupil="'+p.id+'" draggable="true" data-drag-pupil="'+p.id+'">'+
      '<b>'+esc(p.name)+'</b><span class="muted">Year '+esc(p.year)+' · '+(d==null ? 'never updated' : (d===0 ? 'updated today' : 'updated '+d+' day'+(d===1?'':'s')+' ago'))+'</span>'+
      '<span class="chips">'+
        (cc.length ? '<span class="chip" style="background:var(--watch-bg);color:var(--watch)">Behind in '+cc.length+' subject'+(cc.length===1?'':'s')+'</span>' : '')+
        (s && s.priority ? '<span class="chip" style="background:var(--concern-bg);color:var(--concern)">Priority</span>' : (s && s.concerns ? '<span class="chip">'+s.concerns+' concern flag'+(s.concerns===1?'':'s')+'</span>' : ''))+
        (miss ? '<span class="chip miss">'+miss+' missing</span>' : '')+
        (p.partTime ? '<span class="chip">Part-time</span>' : '')+
      '</span></button>';
  };
  const cols = PATHWAYS;
  const unset = pupils.filter(function(p){ return !p.pathway; }).sort(function(a,b){ return yearSortKey(b.year)-yearSortKey(a.year) || String(a.name).localeCompare(String(b.name)); });
  host.innerHTML = '<div class="aaacols">'+cols.map(function(pw){
    const list = pupils.filter(function(p){ return (p.pathway||"")===pw; }).sort(function(a,b){ return String(a.name).localeCompare(String(b.name)); });
    const col = PATHWAY_COLOURS[pw] || ["var(--ink-soft)","var(--hover)","var(--line)"];
    return '<div class="aaacol" data-dropcol="'+pw+'"><div class="aaacolhead" style="border-top-color:'+col[0]+'"><b style="color:'+col[0]+'">'+esc(pw ? PATHWAY_LABELS[pw] : "No pathway yet")+'</b>'+
      '<span class="chip">'+list.length+'</span></div>'+
      (pw ? '<p class="hint" style="margin:0 0 8px">'+esc(PATHWAY_DESC[pw])+'</p>' : '<p class="hint" style="margin:0 0 8px">Open a pupil and log their pathway.</p>')+
      (list.length ? list.map(card).join("") : '<div class="empty" style="padding:14px">Nobody</div>')+'</div>';
  }).join("")+'</div>'+
  (unset.length ? '<div class="panel" style="margin-top:12px"><div class="panelhead"><h2>No pathway yet</h2><span class="chip">'+unset.length+'</span></div>'+
    '<p class="hint">Click a name to set their pathway.</p><div class="chips">'+unset.map(function(p){
      return '<button class="chip" style="border:1px solid var(--line-strong);cursor:pointer;background:var(--panel)" data-aaa-pupil="'+p.id+'">'+esc(p.name)+' <span class="muted">Y'+esc(p.year)+'</span></button>';
    }).join("")+'</div></div>' : '');
  /* recent changes */
  const recent = (state.pathwayLogs||[]).filter(function(l){ return l.reason!=="imported" && base.some(function(p){ return p.id===l.pupilId; }); })
    .sort(function(a,b){ return String(b.ts).localeCompare(String(a.ts)); }).slice(0, 15);
  document.getElementById("aaaRecent").innerHTML = recent.length
    ? '<table><thead><tr><th>When</th><th>Pupil</th><th>Pathway</th><th>Reason</th><th>Action</th><th>By</th></tr></thead><tbody>'+
      recent.map(function(l){
        const p = byId(state.pupils, l.pupilId);
        return '<tr><td>'+esc(fmtDateTime(l.ts))+'</td><td><button class="linkbtn" data-aaa-pupil="'+l.pupilId+'">'+esc(p ? p.name : l.pupilId)+'</button></td>'+
          '<td>'+(l.from && l.from!==l.to ? pathwayTag(l.from, true)+' → ' : '')+pathwayTag(l.to, true)+'</td>'+
          '<td class="evidence">'+esc(reasonLabel(l.reason))+(l.notes ? '<br>'+esc(l.notes) : '')+'</td><td class="evidence">'+esc(l.action)+'</td><td>'+esc(l.staff)+'</td></tr>';
      }).join("")+'</tbody></table>'
    : '<div class="empty">No updates logged yet.</div>';
}

/* AAA overview: every year group side by side, and this year's moves */
let aaaMoveSel = "";
function pwBar(counts, total){
  if(!total) return '<div class="bar"></div>';
  return '<div class="bar">'+PATHWAYS.map(function(pw){
    const n = counts[pw]||0; if(!n) return "";
    return '<span style="width:'+(n/total*100).toFixed(1)+'%;background:'+PATHWAY_COLOURS[pw][0]+'" title="'+esc(PATHWAY_LABELS[pw])+' '+n+'"></span>';
  }).join("")+(counts[""] ? '<span style="width:'+(counts[""]/total*100).toFixed(1)+'%;background:var(--line-strong)" title="No pathway '+counts[""]+'"></span>' : '')+'</div>';
}
function renderAaaOverview(c){
  const host = document.getElementById("aaaOverview");
  if(!host) return;
  const ay = currentAY(), start = ayStartDate(ay);
  const moves = (state.pathwayLogs||[]).filter(function(l){ return isRealMove(l) && String(l.ts).slice(0,10) >= start; });
  const yrs = {};
  state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) yrs[String(p.year)] = true; });
  const yl = Object.keys(yrs).sort(function(a,b){ return yearSortKey(b)-yearSortKey(a); });
  const whole = {}; state.pupils.forEach(function(p){ whole[p.pathway||""] = (whole[p.pathway||""]||0) + 1; });
  const ycards = yl.map(function(y){
    const ps = state.pupils.filter(function(p){ return String(p.year)===y; });
    const cnt = {}; ps.forEach(function(p){ cnt[p.pathway||""] = (cnt[p.pathway||""]||0) + 1; });
    const ids = {}; ps.forEach(function(p){ ids[p.id] = true; });
    const ym = moves.filter(function(l){ return ids[l.pupilId]; });
    const up = ym.filter(function(l){ return moveDir(l)==="up"; }).length, dn = ym.length - up;
    const onA = ps.length ? Math.round((cnt.attain||0)/ps.length*100) : 0;
    return '<button class="yrcard'+(aaaYear===y?' on':'')+'" data-aaayear="'+(aaaYear===y?'':esc(y))+'"><b>Year '+esc(y)+'</b> <span class="muted">· '+ps.length+' pupils</span>'+
      pwBar(cnt, ps.length)+
      '<small>'+PATHWAYS.map(function(pw){ return '<span style="color:'+PATHWAY_COLOURS[pw][0]+'">'+esc(PATHWAY_LABELS[pw].replace("Attune to ","Att. "))+' '+(cnt[pw]||0)+'</span>'; }).join(" · ")+'</small>'+
      '<small>'+onA+'% Attain · this year <span style="color:var(--secure)">↑'+up+'</span> <span style="color:var(--concern)">↓'+dn+'</span></small></button>';
  }).join("");
  const pairs = {};
  moves.forEach(function(l){ const k = l.from+">"+l.to; pairs[k] = (pairs[k]||0) + 1; });
  const keys = Object.keys(pairs).sort(function(a,b){ return pairs[b]-pairs[a]; });
  if(aaaMoveSel && !pairs[aaaMoveSel]) aaaMoveSel = "";
  const chips = keys.map(function(k){
    const pr = k.split(">"), dir = PW_RANK[pr[1]] > PW_RANK[pr[0]] ? "up" : "down";
    return '<button class="movechip '+dir+(aaaMoveSel===k?' on':'')+'" data-aaamove="'+esc(k)+'">'+esc(PATHWAY_LABELS[pr[0]])+' → '+esc(PATHWAY_LABELS[pr[1]])+' <b>'+pairs[k]+'</b></button>';
  }).join("");
  const up = moves.filter(function(l){ return moveDir(l)==="up"; }).length;
  let who = "";
  if(aaaMoveSel){
    const pr = aaaMoveSel.split(">");
    who = '<div class="tablewrap" style="margin-top:10px"><table><thead><tr><th>When</th><th>Pupil</th><th>Reason</th><th>Action</th><th>By</th></tr></thead><tbody>'+
      moves.filter(function(l){ return l.from===pr[0] && l.to===pr[1]; }).sort(function(a,b){ return String(b.ts).localeCompare(String(a.ts)); }).map(function(l){
        const p = byId(state.pupils, l.pupilId);
        return '<tr><td>'+esc(fmtDate(l.ts))+'</td><td><button class="linkbtn" data-aaa-pupil="'+l.pupilId+'">'+esc(p ? p.name : l.pupilId)+'</button> <span class="muted">'+(p ? 'Y'+esc(p.year) : '')+'</span></td>'+
          '<td class="evidence">'+esc(reasonLabel(l.reason))+(l.notes && l.notes!=="." ? '<br>'+esc(l.notes) : '')+'</td><td class="evidence">'+esc(l.action==="." ? "" : l.action)+'</td><td>'+esc(l.staff)+'</td></tr>';
      }).join("")+'</tbody></table></div>';
  }
  host.innerHTML = '<div class="aaaov">'+
    '<div class="panel"><h2>Year groups side by side</h2>'+
      '<p class="hint" style="margin:4px 0 0">Whole school: '+state.pupils.length+' pupils.</p>'+pwBar(whole, state.pupils.length)+
      '<div class="yrcards">'+ycards+'</div><p class="hint" style="margin:8px 0 0">Click a year group to filter the board; click it again for the whole school.</p></div>'+
    '<div class="panel"><h2>Moves this year</h2>'+
      (moves.length ? '<p class="hint" style="margin:4px 0 0">'+moves.length+' pathway move'+(moves.length===1?'':'s')+' since 1 September: <span style="color:var(--secure)">'+up+' towards Attain</span>, <span style="color:var(--concern)">'+(moves.length-up)+' away</span>. Click a pair to see who and why.</p>'+
        '<div class="movechips">'+chips+'</div>'+who
        : '<p class="hint">No pathway moves logged this academic year yet.</p>')+'</div>'+
    '</div>';
}
/* pupil panel: log an update, see the history */
function openPathwayPanel(pid){
  const p = byId(state.pupils, pid);
  if(!p) return;
  draft = null;
  aaaPupil = pid;
  aaaChoice = p.pathway || "attain";
  renderPathwayPanel();
  document.getElementById("drawer").classList.add("open");
  document.getElementById("drawer").setAttribute("aria-hidden","false");
  document.getElementById("drawerScrim").classList.add("open");
}
function renderPathwayPanel(){
  const p = byId(state.pupils, aaaPupil);
  if(!p) return;
  const now = new Date();
  const pad = function(n){ return String(n).padStart(2,"0"); };
  const local = now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate())+"T"+pad(now.getHours())+":"+pad(now.getMinutes());
  const cc = curConcerns(p);
  document.getElementById("drawerTitle").textContent = p.name;
  document.getElementById("drawerBody").innerHTML =
    '<div class="chips" style="margin-bottom:6px"><span class="chip">Year '+esc(p.year)+'</span>'+pathwayTag(p.pathway)+
      markersShown(p).map(function(k){ return '<span class="chip">'+esc(markerChip(k))+'</span>'; }).join("")+'</div>'+
    (cc.length ? '<div class="warn" style="margin:8px 0">Behind in '+cc.map(function(x){ return esc(x.su.name)+(x.status==="well"?' (well behind)':''); }).join(", ")+'.</div>' : '')+
    (p.pathway && aaaChoice && aaaChoice!==p.pathway ? '<div class="warn info" style="margin:8px 0"><strong>Moving</strong> '+pathwayTag(p.pathway, true)+' → '+pathwayTag(aaaChoice, true)+'. Choose a reason, then <strong>Save log entry</strong>.</div>' : '')+
    '<div class="dsec"><h3>Log an update</h3>'+
      '<div class="pathpick">'+PATHWAYS.map(function(pw){
        const c = PATHWAY_COLOURS[pw];
        return '<button type="button" data-aaapw="'+pw+'" class="'+(aaaChoice===pw?'on':'')+'" style="--pc:'+c[0]+';--pb:'+c[1]+'">'+esc(PATHWAY_LABELS[pw])+'</button>';
      }).join("")+'</div>'+
      '<div class="row" style="margin-top:10px">'+
        '<label class="fld" style="flex:1;min-width:240px">Reason<select id="aaaReason"><option value="">Choose…</option>'+
          PATHWAY_REASONS.filter(function(r){ return r[0]!=="imported"; }).map(function(r){ return '<option value="'+r[0]+'">'+esc(r[1])+'</option>'; }).join("")+'</select></label></div>'+
      '<label class="fld" style="margin-bottom:10px">Notes <small>optional</small><textarea id="aaaNotes" rows="2" style="width:100%"></textarea></label>'+
      '<label class="fld" style="margin-bottom:10px">What we’re doing about it<textarea id="aaaAction" rows="2" style="width:100%"></textarea></label>'+
      '<div class="row"><label class="fld">Logged by<input id="aaaStaff" value="'+esc(whoAmI() || (ENTRY_MODE && entryMeRec ? entryMeRec.name : ""))+'" style="width:120px"></label>'+
        '<label class="fld">Date and time<input id="aaaWhen" type="datetime-local" value="'+local+'"></label></div>'+
      (ENTRY_MODE ? '<p class="hint" style="margin-top:8px">Saved straight away. SLT see it in the AAA log, marked as from staff entry.</p>' : '')+
    '</div>'+
    '<div class="dsec"><h3>History</h3>'+(logsFor(p.id).length ? logsFor(p.id).map(function(l){
      return '<div class="histitem"><div><b>'+esc(fmtDateTime(l.ts))+'</b> · '+(l.from && l.from!==l.to ? pathwayTag(l.from, true)+' → ' : '')+pathwayTag(l.to, true)+
        (l.staff ? ' <span class="muted">by '+esc(l.staff)+'</span>' : '')+(/^staff/.test(l.type || "") ? ' <span class="tag t-none">staff entry</span>' : '')+'</div>'+
        '<div class="evidence">'+esc(reasonLabel(l.reason))+(l.notes ? ' — '+esc(l.notes) : '')+'</div>'+
        (l.action ? '<div class="evidence"><strong>Action:</strong> '+esc(l.action)+'</div>' : '')+'</div>';
    }).join("") : '<p class="hint">Nothing logged yet.</p>')+'</div>';
  document.getElementById("drawerFoot").innerHTML =
    '<button class="btn" data-act="aaa-save">Save log entry</button><button class="btn ghost" data-act="drawer-close">Close</button>'+
    (ENTRY_MODE ? '' : '<span class="spacer"></span><button class="btn subtle" data-goto-pupil="'+p.id+'">Open profile</button>');
}
/* Staff can't change the Pupils list, so an update logged in staff entry moves the pupil's
   pathway through the PathwayLog list: when the newest entry for a pupil came from staff
   entry, that entry decides the pathway shown (the next save from the main tracker writes it
   to the Pupils list too). */
function pathwaysFromStaff(st){
  const latest = {};
  (st.pathwayLogs || []).forEach(function(l){ const c = latest[l.pupilId]; if(!c || String(l.ts) > String(c.ts)) latest[l.pupilId] = l; });
  /* in staff entry, a pupil with no pathway on the class list (an older copy of the tracker saved it without)
     takes the pathway from their newest AAA log entry */
  (st.pupils || []).forEach(function(p){ const l = latest[p.id]; if(!l) return; const to = typeof migratePw === "function" ? migratePw(l.to) : l.to;
    if(to && PATHWAYS.indexOf(to) >= 0 && (/^staff/.test(l.type || "") || (ENTRY_MODE && !p.pathway))) p.pathway = to; });
}
function savePathwayLog(){
  const p = byId(state.pupils, aaaPupil);
  if(!p) return;
  if(ENTRY_MODE && entryAaaOff){ alert("This update can\u2019t be saved: staff entry can\u2019t open the PathwayLog list. Ask SLT to give staff access to it."); return; }
  if(spLegacy && hasSheet()){ alert("Run Settings & data \u2192 Set up the SharePoint lists first, so pathway logs have somewhere to be saved."); return; }
  const reason = document.getElementById("aaaReason").value;
  if(!reason){ alert("Choose a reason."); return; }
  const when = document.getElementById("aaaWhen").value;
  const ts = when ? new Date(when).toISOString() : new Date().toISOString();
  const staff = String(document.getElementById("aaaStaff").value||"").trim();
  if(staff && !whoAmI()) setWho(staff);
  const from = p.pathway || "";
  state.pathwayLogs = state.pathwayLogs || [];
  state.pathwayLogs.push({id:uid("lg"), pupilId:p.id, ts:ts, from:from, to:aaaChoice, reason:reason,
    notes:String(document.getElementById("aaaNotes").value||"").trim(), action:String(document.getElementById("aaaAction").value||"").trim(),
    staff:staff, type: (ENTRY_MODE ? "staff-" : "") + (from!==aaaChoice ? "change" : "review")});
  /* only the newest entry decides the pathway shown now */
  const latest = logsFor(p.id)[0];
  p.pathway = latest ? latest.to : aaaChoice;
  markDirty();
  renderAll();
  renderPathwayPanel();
  if(ENTRY_MODE) toast(p.name + ": " + PATHWAY_LABELS[p.pathway] + (from && from !== p.pathway ? " (was " + PATHWAY_LABELS[from] + ")" : "") + ". Saving…", "ok");
}
function profilePathwayHtml(p){
  const logs = logsFor(p.id);
  return '<h3>AAA pathway</h3><div class="row" style="align-items:center;margin-bottom:8px">'+pathwayTag(p.pathway)+
    '<button class="btn ghost sm noprint" data-aaa-pupil="'+p.id+'">Log update</button></div>'+
    (logs.length ? '<div class="tablewrap"><table><thead><tr><th>When</th><th>Pathway</th><th>Reason</th><th>Action</th><th>By</th></tr></thead><tbody>'+
      logs.slice(0, 8).map(function(l){
        return '<tr><td>'+esc(fmtDateTime(l.ts))+'</td><td>'+(l.from && l.from!==l.to ? pathwayTag(l.from, true)+' → ' : '')+pathwayTag(l.to, true)+'</td>'+
          '<td class="evidence">'+esc(reasonLabel(l.reason))+(l.notes ? '<br>'+esc(l.notes) : '')+'</td><td class="evidence">'+esc(l.action)+'</td><td>'+esc(l.staff)+'</td></tr>';
      }).join("")+'</tbody></table></div>' : '<p class="hint">No pathway logged yet.</p>');
}
function exportPathwayCsv(){
  const lines = [["When","Pupil","Year","From","To","Reason","Notes","Action","Logged by"].map(csvCell).join(",")];
  (state.pathwayLogs||[]).slice().sort(function(a,b){ return String(a.ts).localeCompare(String(b.ts)); }).forEach(function(l){
    const p = byId(state.pupils, l.pupilId);
    lines.push([fmtDateTime(l.ts), p ? p.name : l.pupilId, p ? p.year : "", PATHWAY_LABELS[l.from]||"", PATHWAY_LABELS[l.to]||"",
      reasonLabel(l.reason), l.notes, l.action, l.staff].map(csvCell).join(","));
  });
  downloadBlob("aaa_pathway_log.csv", lines.join("\n"), "text/csv;charset=utf-8");
}
/* Import the AAA tracker's backup (.json): pathways and logs, matched to pupils by name */
function importAaaBackup(text){
  let j = null;
  try { j = JSON.parse(text); } catch(e){}
  /* the AAA tracker's backup wraps everything in "state"; older ones didn't */
  const pick = function(o){ return o && Array.isArray(o.students) ? o : null; };
  j = pick(j) || pick(j && j.state) || pick(j && j.data) || pick(j && j.state && j.state.state);
  if(!j) return {error:"That isn’t an AAA tracker backup (it needs a list of students)."};
  if(!Array.isArray(j.logs)) j.logs = [];
  /* each student's _lastLog may not be in the logs list, so fold those in too */
  const seenLog = {};
  j.logs.forEach(function(l){ if(l && l.id) seenLog[l.id] = true; });
  j.students.forEach(function(st){
    const l = st && st._lastLog;
    if(l && l.id && !seenLog[l.id]){ j.logs.push(Object.assign({studentId:st.id}, l)); seenLog[l.id] = true; }
  });
  const gone = function(st){ return st.status==="left" || st.status==="archived"; };
  const map = {}, unmatched = [], skipped = [];
  j.students.forEach(function(st){
    if(!st || !st.name) return;
    const p = findPupilByName(st.name);
    if(p) map[st.id] = p; else if(gone(st)) skipped.push(st.name); else unmatched.push(st.name);
  });
  const migratePw = function(x){ return x==="attune" ? "attune_school" : (x||""); };
  state.pathwayLogs = state.pathwayLogs || [];
  const have = {};
  state.pathwayLogs.forEach(function(l){ have[l.id] = true; });
  let added = 0, set = 0;
  j.logs.forEach(function(l){
    const p = map[l.studentId];
    if(!p) return;
    const id = "lg_" + String(l.id || uid("x")).replace(/^l_/, "");
    if(have[id]) return;
    state.pathwayLogs.push({id:id, pupilId:p.id, ts:l.ts || "", from:migratePw(l.fromPathway), to:migratePw(l.toPathway),
      reason:l.reasonCode || "", notes:l.notes || "", action:l.action || "", staff:l.staff || "", type:l.type || "update"});
    have[id] = true; added++;
  });
  j.students.forEach(function(st){
    const p = map[st.id];
    if(!p || gone(st)) return;
    const pw = migratePw(st.pathway);
    if(pw && p.pathway!==pw){ p.pathway = pw; set++; }
  });
  markDirty();
  return {matched:Object.keys(map).length, unmatched:unmatched, skipped:skipped, added:added, set:set};
}

/* ======================= ATTAINMENT, DISTANCE TRAVELLED, GCSE PROJECTION =======================
   Levels are curriculum stages: Level N is the Year N standard, E at the start of
   the year, S by the end. So a pupil's age-related level (ARE) rises from YE in
   September to YS in July, and "years behind" = ARE - working-at level (1 level = 1 year).
   Projected GCSE: carry each pupil on at their own pace (or the expected pace) to the
   end of Year 9, see how far behind the Year 9 standard they would be, and read the
   likely grade off the table below. The table follows the national KS2 -> GCSE pattern
   (DfE transition matrices, English language 2022/23): pupils at the expected standard
   at 11 had a median grade 4, around a year behind a median 3, two or more years behind
   a median 2. It is editable in Settings & data. */
const GCSE_MAP_DEFAULT = "7:-1.67,6:-1,5:-0.34,4:0.34,3:1.34,2:2.34,1:3.5";
function gcseMapRows__raw(){
  const s = String(curCfg().gcseMap || GCSE_MAP_DEFAULT);
  const rows = s.split(",").map(function(x){ const m = x.split(":"); return {g:String(m[0]).trim(), max:parseFloat(m[1])}; })
    .filter(function(r){ return r.g && !isNaN(r.max); }).sort(function(a,b){ return a.max - b.max; });
  return rows.length ? rows : GCSE_MAP_DEFAULT.split(",").map(function(x){ const m = x.split(":"); return {g:m[0], max:parseFloat(m[1])}; });
}
function gcseFromBehind(yb){
  if(yb==null || isNaN(yb)) return null;
  const rows = gcseMapRows();
  for(let i=0;i<rows.length;i++) if(yb <= rows[i].max) return rows[i].g;
  return "U";
}
/* how far through the school year a date is: 0 on 1 September, 1 by 20 July */
function ayFraction__raw(dateStr){
  const d = new Date(dateStr || new Date());
  if(isNaN(d)) return 0;
  const y = d.getMonth() >= 8 ? d.getFullYear() : d.getFullYear() - 1;
  const start = new Date(y, 8, 1), end = new Date(y + 1, 6, 20);
  return Math.max(0, Math.min(1, (d - start) / (end - start)));
}
/* the age-related level for a pupil on a date, e.g. 7E in September of Year 7, 7S by July */
function areAt__raw(p, dateStr){
  const y = parseInt(yearAt(p, acYearOf(dateStr) || currentAY()), 10);
  if(isNaN(y) || y < 1) return null;
  return y + (2/3) * ayFraction(dateStr);
}
function fmtYears(yb){
  if(yb==null || isNaN(yb)) return "—";
  const r = Math.round(yb * 10) / 10;
  if(Math.abs(r) < 0.2) return "at ARE";
  return Math.abs(r).toFixed(1) + (r > 0 ? " yrs behind" : " yrs ahead");
}
function behindClass(yb){ return yb==null ? "same" : (yb <= 0.34 ? "good" : (yb <= 1.34 ? "same" : "bad")); }
function behindHtml(yb){ return yb==null ? '<span class="muted">—</span>' : '<span class="delta '+behindClass(yb)+'">'+fmtYears(yb)+'</span>'; }
/* end of Year 9 (20 July) for a pupil, as a date string */
function endOfYear9(p){
  const y = parseInt(p.year, 10), s = ayStart(currentAY());
  if(isNaN(y) || s==null) return null;
  return (s + (9 - y) + 1) + "-07-20";
}
/* everything worth knowing about one pupil in one subject (levels only) */
function subjectMetrics__raw(p, su, idx, uptoDate){
  idx = idx || curIndex();
  const c = curCfg();
  const ser = levelSeries(p.id, su.id, idx, uptoDate);
  const base = baselineOf(p.id, su.id, idx);
  const o = {base:base, last:null, now:null, nowDate:null, gain:null, expGain:null, months:null, pace:null,
             behindNow:null, behindBase:null, gapChange:null, proj9:null, proj9Exp:null, gcse:null, gcseExp:null, are:null};
  if(!ser.length) return o;
  const last = ser[ser.length-1];
  o.last = last; o.nowScore = resultScore(last.r); o.now = scoreToLevel(o.nowScore); o.nowDate = last.dp.date; o.onGrades = isGradeResult(last.r);
  o.are = areAt(p, last.dp.date);
  if(o.are!=null && o.now!=null) o.behindNow = o.are - o.now;
  if(base){
    const bs = baseScore(base);
    const bv = scoreToLevel(bs), yrs = yearsBetween(base.date, last.dp.date);
    const bare = areAt(p, base.date);
    if(bare!=null && bv!=null) o.behindBase = bare - bv;
    if(o.behindBase!=null && o.behindNow!=null) o.gapChange = o.behindNow - o.behindBase;   /* negative = gap closing */
    if(yrs!=null && yrs > 0 && bs!=null && o.nowScore!=null){
      o.gain = o.nowScore - bs; o.expGain = c.rate * yrs; o.months = yrs * 12;
      /* V41: a pupil's own pace drives the projection only with enough evidence (at least
         paceMinDrops results over a year or more), and never above paceCap a year; otherwise
         the expected rate is used. One jumpy result can no longer move the grade by several. */
      const since = ser.filter(function(x){ return String(x.dp.date) >= String(base.date); }).length + (base.source === "set" ? 1 : 0);
      o.ownPaceOk = yrs >= 1 && since >= (c.paceMinDrops || CUR_DEFAULTS.paceMinDrops);
      if(o.ownPaceOk) o.pace = Math.max(0, Math.min(c.paceCap || CUR_DEFAULTS.paceCap, o.gain / yrs));
    }
    /* headline: progress rate before joining against the rate at RMS, both in levels a year.
       Before = the level on entry over the years of schooling before it (age on entry - 5);
       at RMS = levels moved since the baseline over the time since. 1.00 a year keeps pace with age;
       below that the gap to age-related expectation widens even if the rate has improved. */
    const ageAt = p.dob ? yearsBetween(p.dob, base.date) : null;
    const prior = ageAt!=null ? ageAt - 5 : null;
    if(prior!=null && prior >= 0.5 && bv!=null) o.preRate = Math.max(0, bv) / prior;
    if(yrs!=null && yrs >= 0.5 && bv!=null && o.now!=null) o.rmsRate = (o.now - bv) / yrs;
  }
  const e9 = endOfYear9(p);
  const y = parseInt(p.year, 10);
  /* V41: no GCSE projection before Year gcseProjFrom (7), or in subjects that aren't GCSEs */
  const projOk = !isNaN(y) && y >= (c.gcseProjFrom || CUR_DEFAULTS.gcseProjFrom) && isGcseSubject(su);
  o.projOk = projOk;
  const pace = o.pace!=null ? o.pace : c.rate;
  o.paceUsed = o.pace!=null ? "own" : "expected";
  if(o.onGrades){
    const g = gcseValue(last.r.value); o.gcse = g==null ? null : (g===0 ? "U" : String(g)); o.gcseFrom = "grade";
  } else if(projOk && e9 && y <= 9 && o.now!=null){
    const left = Math.max(0, yearsBetween(last.dp.date, e9) || 0);
    o.proj9 = scoreToLevel(o.nowScore + pace * left);
    o.proj9Exp = scoreToLevel(o.nowScore + c.rate * left);
    o.gcse = gcseFromBehind((9 + 2/3) - o.proj9);
    o.gcseExp = gcseFromBehind((9 + 2/3) - o.proj9Exp);
    o.gcseBand = gcseBandOf((9 + 2/3) - o.proj9);
  } else if(projOk && y >= 10 && o.now!=null){
    /* KS4 still on levels: carried on to the end of Year 11 and compared with the Year 11
       standard, the same way KS3 is compared with Year 9 (no longer capped at grade 4) */
    const e11 = (ayStart(currentAY()) + (11 - y) + 1) + "-07-20";
    const left = Math.max(0, yearsBetween(last.dp.date, e11) || 0);
    const end = 11 + 2/3;
    o.proj11 = o.nowScore + pace * left;
    o.gcse = gcseFromBehind(end - o.proj11);
    o.gcseExp = gcseFromBehind(end - (o.nowScore + c.rate * left));
    o.gcseBand = gcseBandOf(end - o.proj11);
    o.gcseFrom = "level";
  }
  return o;
}
function gcseRank(g){ if(g==null) return null; const s = String(g).toUpperCase(); return s==="U" ? 0 : (parseInt(s,10) || 0); }
/* a pupil's picture across subjects */
function pupilMetrics__raw(p, idx, subs){
  idx = idx || curIndex();
  subs = subs || (state.subjects||[]).filter(function(s){ return s.active; });
  const per = subs.map(function(su){ return {su:su, m:subjectMetrics(p, su, idx)}; }).filter(function(x){ return x.m.last; });
  const pick = function(k){ return per.map(function(x){ return x.m[k]; }).filter(function(v){ return v!=null; }); };
  return {per:per, preRate:avgOf(pick("preRate")), rmsRate:avgOf(pick("rmsRate")), gain:avgOf(pick("gain")), expGain:avgOf(pick("expGain")), behindNow:avgOf(pick("behindNow")),
          behindBase:avgOf(pick("behindBase")), gapChange:avgOf(pick("gapChange")), months:avgOf(pick("months")),
          gcse:avgOf(pick("gcse").map(gcseRank))};
}
function gcseHtml(g, gExp, band){
  if(g==null) return '<span class="muted">—</span>';
  const r = gcseRank(g);
  return '<span class="delta '+(r>=4?'good':(r>=3?'same':'bad'))+'"'+(band ? ' title="Within half a step of a grade boundary"' : '')+'>'+esc(String(band || g))+'</span>'+(gExp!=null && gExp!==g ? ' <span class="muted">(at '+curCfg().rate+': '+esc(String(gExp))+')</span>' : '');
}
/* a grade near a boundary is shown as a band ("3–4"): half a step either way changes it */
function gcseBandOf(yb){
  if(yb==null || isNaN(yb)) return null;
  const lo = gcseFromBehind(yb + 1/6), hi = gcseFromBehind(yb - 1/6);
  return lo === hi ? null : lo + "–" + hi;
}
/* "2E" -> "2": a predicted or target grade shown as a whole grade */
function gradeWhole(v){ const g = gcseValue(v); return g==null ? (v==null ? null : String(v)) : (g===0 ? "U" : String(g)); }
/* is this subject a GCSE? Ticked in Settings & data → Subjects; until then, worked out from the name */
const NON_GCSE_RE = /^(pshe|pse|rshe|reading|phonics|futures|tutor|citizenship|life ?skills|enrichment|forest|outdoor|careers|wellbeing|nurture|lexia|accelerated reader)\b/i;
function isGcseSubject(su){
  if(!su) return false;
  const list = curCfg().gcseSubs;
  if(Array.isArray(list)) return list.indexOf(su.id) >= 0;
  return !NON_GCSE_RE.test(String(su.name || "").trim());
}
function gcseSubjectIds(){ return (state.subjects || []).filter(isGcseSubject).map(function(s){ return s.id; }); }
function gapChangeHtml(d){
  if(d==null) return '<span class="muted">—</span>';
  const r = Math.round(d*10)/10;
  if(Math.abs(r) < 0.1) return '<span class="delta same">no change</span>';
  return r < 0 ? '<span class="delta good">closed '+Math.abs(r).toFixed(1)+' yrs</span>' : '<span class="delta bad">widened '+r.toFixed(1)+' yrs</span>';
}

/* ======================= CORE SUBJECTS DASHBOARD =======================
   English, maths and science (or whichever subjects are ticked as core) by AAA
   pathway and year group: attainment against age, progress since baseline, gap
   closing, and the likely GCSE grade (projected for KS3, predicted for KS4). */
let coreYear = "", corePw = "", coreFocus = null;
/* V41: every figure on Core subjects narrows the pupil-by-pupil table to the pupils behind it */
function coreFocusAttr(spec, label){ return ' data-corefocus="'+drillAttr(Object.assign({label:label}, spec))+'" role="button" tabindex="0" style="cursor:pointer" title="Click to see these pupils"'; }
function coreSubjects(){
  const subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const set = curCfg().core;
  const ids = Array.isArray(set) ? set : String(set||"").split(",").map(function(x){ return x.trim(); }).filter(Boolean);
  if(ids.length) return subs.filter(function(s){ return ids.indexOf(s.id) >= 0; });
  return subs.filter(function(s){ return /^(english|maths?|mathematics|science)\b/i.test(s.name); });
}
/* the English and maths subjects (by name), for headline measures */
function emSubjects(){
  const subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const en = subs.filter(function(s){ return /^english\b/i.test(s.name); })[0];
  const ma = subs.filter(function(s){ return /^(maths?|mathematics)\b/i.test(s.name); })[0];
  return [en, ma].filter(Boolean);
}
function emLikely(p, idx){ return emSubjects().map(function(su){ const c = coreCell(p, su, idx); return {su:su, likely:c.likely, ks4:c.ks4}; }); }
/* one pupil in one core subject: where they are, progress, and the likely grade */
function coreCell(p, su, idx){
  const m = subjectMetrics(p, su, idx);
  const ks4 = usesGcse(p, null, su.id);
  const S = subjStatus(p, su, idx);
  const g = S.g, j = S.j;
  const likely = ks4 ? (g.pred ? gradeWhole(g.pred.value) : m.gcse) : m.gcse;
  return {m:m, ks4:ks4, g:g, j:j, st:S.st, likely:likely, has: ks4 ? !!(g.pred || g.target) : !!m.last,
          ontrack: S.st==="ahead" || S.st==="ontrack",
          judged: ["ahead","ontrack","behind","well"].indexOf(S.st) >= 0};
}
function coreAgg(cells){
  const has = cells.filter(function(c){ return c.has; });
  const judged = has.filter(function(c){ return c.judged; });
  const beh = has.map(function(c){ return c.m.behindNow; }).filter(function(v){ return v!=null; });
  const atAre = beh.filter(function(v){ return v <= 0.34; }).length;
  const gch = has.map(function(c){ return c.m.gapChange; }).filter(function(v){ return v!=null; });
  const lk = has.filter(function(c){ return c.likely!=null; });
  const gains = has.filter(function(c){ return c.m.gain!=null; });
  const both = has.filter(function(c){ return c.m.preRate!=null && c.m.rmsRate!=null; });
  return {pre:avgOf(both.map(function(c){ return c.m.preRate; })), rms:avgOf(both.map(function(c){ return c.m.rmsRate; })), nRate:both.length,
          faster:both.filter(function(c){ return c.m.rmsRate > c.m.preRate; }).length, n:has.length, judged:judged.length, on:judged.filter(function(c){ return c.ontrack; }).length,
          beh:avgOf(beh), nBeh:beh.length, atAre:atAre,
          closing:gch.filter(function(v){ return v < -0.05; }).length, nGch:gch.length,
          g4:lk.filter(function(c){ return gcseRank(c.likely) >= 4; }).length, nLk:lk.length,
          gain:avgOf(gains.map(function(c){ return c.m.gain; })), expGain:avgOf(gains.map(function(c){ return c.m.expGain; }))};
}
function coreHeat(a, spec, label){
  if(!a.n) return '<td><span class="cell-na">—</span></td>';
  const att = spec ? coreFocusAttr(spec, label) : '';
  const pc = a.judged ? Math.round(a.on/a.judged*100) : null;
  const k = pc==null ? "same" : (pc >= 70 ? "good" : (pc >= 50 ? "same" : "bad"));
  const bg = k==="good" ? "var(--secure-bg)" : (k==="same" ? "var(--watch-bg)" : "var(--concern-bg)");
  const bd = k==="good" ? "var(--secure-line)" : (k==="same" ? "var(--watch-line)" : "var(--concern-line)");
  return '<td><div class="heat"'+att+' style="background:'+bg+';border:1px solid '+bd+(spec ? ';cursor:pointer' : '')+'">'+
    '<b>'+(pc==null ? '—' : pc+'%')+'</b> on track · n '+a.n+'<br>'+
    (a.beh!=null ? fmtYears(a.beh)+'<br>' : '')+

    (a.nGch ? a.closing+' of '+a.nGch+' closing gap<br>' : '')+
    (a.nLk ? '<b>'+Math.round(a.g4/a.nLk*100)+'%</b> likely 4+' : '')+'</div></td>';
}
function renderCore(){
  const host = document.getElementById("coreBody");
  if(!host) return;
  const subs = coreSubjects();
  const yrs = {};
  state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) yrs[String(p.year)] = true; });
  const yl = Object.keys(yrs).sort(function(a,b){ return yearSortKey(b)-yearSortKey(a); });
  document.getElementById("coreYears").innerHTML = ['<button data-coreyear=""'+(coreYear===""?' class="on"':'')+'>Whole school</button>']
    .concat(yl.map(function(y){ return '<button data-coreyear="'+esc(y)+'"'+(coreYear===y?' class="on"':'')+'>Year '+esc(y)+'</button>'; })).join("");
  const pSel = document.getElementById("corePwSel");
  if(pSel) pSel.innerHTML = '<option value="">All pathways</option>'+PATHWAYS.map(function(k){ return '<option value="'+k+'"'+(corePw===k?' selected':'')+'>'+esc(PATHWAY_LABELS[k])+'</option>'; }).join("");
  if(!subs.length){
    document.getElementById("coreStats").innerHTML = "";
    host.innerHTML = '<div class="empty">No core subjects. Tick them in Settings &amp; data → Subjects (Core column), or name them English, Maths and Science.</div>';
    return;
  }
  const idx = curIndex();
  let pupils = state.pupils.filter(function(p){ return !coreYear || String(p.year)===coreYear; });
  if(corePw) pupils = pupils.filter(function(p){ return (p.pathway||"")===corePw; });
  const grid = {};
  pupils.forEach(function(p){ grid[p.id] = {}; subs.forEach(function(su){ grid[p.id][su.id] = coreCell(p, su, idx); }); });
  const cellsFor = function(su, ps){ return ps.map(function(p){ return grid[p.id][su.id]; }); };
  /* tiles: one per core subject */
  const emSubs = emSubjects();
  const emTile = function(g){
    if(emSubs.length < 2) return '';
    const rows = pupils.map(function(p){ const cs = emSubs.map(function(su){ return grid[p.id][su.id] || coreCell(p, su, idx); }); return cs.every(function(c){ return c.likely!=null; }) ? cs : null; }).filter(Boolean);
    const part = function(ks4){ const xs = rows.filter(function(cs){ return cs.every(function(c){ return !!c.ks4 === ks4; }); }); const n = xs.filter(function(cs){ return cs.every(function(c){ return gcseRank(c.likely) >= g; }); }).length; return {n:n, of:xs.length}; };
    const k3 = part(false), k4 = part(true), all = rows.filter(function(cs){ return cs.every(function(c){ return gcseRank(c.likely) >= g; }); }).length;
    const pc = function(x){ return x.of ? Math.round(x.n / x.of * 100) + '%' : '—'; };
    return '<div class="stat brand"'+coreFocusAttr({t:"em", g:g}, 'English and maths both '+g+'+')+'><div class="n">'+(rows.length ? Math.round(all / rows.length * 100)+'%' : '—')+'</div><div class="l"><strong>English and maths '+g+'+</strong> (both)<br>'+
      'KS3 projected: '+pc(k3)+(k3.of ? ' ('+k3.n+' of '+k3.of+')' : '')+'<br>KS4 predicted: '+pc(k4)+(k4.of ? ' ('+k4.n+' of '+k4.of+')' : '')+'</div></div>';
  };
  document.getElementById("coreStats").innerHTML = emTile(4) + emTile(5) + subs.map(function(su){
    const a = coreAgg(cellsFor(su, pupils));
    return '<div class="stat brand"'+coreFocusAttr({t:"sub", s:su.id}, su.name+' (all with data)')+'><div class="n">'+(a.judged ? Math.round(a.on/a.judged*100)+'%' : '—')+'</div><div class="l"><strong>'+esc(su.name)+'</strong> on track<br>'+
      (a.nBeh ? a.atAre+' of '+a.nBeh+' at or above age · avg '+fmtYears(a.beh)+'<br>' : '')+

      (a.nLk ? Math.round(a.g4/a.nLk*100)+'% likely GCSE 4+' : 'No GCSE projection yet')+'</div></div>';
  }).join("");
  /* readiness for the Attain description: likely 4+ in every core subject */
  const ready = function(p){
    const cs = subs.map(function(su){ return grid[p.id][su.id]; }).filter(function(c){ return c.likely!=null; });
    if(cs.length < subs.length) return "unknown";
    const n4 = cs.filter(function(c){ return gcseRank(c.likely) >= 4; }).length;
    return n4===cs.length ? "all" : (n4 ? "some" : "none");
  };
  const pkeys = PATHWAYS.concat(pupils.some(function(p){ return !p.pathway; }) ? [""] : []);
  const rd = {}; pkeys.forEach(function(k){ rd[k] = {all:0, some:0, none:0, unknown:0}; });
  pupils.forEach(function(p){ const k = p.pathway||""; if(rd[k]) rd[k][ready(p)]++; });
  const readyHtml = '<div class="panel"><h2>On course for core GCSEs, by pathway</h2>'+
    '<p class="hint">Attain is defined as “on track for core GCSEs”. Likely grade 4+ in every core subject ('+subs.map(function(s){ return esc(s.name); }).join(", ")+'): projected for KS3 from levels, the latest predicted grade for KS4.</p>'+
    '<div class="tablewrap"><table class="matrix"><thead><tr><th></th>'+pkeys.map(pwHead).join("")+'</tr></thead><tbody>'+
    [["all","4+ in every core subject","var(--secure-bg)"],["some","4+ in some","var(--watch-bg)"],["none","Below 4 in all","var(--concern-bg)"],["unknown","Not enough data","var(--panel)"]].map(function(r){
      return '<tr><td><strong>'+r[1]+'</strong></td>'+pkeys.map(function(k){ const n = rd[k][r[0]]; return '<td>'+(n ? '<div class="heat"'+coreFocusAttr({t:"rd", r:r[0], k:k}, r[1]+', '+(PATHWAY_LABELS[k] || 'no pathway'))+' style="background:'+r[2]+';border:1px solid var(--line);text-align:center;cursor:pointer"><b>'+n+'</b></div>' : '<span class="cell-na">·</span>')+'</td>'; }).join("")+'</tr>';
    }).join("")+'</tbody></table></div></div>';
  /* subject x pathway and subject x year group */
  const cross = function(title, keys, label, fn, kind){
    return '<div class="panel" style="margin-top:16px"><h2>'+title+'</h2>'+
      '<p class="hint">Each cell: share on track for progress, average against age, how many are closing the gap to age-related expectations, and the share likely to get grade 4+.</p>'+
      '<div class="tablewrap"><table class="matrix"><thead><tr><th>Subject</th>'+keys.map(label).join("")+'</tr></thead><tbody>'+
      subs.map(function(su){ return '<tr><td><strong>'+esc(su.name)+'</strong></td>'+keys.map(function(k){ return coreHeat(coreAgg(cellsFor(su, pupils.filter(function(p){ return fn(p)===k; }))), {t:kind, s:su.id, k:k}, su.name+', '+(kind==="yr" ? 'Year '+k : (PATHWAY_LABELS[k] || 'no pathway'))); }).join("")+'</tr>'; }).join("")+
      '</tbody></table></div></div>';
  };
  const ykeys = yl.filter(function(y){ return pupils.some(function(p){ return String(p.year)===y; }); });
  const byPw = cross("Core subjects by pathway", pkeys, pwHead, function(p){ return p.pathway||""; }, "pw");
  const byYr = cross("Core subjects by year group", ykeys, function(y){ return '<th>Year '+esc(y)+'</th>'; }, function(p){ return String(p.year); }, "yr");
  /* likely grade distribution */
  const grades = ["U","1","2","3","4","5","6","7","8","9"];
  const dist = '<div class="panel" style="margin-top:16px"><h2>Likely GCSE grades</h2><p class="hint">KS3: projected from levels (own pace only with enough results, otherwise '+curCfg().rate+' a year). KS4: latest predicted grade. Click a number to see the pupils.</p>'+
    '<div class="tablewrap"><table><thead><tr><th>Subject</th>'+grades.map(function(g){ return '<th class="num">'+g+'</th>'; }).join("")+'<th class="num">4+</th><th></th></tr></thead><tbody>'+
    subs.map(function(su){
      const cs = cellsFor(su, pupils).filter(function(c){ return c.likely!=null; });
      const cnt = {}; cs.forEach(function(c){ const g = String(c.likely).toUpperCase(); cnt[g] = (cnt[g]||0) + 1; });
      const mx = Math.max.apply(null, grades.map(function(g){ return cnt[g]||0; }).concat([1]));
      const g4 = cs.filter(function(c){ return gcseRank(c.likely) >= 4; }).length;
      return '<tr><td><strong>'+esc(su.name)+'</strong> <span class="muted">n '+cs.length+'</span></td>'+grades.map(function(g){
        const n = cnt[g]||0;
        return '<td class="num">'+(n ? '<div'+coreFocusAttr({t:"g", s:su.id, g:g}, su.name+', likely '+g)+' style="display:inline-block;min-width:22px;padding:2px 4px;border-radius:4px;cursor:pointer;background:rgba(15,108,189,'+(0.12+0.6*n/mx).toFixed(2)+');color:inherit">'+n+'</div>' : '<span class="muted">·</span>')+'</td>';
      }).join("")+'<td class="num"><b>'+(cs.length ? Math.round(g4/cs.length*100)+'%' : '—')+'</b></td><td></td></tr>';
    }).join("")+'</tbody></table></div></div>';
  /* pupil by pupil */
  const focusFn = coreFocus ? (function(f){
    const cell = function(p, sid){ return (grid[p.id] && grid[p.id][sid]) || coreCell(p, byId(state.subjects, sid), idx); };
    if(f.t==="sub") return function(p){ return cell(p, f.s).has; };
    if(f.t==="pw") return function(p){ return (p.pathway||"")===f.k && cell(p, f.s).has; };
    if(f.t==="yr") return function(p){ return String(p.year)===String(f.k) && cell(p, f.s).has; };
    if(f.t==="rd") return function(p){ return (p.pathway||"")===f.k && ready(p)===f.r; };
    if(f.t==="g") return function(p){ const c = cell(p, f.s); return c.likely!=null && String(c.likely).toUpperCase()===String(f.g); };
    if(f.t==="em") return function(p){ const cs = emSubs.map(function(su){ return cell(p, su.id); }); return cs.length===2 && cs.every(function(c){ return c.likely!=null && gcseRank(c.likely) >= f.g; }); };
    return function(){ return true; };
  })(coreFocus) : null;
  const list = pupils.filter(function(p){ return !focusFn || focusFn(p); }).sort(function(a,b){ return yearSortKey(b.year)-yearSortKey(a.year) || String(a.name).localeCompare(String(b.name)); });
  const pupilHtml = '<div class="panel" style="margin-top:16px" id="corePupils"><h2>Pupil by pupil</h2>'+
    (coreFocus ? '<div class="backbar" style="margin:6px 0 10px"><strong>Showing '+list.length+' pupil'+(list.length===1?'':'s')+': '+esc(coreFocus.label || '')+'</strong> <button class="btn ghost sm noprint" data-corefocus="">Show all pupils</button></div>' : '')+
    '<p class="hint">Latest level (or predicted grade for KS4), against age, and likely GCSE for each core subject. Click a heading to sort.</p>'+
    '<div class="tablewrap"><table class="sortable"><thead><tr><th>Pupil</th><th>Yr</th><th>Pathway</th>'+
    subs.map(function(su){ return '<th>'+esc(su.name)+'</th><th>'+esc(su.name)+' likely</th>'; }).join("")+'<th>Core 4+</th></tr></thead><tbody>'+
    list.map(function(p){
      const r = ready(p);
      return '<tr><td style="white-space:nowrap"><button class="linkbtn" data-goto-pupil="'+p.id+'">'+esc(p.name)+'</button></td><td>'+esc(p.year)+'</td><td style="white-space:nowrap">'+pathwayTag(p.pathway, true)+'</td>'+
        subs.map(function(su){
          const c = grid[p.id][su.id];
          const now = c.ks4 ? (c.g.pred ? c.g.pred.value+' <span class="muted">pred</span>' : '—') : (c.m.last ? esc(resultLabel(c.m.last.r))+'<br>'+behindHtml(c.m.behindNow) : '<span class="muted">—</span>');
          return '<td>'+now+'</td><td>'+(c.ks4 ? (c.g.exp!=null ? '<span class="muted">0.8 a year → '+esc(String(c.g.exp))+'</span>' : '')+(c.g.target ? '<br><span class="muted">target '+esc(gradeWhole(c.g.target.value))+'</span>' : (c.g.exp==null ? '—' : '')) : gcseHtml(c.likely, c.m.gcseExp, c.m.gcseBand))+'</td>';
        }).join("")+
        '<td>'+(r==="all" ? '<span class="tag t-secure">All</span>' : (r==="some" ? '<span class="tag t-watch">Some</span>' : (r==="none" ? '<span class="tag t-concern">None</span>' : '<span class="muted">—</span>')))+'</td></tr>';
    }).join("")+'</tbody></table></div></div>';
  host.innerHTML = readyHtml + byPw + byYr + dist + pupilHtml;
}
function exportCoreCsv(){
  const subs = coreSubjects(), idx = curIndex();
  const head = ["Pupil","Year","Pathway"];
  subs.forEach(function(su){ head.push(su.name+" latest", su.name+" against age (yrs behind)", su.name+" levels gained", su.name+" likely GCSE"); });
  const lines = [head.map(csvCell).join(",")];
  state.pupils.filter(function(p){ return (!coreYear || String(p.year)===coreYear) && (!corePw || (p.pathway||"")===corePw); }).forEach(function(p){
    const row = [p.name, p.year, PATHWAY_LABELS[p.pathway]||""];
    subs.forEach(function(su){
      const c = coreCell(p, su, idx);
      row.push(c.ks4 ? (c.g.pred ? c.g.pred.value : "") : (c.m.last ? resultLabel(c.m.last.r) : ""),
               c.m.behindNow!=null ? (Math.round(c.m.behindNow*10)/10) : "", c.m.gain!=null ? fmtGain(c.m.gain) : "", c.likely!=null ? c.likely : "");
    });
    lines.push(row.map(csvCell).join(","));
  });
  downloadBlob("core_subjects.csv", lines.join("\n"), "text/csv;charset=utf-8");
}

/* ======================= IMPORT & EXPORT CENTRE =======================
   Paste from Excel, or load a CSV or Excel file. Match the columns once (most are
   recognised by their headings), check the preview, then import. Works for pupils,
   curriculum levels (one column per subject or one row per result), baselines,
   GCSE targets / predicted / actual, summative results and AAA pathways. */
const IO_KINDS = {
  pupils:   {label:"Pupils (add or update the pupil list)"},
  levels:   {label:"Curriculum levels", wide:true, needsDrop:true, value:"Level"},
  baseline: {label:"Baselines (dated, e.g. on entry)", wide:true, value:"Baseline level"},
  target:   {label:"GCSE targets", wide:true, value:"Target grade"},
  predicted:{label:"GCSE predicted grades", wide:true, needsDrop:true, value:"Predicted grade"},
  actual:   {label:"GCSE actual grades", wide:true, needsDrop:true, value:"Actual grade"},
  results:  {label:"Summative assessment results", wide:true, needsDrop:true, value:"Score / result", cols:"assessment"},
  aaa:      {label:"AAA pathways", value:"Pathway"}
};
const IO_SYN = {
  name:["studentname","name","pupil","pupilname","fullname","student","learner","child","legalname","preferredname"],
  surname:["surname","lastname","familyname","legalsurname"],
  first:["firstname","forename","forenames","givenname","preferredforename","legalforename"],
  upn:["upn","uniquepupilnumber","admissionnumber","adno","pupilid","studentid","misid"],
  year:["year","yeargroup","ncyear","yr","curriculumyear"],
  subject:["subject","subjectname","course"],
  assessment:["assessment","assessmentname","test","testname"],
  value:["level","baseline","baselinelevel","value","result","score","grade","attainment","workingat","current","currentlevel","sas","standardisedscore","stdscore"],
  drop:["datadrop","drop","term","period","assessmentpoint","point","window"],
  date:["date","assessed","dateassessed","assessmentdate","baselinedate","entrydate","startdate","loggedat","when"],
  pathway:["pathway","aaa","aaapathway","currentpathway"],
  reason:["reason","reasoncode"],
  notes:["notes","note","comment","comments"],
  action:["action","actiontaken","whatweredoing","nextsteps"],
  staff:["staff","loggedby","by","teacher","initials"]
};
let io = {replaceLevels:true, markEarly:true, kind:"levels", rows:[], headRow:0, map:{}, wide:null, colSubj:{}, dropId:"", dropFrom:"fixed", baseDate:"", overwrite:true,
          createDrops:true, sheets:null, sheet:"", fileName:""};
function ioKey(s){ return String(s||"").toLowerCase().replace(/[^a-z0-9]/g, ""); }
/* text -> rows; tabs mean it came from Excel, otherwise CSV with quotes */
function ioParseText(text){
  const s = String(text||"").replace(/\r\n?/g, "\n");
  const tab = s.indexOf("\t") >= 0;
  const delim = tab ? "\t" : (s.split("\n")[0].split(";").length > s.split("\n")[0].split(",").length ? ";" : ",");
  const rows = []; let row = [], cur = "", q = false;
  for(let i=0;i<s.length;i++){
    const ch = s[i];
    if(q){
      if(ch==='"'){ if(s[i+1]==='"'){ cur+='"'; i++; } else q = false; }
      else cur += ch;
    } else if(ch==='"' && cur==="") q = true;
    else if(ch===delim){ row.push(cur.trim()); cur = ""; }
    else if(ch==="\n"){ row.push(cur.trim()); rows.push(row); row = []; cur = ""; }
    else cur += ch;
  }
  if(cur!=="" || row.length){ row.push(cur.trim()); rows.push(row); }
  return rows.filter(function(r){ return r.some(function(c){ return String(c).trim()!==""; }); });
}
function ioLoadXlsx(buf, done){
  const go = function(){
    try {
      const wb = XLSX.read(buf, {type:"array", cellDates:true});
      const sheets = {};
      wb.SheetNames.forEach(function(n){
        sheets[n] = XLSX.utils.sheet_to_json(wb.Sheets[n], {header:1, raw:false, dateNF:"dd/mm/yyyy", defval:""})
          .map(function(r){ return r.map(function(c){ return String(c==null?"":c).trim(); }); })
          .filter(function(r){ return r.some(function(c){ return c!==""; }); });
      });
      done(null, sheets, wb.SheetNames);
    } catch(e){ done("That Excel file could not be read ("+e.message+").");  }
  };
  /* the Excel library is bundled in this file (see the lib-sheetjs script), so this works offline */
  if(window.XLSX) return go();
  done("The Excel reader is missing from this copy of the tracker. Save the sheet as CSV, or copy the cells and paste them in instead.");
}
function ioHead(){ return (io.rows[io.headRow] || []).map(function(h, i){ return String(h||"").trim() || ("Column "+(i+1)); }); }
function ioBody(){ return io.rows.slice(io.headRow + 1); }
function ioGuess(){
  const head = ioHead().map(ioKey);
  const find = function(list){ for(let i=0;i<head.length;i++) if(list.indexOf(head[i])>=0) return i; return -1; };
  const findLike = function(list){ for(let i=0;i<head.length;i++) for(let j=0;j<list.length;j++) if(head[i].indexOf(list[j])===0) return i; return -1; };
  const m = {};
  Object.keys(IO_SYN).forEach(function(k){ const i = find(IO_SYN[k]); m[k] = i >= 0 ? i : findLike(IO_SYN[k]); });
  if(m.name>=0 && (m.name===m.surname || m.name===m.first)) m.name = -1;
  /* columns that are subjects (or assessments): wide layout */
  const kind = IO_KINDS[io.kind];
  const colSubj = {};
  let nWide = 0;
  ioHead().forEach(function(h, i){
    if([m.name, m.surname, m.first, m.upn, m.year, m.date, m.drop, m.pathway].indexOf(i) >= 0) return;
    const hit = kind && kind.cols==="assessment" ? ioMatchAssessment(h) : ioMatchSubject(h);
    if(hit){ colSubj[i] = hit.id; nWide++; }
  });
  io.map = m; io.colSubj = colSubj;
  if(m.drop >= 0) io.dropFrom = "drop"; else if(m.date >= 0 && kind && kind.needsDrop) io.dropFrom = "date";
  io.wide = kind && kind.wide ? (nWide > 0 && (m.subject < 0 && m.assessment < 0)) : false;
}
function ioMatchSubject(h){
  const k = ioKey(h).replace(/(level|levels|grade|target|predicted|pred|actual|baseline)$/,"");
  if(!k) return null;
  const subs = state.subjects || [];
  const syn = {mathematics:"maths", math:"maths", englishlanguage:"english", englishlit:"english", dt:"designtechnology", designandtechnology:"designtechnology", ict:"computing", pe:"pe", physicaleducation:"pe", religiouseducation:"re", rs:"re"};
  const kk = syn[k] || k;
  for(let i=0;i<subs.length;i++){ const s = ioKey(subs[i].name).replace("and",""); if(s===kk || s===k) return subs[i]; }
  for(let i=0;i<subs.length;i++){ const s = ioKey(subs[i].name); if(kk.length >= 4 && s.length >= 4 && (s.indexOf(kk)===0 || kk.indexOf(s)===0)) return subs[i]; }
  return null;
}
function ioMatchAssessment(h){
  const k = ioKey(h);
  if(!k) return null;
  const as = state.assessments || [];
  for(let i=0;i<as.length;i++) if(ioKey(as[i].name)===k) return as[i];
  for(let i=0;i<as.length;i++){ const s = ioKey(as[i].name); if(k.length >= 4 && s.length >= 4 && (s.indexOf(k)===0 || k.indexOf(s)===0)) return as[i]; }
  return null;
}
/* a level in any common spelling: 4D, 4 d, 4-Developing, Level 4 Secure, 4s */
function ioLevel(v){
  let s = String(v||"").trim();
  if(!s) return {blank:true};
  s = s.toUpperCase().replace(/^LEVEL\s*/,"").replace(/^L(?=\d)/,"");
  const fl = s.match(/^FLS\s*(\d{1,2})$/);
  if(fl && parseInt(fl[1],10) >= 1 && parseInt(fl[1],10) <= 10) return {value:"FLS" + parseInt(fl[1],10)};
  const m = s.match(/^([1-9])\s*[-.\/]?\s*(E|D|S|EMERG\w*|DEVEL\w*|SECURE|SEC)?$/);
  if(!m) return {error:"“"+v+"” isn’t a level 1E–9S"};
  const step = !m[2] ? "E" : m[2][0];
  return {value:m[1]+step};
}
function ioGrade(v){
  const s = String(v||"").trim().toUpperCase().replace(/^GRADE\s*/,"");
  if(!s) return {blank:true};
  if(/^[1-9]$/.test(s) || s==="U") return {value:s};
  let m = s.match(/^([0-9])\s*[-.]?\s*(E|D|S|EMERG\w*|DEVEL\w*|SECURE)$/); if(m) return {value:m[1]==="0" ? "U" : m[1] + m[2][0]};
  m = s.match(/^([1-9])[-+\/]?$/); if(m) return {value:m[1]};
  return {error:"“"+v+"” isn’t a GCSE grade 9–1 or U"};
}
function ioDate(v){
  const s = String(v||"").trim();
  if(!s) return "";
  let m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2}|\d{4})$/);
  if(m){ const y = m[3].length===2 ? "20"+m[3] : m[3]; return y+"-"+m[2].padStart(2,"0")+"-"+m[1].padStart(2,"0"); }
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(m) return m[1]+"-"+m[2]+"-"+m[3];
  const d = new Date(s);
  return isNaN(d) ? "" : d.toISOString().slice(0,10);
}
function ioPathway(v){
  const k = ioKey(v);
  if(!k) return "";
  const map = {attain:"attain", attunetolearn:"attune_learn", attunelearn:"attune_learn", attunelearning:"attune_learn", attune:"attune_school",
               attunetoschool:"attune_school", attuneschool:"attune_school", attend:"attend", attendance:"attend"};
  return map[k] || (PATHWAYS.indexOf(String(v).trim())>=0 ? String(v).trim() : null);
}
function ioPupil(r){
  const m = io.map;
  const get = function(i){ return i>=0 ? String(r[i]||"").trim() : ""; };
  const upn = get(m.upn);
  if(upn){ const p = state.pupils.filter(function(x){ return x.upn && String(x.upn).trim()===upn; })[0]; if(p) return p; }
  let name = get(m.name);
  if(!name && (get(m.surname) || get(m.first))) name = get(m.surname) + (get(m.first) ? ", " + get(m.first) : "");
  if(!name) return null;
  return findPupilByName(name) || (get(m.first) && get(m.surname) ? findPupilByName(get(m.first)+" "+get(m.surname)) : null);
}
function ioRowName(r){
  const m = io.map, g = function(i){ return i>=0 ? String(r[i]||"").trim() : ""; };
  return g(m.name) || (g(m.surname) + (g(m.first) ? ", "+g(m.first) : "")) || g(m.upn) || "(no name)";
}
/* "Autumn 2024" -> a date inside that term, so a drop created from a name sits in the right place */
function ioTermDate(name){
  const m = String(name||"").match(/(autumn|spring|summer)\s*(?:term\s*)?(\d{4})/i);
  if(!m) return "";
  const t = m[1].toLowerCase(), y = m[2];
  return y + (t==="autumn" ? "-12-12" : (t==="spring" ? "-03-27" : "-07-10"));
}
function ioSameTerm(dt){
  return state.settings.dataPoints.filter(function(d){ return d.date && acYearOf(d.date)===acYearOf(dt) && termOf(d.date)===termOf(dt); })[0] || null;
}
function ioDropFor(r){
  if(io.dropFrom==="fixed") return {dp:byId(state.settings.dataPoints, io.dropId)};
  const v = String((io.dropFrom==="drop" ? r[io.map.drop] : r[io.map.date]) || "").trim();
  if(!v) return {error:"no data drop"};
  const dps = state.settings.dataPoints;
  if(io.dropFrom==="drop"){
    const hit = dps.filter(function(d){ return ioKey(d.name)===ioKey(v); })[0];
    if(hit) return {dp:hit};
    const td = ioTermDate(v), same = td ? ioSameTerm(td) : null;
    return same ? {dp:same} : {create:{name:v, date:td}};
  }
  const dt = ioDate(v);
  if(!dt) return {error:"“"+v+"” isn’t a date"};
  const hit = dps.filter(function(d){ return d.date===dt; })[0] || ioSameTerm(dt);
  return hit ? {dp:hit} : {create:{date:dt}};
}
/* turn the rows into records to write: {p, sid|aid, dp, value, date, ...} */
function ioRecords(){
  const kind = io.kind, m = io.map, out = [], unmatched = {};
  const body = ioBody();
  if(kind==="pupils") return {recs:[], unmatched:[]};
  body.forEach(function(r, ri){
    const p = ioPupil(r);
    if(!p){ unmatched[ioRowName(r)] = true; return; }
    const base = {p:p, row:ri};
    if(kind==="aaa"){
      const pw = ioPathway(r[m.pathway]);
      if(pw===null){ out.push(Object.assign({error:"“"+r[m.pathway]+"” isn’t a pathway"}, base)); return; }
      if(!pw) return;
      out.push(Object.assign({}, base, {value:pw, date:m.date>=0 ? ioDate(r[m.date]) : "", reason:m.reason>=0 ? String(r[m.reason]||"") : "",
        notes:m.notes>=0 ? String(r[m.notes]||"") : "", action:m.action>=0 ? String(r[m.action]||"") : "", staff:m.staff>=0 ? String(r[m.staff]||"") : ""}));
      return;
    }
    const cells = [];
    if(io.wide){
      Object.keys(io.colSubj).forEach(function(ci){ if(io.colSubj[ci]) cells.push({ref:io.colSubj[ci], v:r[ci], col:ioHead()[ci]}); });
    } else {
      const refCol = kind==="results" ? m.assessment : m.subject;
      const name = String(r[refCol]||"").trim();
      const hit = kind==="results" ? ioMatchAssessment(name) : ioMatchSubject(name);
      if(!hit && name && kind!=="results" && io.createSubjects){ cells.push({ref:"new:"+name, v:r[m.value]}); }
      else if(!hit){ if(name) out.push(Object.assign({error:"“"+name+"” isn’t a "+(kind==="results"?"known assessment":"subject")+(kind!=="results" ? " (tick ‘Add subjects that aren’t in the list’)" : "")}, base)); return; }
      else cells.push({ref:hit.id, v:r[m.value]});
    }
    const dr = IO_KINDS[kind].needsDrop ? ioDropFor(r) : {};
    cells.forEach(function(c){
      const rec = Object.assign({}, base, {ref:c.ref});
      let pv;
      if(kind==="levels" || kind==="baseline") pv = ioLevel(c.v);
      else if(kind==="results") pv = String(c.v||"").trim() ? {value:String(c.v).trim()} : {blank:true};
      else pv = ioGrade(c.v);
      if(pv.blank) return;
      if(pv.error){ rec.error = pv.error; out.push(rec); return; }
      rec.value = pv.value;
      if(IO_KINDS[kind].needsDrop){
        if(dr.error){ rec.error = dr.error; out.push(rec); return; }
        if(dr.create){ rec.createDrop = dr.create; }
        else if(!dr.dp){ rec.error = "choose a data drop"; out.push(rec); return; }
        else rec.dp = dr.dp;
      }
      if(kind==="baseline"){
        rec.date = m.date>=0 && ioDate(r[m.date]) ? ioDate(r[m.date]) : (io.baseDate || p.startDate || "");
        if(!rec.date){ rec.error = "no baseline date (add a date column, a fixed date, or start dates on the pupil list)"; }
      }
      out.push(rec);
    });
  });
  return {recs:out, unmatched:Object.keys(unmatched)};
}
function ioExisting(rec){
  const k = io.kind;
  if(k==="levels" || k==="predicted" || k==="actual" || k==="target"){
    const idx = ioExisting.idx || (ioExisting.idx = curIndex());
    if(/^new:/.test(String(rec.ref))) return "";
    const x = curGet(idx, rec.p.id, rec.ref, k==="target" ? "" : (rec.dp ? rec.dp.id : "?"), k==="levels" ? "level" : k);
    return x ? x.value : "";
  }
  if(k==="baseline"){ const b = (state.baselines||[]).filter(function(x){ return x.pupilId===rec.p.id && x.subjectId===rec.ref; })[0]; return b ? b.value + " (" + fmtDate(b.date) + ")" : ""; }
  if(k==="results"){ const r = rec.dp ? resultFor(rec.p.id, rec.ref, rec.dp.id) : null; return r ? r.value : ""; }
  if(k==="aaa") return rec.p.pathway || "";
  return "";
}
function ioStatus(rec){
  if(rec.error) return "error";
  const ex = ioExisting(rec);
  if(!ex) return "new";
  const same = io.kind==="baseline" ? ex.indexOf(rec.value + " (") === 0 && ex.indexOf(fmtDate(rec.date)) > 0 : String(ex).toUpperCase()===String(rec.value).toUpperCase();
  if(same) return "same";
  return io.overwrite ? "change" : "keep";
}
function refName(id){ if(/^new:/.test(id)) return id.slice(4)+" (new subject)"; const s = byId(state.subjects||[], id) || byId(state.assessments||[], id); return s ? s.name : id; }
function renderIo(){
  const host = document.getElementById("ioBody");
  const xd = document.getElementById("exDrop");
  if(xd && state){ const ld = latestStartedDrop(); fillSelect(xd, orderedDataPoints().map(function(d){ return {v:d.id, l:d.name}; }), xd.value || (ld ? ld.id : null)); }
  if(!host) return;
  const kSel = document.getElementById("ioKind");
  if(!kSel.options.length) kSel.innerHTML = Object.keys(IO_KINDS).map(function(k){ return '<option value="'+k+'">'+esc(IO_KINDS[k].label)+'</option>'; }).join("");
  kSel.value = io.kind;
  if(!io.dropId || !byId(state.settings.dataPoints, io.dropId)){ const ld = latestStartedDrop() || orderedDataPoints().slice(-1)[0]; io.dropId = ld ? ld.id : ""; }
  const sh = document.getElementById("ioSheetWrap");
  sh.hidden = !io.sheets;
  if(io.sheets) document.getElementById("ioSheet").innerHTML = Object.keys(io.sheets).map(function(n){ return '<option'+(n===io.sheet?' selected':'')+'>'+esc(n)+'</option>'; }).join("");
  if(!io.rows.length){ host.innerHTML = '<div class="empty">Paste cells from Excel into the box above (include the heading row), or choose a CSV or Excel file.</div>'; return; }
  const head = ioHead(), kind = IO_KINDS[io.kind];
  const colOpts = function(sel){ return '<option value="-1">—</option>'+head.map(function(h, i){ return '<option value="'+i+'"'+(sel===i?' selected':'')+'>'+esc(h)+'</option>'; }).join(""); };
  const fld = function(key, label, hint){ return '<label class="fld">'+label+(hint ? ' <small>'+hint+'</small>' : '')+'<select data-iomap="'+key+'">'+colOpts(io.map[key])+'</select></label>'; };
  let html = '<div class="panel" style="margin-top:12px"><h2>2. Match the columns</h2>'+
    '<div class="row"><label class="fld">Heading row<input id="ioHeadRow" type="number" min="1" max="'+io.rows.length+'" value="'+(io.headRow+1)+'" style="width:80px"></label>'+
    '<span class="hint" style="align-self:center">'+ioBody().length+' data rows · '+head.length+' columns'+(io.fileName ? ' · '+esc(io.fileName) : '')+'</span></div>';
  if(io.kind==="pupils"){
    html += '<p class="hint">Pupil columns are recognised by their headings (name or surname + first name, year, group, DOB, start date, UPN, gender, ethnicity and the cohort markers such as SEN, EHCP, PP, FSM6, LAC). Existing pupils are matched by name or UPN and updated; new names are added.</p>';
  } else {
    html += '<div class="row">'+fld("name","Pupil name","or the two below")+fld("surname","Surname")+fld("first","First name")+fld("upn","UPN","optional, matches first")+'</div>';
    if(kind.wide){
      html += '<div class="row"><label class="fld">Layout<select id="ioWide"><option value="1"'+(io.wide?' selected':'')+'>One column per '+(kind.cols==="assessment"?'assessment':'subject')+' (wide)</option>'+
        '<option value="0"'+(!io.wide?' selected':'')+'>One row per result (long)</option></select></label>'+
        (!io.wide ? fld(kind.cols==="assessment" ? "assessment" : "subject", kind.cols==="assessment" ? "Assessment column" : "Subject column")+fld("value", kind.value+" column") : '')+'</div>';
      if(io.wide){
        const opts = (kind.cols==="assessment" ? state.assessments : (state.subjects||[]).filter(function(s){ return s.active; }));
        html += '<p class="hint" style="margin:6px 0">Which '+(kind.cols==="assessment"?'assessment':'subject')+' is each column? Recognised ones are filled in; set any others or leave them as Ignore.</p><div class="row" style="gap:8px">'+
          head.map(function(h, i){
            if([io.map.name, io.map.surname, io.map.first, io.map.upn, io.map.year, io.map.date, io.map.drop].indexOf(i) >= 0) return "";
            return '<label class="fld">'+esc(h)+'<select data-iocol="'+i+'"><option value="">Ignore</option>'+opts.map(function(s){ return '<option value="'+s.id+'"'+(io.colSubj[i]===s.id?' selected':'')+'>'+esc(s.name)+'</option>'; }).join("")+'</select></label>';
          }).join("")+'</div>';
      }
    } else if(io.kind==="aaa"){
      html += '<div class="row">'+fld("pathway","Pathway column")+fld("date","Date","optional")+fld("reason","Reason","optional")+fld("notes","Notes","optional")+fld("action","Action","optional")+fld("staff","Logged by","optional")+'</div>';
    }
    if(kind.needsDrop){
      html += '<div class="row"><label class="fld">Data drop<select id="ioDropFrom"><option value="fixed"'+(io.dropFrom==="fixed"?' selected':'')+'>All rows are one drop</option>'+
        '<option value="drop"'+(io.dropFrom==="drop"?' selected':'')+'>From a column (drop name)</option><option value="date"'+(io.dropFrom==="date"?' selected':'')+'>From a column (date)</option></select></label>'+
        (io.dropFrom==="fixed" ? '<label class="fld">Which drop<select id="ioDrop">'+orderedDataPoints().map(function(d){ return '<option value="'+d.id+'"'+(io.dropId===d.id?' selected':'')+'>'+esc(d.name)+' ('+esc(fmtDate(d.date))+')</option>'; }).join("")+'</select></label>'
                               : fld(io.dropFrom==="drop" ? "drop" : "date", io.dropFrom==="drop" ? "Drop name column" : "Date column")+
                                 '<span class="hint" style="align-self:center">Drops that don’t exist yet are created.</span>')+'</div>';
    }
    if(io.kind==="baseline")
      html += '<div class="row">'+fld("date","Baseline date column","optional")+'<label class="fld">or one date for all<input type="date" id="ioBaseDate" value="'+esc(io.baseDate)+'"></label>'+
        '<span class="hint" style="align-self:center">With neither, each pupil’s start date is used.</span></div>';
    html += '<label class="fld" style="flex-direction:row;align-items:center;gap:8px;margin-top:6px"><input type="checkbox" id="ioOverwrite"'+(io.overwrite?' checked':'')+'>Replace values already in the tracker (untick to fill gaps only)</label>';
    if(io.kind==="predicted" || io.kind==="actual"){
      html += '<label class="fld" style="flex-direction:row;align-items:center;gap:8px;margin-top:6px"><input type="checkbox" id="ioReplaceLevels"'+(io.replaceLevels?' checked':'')+'>Remove a level entered for the same pupil, subject and drop (it was really a grade)</label>';
      html += '<label class="fld" style="flex-direction:row;align-items:center;gap:8px;margin-top:6px"><input type="checkbox" id="ioMarkEarly"'+(io.markEarly?' checked':'')+'>Pupils with grades before Year '+curCfg().gcseFrom+': mark them as on GCSE grades early, from that year</label>';
    }
    if(kind.wide && !io.wide && kind.cols!=="assessment") html += '<label class="fld" style="flex-direction:row;align-items:center;gap:8px;margin-top:6px"><input type="checkbox" id="ioCreateSubjects"'+(io.createSubjects?' checked':'')+'>Add subjects that aren’t in the list yet</label>';
  }
  html += '</div>';
  /* preview */
  if(io.kind==="pupils"){
    const body = ioBody();
    html += '<div class="panel" style="margin-top:12px"><h2>3. Check and import</h2><div class="tablewrap"><table><thead><tr>'+head.map(function(h){ return '<th>'+esc(h)+'</th>'; }).join("")+'</tr></thead><tbody>'+
      body.slice(0, 12).map(function(r){ return '<tr>'+head.map(function(h, i){ return '<td>'+esc(r[i]||"")+'</td>'; }).join("")+'</tr>'; }).join("")+'</tbody></table></div>'+
      (body.length > 12 ? '<p class="hint">…and '+(body.length-12)+' more rows.</p>' : '')+
      '<div class="row" style="margin-top:10px"><button class="btn" data-act="io-apply">Import '+body.length+' pupil'+(body.length===1?'':'s')+'</button></div><div id="ioReport"></div></div>';
    host.innerHTML = html; return;
  }
  ioExisting.idx = null;
  const res = ioRecords();
  const cnt = {new:0, change:0, same:0, keep:0, error:0};
  res.recs.forEach(function(r){ r.st = ioStatus(r); cnt[r.st]++; });
  const stTag = {new:'<span class="tag t-secure">New</span>', change:'<span class="tag t-watch">Replaces</span>', same:'<span class="tag t-none">Same</span>',
                 keep:'<span class="tag t-none">Kept</span>', error:'<span class="tag t-concern">Problem</span>'};
  const shown = res.recs.filter(function(r){ return r.st!=="same"; }).slice(0, 40);
  html += '<div class="panel" style="margin-top:12px"><h2>3. Check and import</h2>'+
    '<div class="stats" style="margin:6px 0 10px"><div class="stat"><div class="n">'+cnt.new+'</div><div class="l">New</div></div>'+
    '<div class="stat watch"><div class="n">'+cnt.change+'</div><div class="l">Replace existing</div></div>'+
    '<div class="stat"><div class="n">'+(cnt.same+cnt.keep)+'</div><div class="l">Already there / kept</div></div>'+
    '<div class="stat'+(cnt.error?' concern':'')+'"><div class="n">'+cnt.error+'</div><div class="l">Problems (skipped)</div></div>'+
    '<div class="stat'+(res.unmatched.length?' concern':'')+'"><div class="n">'+res.unmatched.length+'</div><div class="l">Pupils not found</div></div></div>'+
    (res.unmatched.length ? '<div class="warn bad" style="margin-bottom:10px"><strong>Not matched to a pupil</strong> (add them on the Pupil list or fix the spelling, then load again): '+esc(res.unmatched.slice(0, 40).join("; "))+(res.unmatched.length>40?' …':'')+'</div>' : '')+
    (shown.length ? '<div class="tablewrap"><table><thead><tr><th>Pupil</th><th>'+(io.kind==="results"?'Assessment':(io.kind==="aaa"?'':'Subject'))+'</th><th>Drop / date</th><th>Now</th><th>Importing</th><th></th></tr></thead><tbody>'+
      shown.map(function(r){
        return '<tr><td>'+esc(r.p.name)+'</td><td>'+(r.ref ? esc(refName(r.ref)) : '')+'</td><td>'+esc(r.dp ? r.dp.name : (r.createDrop ? (r.createDrop.name || fmtDate(r.createDrop.date))+' (new drop)' : (r.date ? fmtDate(r.date) : '')))+'</td>'+
          '<td class="muted">'+esc(r.error ? "" : ioExisting(r))+'</td><td><strong>'+esc(r.error ? r.error : (io.kind==="aaa" ? PATHWAY_LABELS[r.value] : r.value))+'</strong></td><td>'+stTag[r.st]+'</td></tr>';
      }).join("")+'</tbody></table></div>'+(res.recs.length - cnt.same > 40 ? '<p class="hint">Showing the first 40 changes.</p>' : '')
      : '<p class="hint">Nothing new to import.</p>')+
    '<div class="row" style="margin-top:10px"><button class="btn" data-act="io-apply"'+(cnt.new+cnt.change ? '' : ' disabled')+'>Import '+(cnt.new+cnt.change)+' value'+(cnt.new+cnt.change===1?'':'s')+'</button></div><div id="ioReport"></div></div>';
  host.innerHTML = html;
}
function ioApply(){
  if(io.kind==="pupils"){
    const head = ioHead();
    document.getElementById("pupilCsvText").value = [head].concat(ioBody()).map(function(r){ return r.map(function(c){ return String(c==null?"":c).replace(/\t/g," "); }).join("\t"); }).join("\n");
    applyPupilCsv();
    const rep = document.getElementById("pupilCsvReport");
    document.getElementById("ioReport").innerHTML = rep ? rep.innerHTML : "";
    return;
  }
  ioExisting.idx = null;
  const res = ioRecords();
  const todo = res.recs.filter(function(r){ const s = ioStatus(r); return s==="new" || s==="change"; });
  if(!todo.length) return;
  /* subjects to create first */
  const newSubs = {};
  todo.forEach(function(r){
    if(!/^new:/.test(String(r.ref))) return;
    const name = String(r.ref).slice(4), k = ioKey(name);
    if(!newSubs[k]){
      const hit = ioMatchSubject(name);
      newSubs[k] = hit || {id:"su_" + k.slice(0,12) + (byId(state.subjects||[], "su_"+k.slice(0,12)) ? "_" + uid("x").slice(2,5) : ""), name:name, active:true, years:"", order:(state.subjects||[]).length+1};
      if(!hit){ state.subjects = state.subjects || []; state.subjects.push(newSubs[k]); }
    }
    r.ref = newSubs[k].id;
  });
  /* drops to create first */
  const made = {};
  todo.forEach(function(r){
    if(!r.createDrop) return;
    /* one new drop per term, however many different dates the rows carry */
    const cd = r.createDrop.date || ioDate(r.createDrop.name) || ioTermDate(r.createDrop.name);
    const key = cd ? "t:" + acYearOf(cd) + termOf(cd) : "n:" + ioKey(r.createDrop.name);
    if(!made[key]){
      const d = r.createDrop.date || ioDate(r.createDrop.name) || new Date().toISOString().slice(0,10);
      const name = r.createDrop.name || (termOf(d) + " " + d.slice(0,4));
      made[key] = {id:uid("dp"), name:name, date:d};
      state.settings.dataPoints.push(made[key]);
    }
    r.dp = made[key];
  });
  /* write in bulk: index once, save once */
  let n = 0;
  const k = io.kind;
  let replaced = 0, early = 0;
  if(k==="predicted" || k==="actual"){
    /* a grade replaces a "level" typed for the same term, and early GCSE pupils are flagged */
    const kill = {};
    todo.forEach(function(r){
      if(io.replaceLevels) kill[curKey(r.p.id, r.ref, r.dp.id, "level")] = true;
      if(io.markEarly){
        const ay = acYearOf(r.dp.date) || currentAY();
        const y = parseInt(yearAt(r.p, ay), 10);
        if(!isNaN(y) && y < curCfg().gcseFrom){
          state.gcseBySub = state.gcseBySub || {};
          const k = r.p.id + "|" + r.ref, cur = state.gcseBySub[k];
          if(!cur || cur==="levels"){ state.gcseBySub[k] = ay; early++; }
          else if(ay < cur) state.gcseBySub[k] = ay;
        }
      }
    });
    if(io.replaceLevels){
      const before = (state.curResults||[]).length;
      state.curResults = (state.curResults||[]).filter(function(r){ return !kill[curKey(r.pupilId, r.subjectId, r.dataPointId, r.kind)]; });
      replaced = before - state.curResults.length;
    }
  }
  if(k==="levels" || k==="predicted" || k==="actual" || k==="target"){
    const kind = k==="levels" ? "level" : k;
    const pos = {};
    (state.curResults||[]).forEach(function(r, i){ pos[curKey(r.pupilId, r.subjectId, r.dataPointId, r.kind)] = i; });
    state.curResults = state.curResults || [];
    todo.forEach(function(r){
      const dpId = kind==="target" ? "" : r.dp.id;
      const key = curKey(r.p.id, r.ref, dpId, kind);
      const ctx = contextNow(r.p.id, dpId);
      if(pos[key]!=null){ state.curResults[pos[key]].value = r.value; state.curResults[pos[key]].ctx = ctx; }
      else { pos[key] = state.curResults.length; state.curResults.push({id:uid("cr"), pupilId:r.p.id, subjectId:r.ref, dataPointId:dpId, kind:kind, value:r.value, ctx:ctx}); }
      n++;
    });
  } else if(k==="baseline"){
    state.baselines = state.baselines || [];
    todo.forEach(function(r){
      const b = state.baselines.filter(function(x){ return x.pupilId===r.p.id && x.subjectId===r.ref; })[0];
      if(b){ b.value = r.value; b.date = r.date; b.source = "import"; }
      else state.baselines.push({id:uid("bl"), pupilId:r.p.id, subjectId:r.ref, value:r.value, date:r.date, source:"import"});
      n++;
    });
  } else if(k==="results"){
    const pos = {};
    state.results.forEach(function(r, i){ pos[r.pupilId+"|"+r.assessmentId+"|"+r.dataPointId] = i; });
    todo.forEach(function(r){
      const key = r.p.id+"|"+r.ref+"|"+r.dp.id, ctx = contextNow(r.p.id, r.dp.id);
      if(pos[key]!=null){ state.results[pos[key]].value = r.value; state.results[pos[key]].ctx = ctx; }
      else { pos[key] = state.results.length; state.results.push({id:uid("re"), pupilId:r.p.id, assessmentId:r.ref, dataPointId:r.dp.id, value:r.value, ctx:ctx}); }
      n++;
    });
  } else if(k==="aaa"){
    state.pathwayLogs = state.pathwayLogs || [];
    todo.forEach(function(r){
      const ts = r.date ? r.date + "T12:00:00.000Z" : new Date().toISOString();
      const from = pathwayAt(r.p.id, ts.slice(0,10)) || r.p.pathway || "";
      const reason = PATHWAY_REASONS.filter(function(x){ return ioKey(x[0])===ioKey(r.reason) || ioKey(x[1]).indexOf(ioKey(r.reason))===0; })[0];
      state.pathwayLogs.push({id:uid("lg"), pupilId:r.p.id, ts:ts, from:from, to:r.value, reason:reason ? reason[0] : (r.reason ? "other" : "review"),
        notes:(reason || !r.reason ? "" : r.reason + (r.notes ? " — " : "")) + r.notes, action:r.action, staff:r.staff || whoAmI() || "Import", type:from!==r.value ? "change" : "review"});
      const latest = logsFor(r.p.id)[0];
      r.p.pathway = latest ? latest.to : r.value;
      n++;
    });
  }
  markDirty(); renderAll();
  document.getElementById("ioReport").innerHTML = '<div class="warn ok" style="margin-top:10px"><strong>Imported '+n+' value'+(n===1?'':'s')+'.</strong>'+
    (Object.keys(made).length ? ' Created '+Object.keys(made).length+' new data drop'+(Object.keys(made).length===1?'':'s')+' (check their names and dates in Settings &amp; data).' : '')+
    (replaced ? ' Removed '+replaced+' level'+(replaced===1?'':'s')+' that were really grades.' : '')+
    (early ? ' Marked '+early+' pupil-subject'+(early===1?'':'s')+' as on GCSE grades early (see the pupil’s profile).' : '')+
    (Object.keys(newSubs).length ? ' Added subject'+(Object.keys(newSubs).length===1?'':'s')+': '+esc(Object.keys(newSubs).map(function(k){ return newSubs[k].name; }).join(", "))+'.' : '')+
    ' They save to SharePoint now.</div>';
}

/* ---------- exports ---------- */
function exportCurCsv(kindFilter){
  const lines = [["Pupil","UPN","Year","Pathway","Subject","Kind","Data drop","Date","Value","Year then","Pathway then"].map(csvCell).join(",")];
  const dps = {}; state.settings.dataPoints.forEach(function(d){ dps[d.id] = d; });
  (state.curResults||[]).forEach(function(r){
    const p = byId(state.pupils, r.pupilId), su = byId(state.subjects||[], r.subjectId), d = dps[r.dataPointId];
    if(!p || !su) return;
    const ctx = contextOf(r, p, d);
    lines.push([p.name, p.upn, p.year, PATHWAY_LABELS[p.pathway]||"", su.name, CUR_KINDS[r.kind]||r.kind, d ? d.name : "", d ? d.date : "", r.value, ctx ? ctx.y : "", ctx ? (PATHWAY_LABELS[ctx.pw]||"") : ""].map(csvCell).join(","));
  });
  downloadBlob("curriculum_levels.csv", lines.join("\n"), "text/csv;charset=utf-8");
}
/* V42.2: everything for one data drop, one row per pupil and subject they take: the level (or GCSE
   grade, or where they are on a qualification that stands in for the subject), the previous result
   and the progress since it */
function exportDropCsv(dpId){
  const dp = byId(state.settings.dataPoints, dpId);
  if(!dp){ toast("Choose a data drop first.", ""); return; }
  const ay = acYearOf(dp.date) || currentAY(), idx = curIndex(), dps = orderedDataPoints(), pos = dps.findIndex(function(d){ return d.id === dp.id; });
  const subs = (state.subjects || []).filter(function(s){ return s.active; });
  const prevOf = function(pid, sid, kind){ for(let i = pos - 1; i >= 0; i--){ const x = curGet(idx, pid, sid, dps[i].id, kind); if(x) return {r:x, dp:dps[i]}; } return null; };
  const moved = function(n, unit){ return n === 0 ? "No change" : (n > 0 ? "Up " : "Down ") + Math.abs(n) + " " + unit + (Math.abs(n) === 1 ? "" : "s"); };
  const lines = [["Pupil","UPN","Year","Group","Subject","Type",dp.name,"Previous","Previous drop","Progress since previous","Status"].map(csvCell).join(",")];
  const seen = {};
  const pupils = state.pupils.filter(function(p){ if(seen[p.id]) return false; seen[p.id] = true; return true; })
    .sort(function(a, b){ return yearSortKey(yearAt(a, ay)) - yearSortKey(yearAt(b, ay)) || String(a.name).localeCompare(String(b.name)); });
  let n = 0;
  pupils.forEach(function(p){ subs.forEach(function(su){
    if(!takesSubject(p, su, ay) || isHidden("ps:" + p.id + "|" + su.id)) return;
    const base = [p.name, p.upn || "", yearAt(p, ay), p.group || "", su.name];
    const qf = qualForSubject(p.id, su.id, dp.id);
    if(qf){
      const rec = qf.rec, S = QUAL_STATUS_BY[rec.status], pdp = pos > 0 ? dps[pos - 1] : null;
      const prev = pdp ? qualAt(p.id, qf.q.id, pdp.id) : null, PS = prev ? QUAL_STATUS_BY[prev.status] : null;
      lines.push(base.concat([qualTitle(qf.q), (S ? S.label : "") + (rec.grade ? " (" + rec.grade + ")" : ""), PS ? PS.label + (prev.grade ? " (" + prev.grade + ")" : "") : "",
        PS ? pdp.name : "", PS && S ? (PS === S ? "No change" : PS.label + " to " + S.label) : "", S ? S.label : ""]).map(csvCell).join(","));
      n++; return;
    }
    const gcse = usesGcse(p, ay, su.id), kind = gcse ? "predicted" : "level";
    let type = gcse ? "GCSE" : "Level", r = curGet(idx, p.id, su.id, dp.id, kind);
    if(!r && gcse){ const a = curGet(idx, p.id, su.id, dp.id, "actual"); if(a){ r = a; type = "GCSE exam result"; } }
    const pv = prevOf(p.id, su.id, kind);
    const ia = r ? fwStepIndex(r.value, kind) : null, ib = pv ? fwStepIndex(pv.r.value, kind) : null;
    let status = "";
    if(!r) status = "Not entered";
    else if(gcse){ if(type === "GCSE"){ const gj = gcseJudge(p.id, su.id, idx, dp.date); status = gj.status && gj.status !== "none" && CUR_STATUS[gj.status] ? CUR_STATUS[gj.status].label : ""; } }
    else { const j = levelJudge(p.id, su.id, r, dp, idx); status = j && CUR_STATUS[j.status] && j.status !== "none" ? CUR_STATUS[j.status].label : ""; }
    lines.push(base.concat([type, r ? r.value : "", pv ? pv.r.value : "", pv ? pv.dp.name : "", ia != null && ib != null ? moved(ia - ib, gcse ? "grade" : "step") : "", status]).map(csvCell).join(","));
    n++;
  }); });
  downloadBlob("levels_" + String(dp.name || "drop").replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "") + ".csv", lines.join("\n"), "text/csv;charset=utf-8");
  toast(n + " rows for " + dp.name + " downloaded.", "ok");
}
function exportBaselinesCsv(){
  const lines = [["Pupil","UPN","Year","Subject","Baseline","Date","Source"].map(csvCell).join(",")];
  const idx = curIndex();
  state.pupils.forEach(function(p){ (state.subjects||[]).forEach(function(su){
    const b = baselineOf(p.id, su.id, idx);
    if(b) lines.push([p.name, p.upn, p.year, su.name, b.value, b.date, b.source==="earliest" ? "Earliest level" : "Set"].map(csvCell).join(","));
  }); });
  downloadBlob("baselines.csv", lines.join("\n"), "text/csv;charset=utf-8");
}
function exportPupilsCsv(){
  const head = ["Name","Surname","First name","UPN","Year","Group","Tutor","Form","DOB","Start date","Gender","Ethnicity","Pathway"].concat(MARKERS.map(function(m){ return m[1]; }));
  const lines = [head.map(csvCell).join(",")];
  state.pupils.forEach(function(p){
    lines.push([p.name, p.surname, p.firstName, p.upn, p.year, p.group, p.tutor, p.form, p.dob, p.startDate, p.gender, p.ethnicity, PATHWAY_LABELS[p.pathway]||""]
      .concat(MARKERS.map(function(m){ return p[m[0]] ? "Y" : ""; })).map(csvCell).join(","));
  });
  downloadBlob("pupils.csv", lines.join("\n"), "text/csv;charset=utf-8");
}
function exportMetricsCsv(){
  const idx = curIndex(), subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const lines = [["Pupil","Year","Pathway","Subject","Baseline","Baseline date","Against age at baseline (yrs)","Latest","Latest drop","Against age now (yrs)","Levels a year before joining","Levels a year at RMS","Levels gained","Expected gain","Gap change (yrs, - = closing)","Projected end Y9","Likely GCSE"].map(csvCell).join(",")];
  state.pupils.forEach(function(p){ subs.forEach(function(su){
    const m = subjectMetrics(p, su, idx);
    if(!m.last) return;
    const r1 = function(v){ return v==null ? "" : Math.round(v*10)/10; };
    lines.push([p.name, p.year, PATHWAY_LABELS[p.pathway]||"", su.name, m.base ? m.base.value : "", m.base ? m.base.date : "", r1(m.behindBase),
      resultLabel(m.last.r), m.last.dp.name, r1(m.behindNow), m.preRate!=null ? fmtRate(m.preRate) : "", m.rmsRate!=null ? fmtRate(m.rmsRate) : "", m.gain!=null ? fmtGain(m.gain) : "", m.expGain!=null ? fmtGain(m.expGain) : "", r1(m.gapChange),
      m.proj9!=null ? lvlLabel(m.proj9) : "", m.gcse!=null ? m.gcse : ""].map(csvCell).join(","));
  }); });
  downloadBlob("progress_metrics.csv", lines.join("\n"), "text/csv;charset=utf-8");
}
/* a ready-to-fill template with the pupils already listed */
function exportTemplate(kind){
  const subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const pupils = state.pupils.slice().sort(function(a,b){ return yearSortKey(a.year)-yearSortKey(b.year) || String(a.name).localeCompare(String(b.name)); });
  let head, rows;
  if(kind==="pupils"){ head = ["Surname","First name","UPN","Year","Group","DOB","Start date","Gender","SEN","EHCP","PP","FSM6","LAC"]; rows = []; }
  else if(kind==="results"){ head = ["Pupil","UPN","Year"].concat(state.assessments.filter(function(a){ return a.active; }).map(function(a){ return a.name; })); rows = pupils.map(function(p){ return [p.name, p.upn, p.year]; }); }
  else if(kind==="aaa"){ head = ["Pupil","UPN","Year","Pathway","Date","Reason","Notes","Action","Logged by"]; rows = pupils.map(function(p){ return [p.name, p.upn, p.year, PATHWAY_LABELS[p.pathway]||""]; }); }
  else if(kind==="baseline"){ head = ["Pupil","UPN","Year","Baseline date"].concat(subs.map(function(s){ return s.name; })); rows = pupils.map(function(p){ return [p.name, p.upn, p.year, p.startDate ? fmtDate(p.startDate) : ""]; }); }
  else { head = ["Pupil","UPN","Year"].concat(subs.map(function(s){ return s.name; })); rows = pupils.filter(function(p){ return kind==="levels" ? !usesGcse(p) : usesGcse(p); }).map(function(p){ return [p.name, p.upn, p.year]; }); }
  const lines = [head].concat(rows).map(function(r){ return r.map(csvCell).join(","); });
  downloadBlob("template_"+kind+".csv", lines.join("\n"), "text/csv;charset=utf-8");
}

/* ======================= STAFF AREA =======================
   Each member of staff has their subjects and their classes (year groups and/or
   teaching groups). "My classes" shows only their pupils, what still needs entering
   and how each class is doing, with one click into level entry already filtered.
   A staff copy of the file opens straight on My classes with the SLT pages hidden
   and the safeguarding markers left out of view. That makes the file simpler for
   staff; it is not a security boundary, because the copy uses the same flow link. */
const STAFF_MODE = false;
const LS_STAFF = LS_NS + "staffId";
const SENSITIVE_MARKERS = ["lac","prevLac","cp","cin","tac","sw","sgo","adopted"];
const STAFF_TABS = ["staff","curentry","qualentry","cur","core","pupil"];
function staffList(){ return state.staff || (state.staff = []); }
function myStaffId(){ let v = ""; try { v = localStorage.getItem(LS_STAFF) || ""; } catch(e){} return v; }
function setMyStaff(id){ try { localStorage.setItem(LS_STAFF, id || ""); } catch(e){} }
/* is the pupil in this teacher's year groups or teaching groups? */
function staffBaseHas(s, p){
  const ys = splitList(s.years).map(function(y){ return y.replace(/[^0-9]/g,""); }).filter(Boolean);
  const gs = splitList(s.groups).map(function(g){ return g.toLowerCase(); });
  if(!ys.length && !gs.length) return true;
  return (ys.length && ys.indexOf(String(p.year)) >= 0) || (gs.length && gs.indexOf(String(p.group||"").toLowerCase()) >= 0);
}
/* V41: a teacher's pupils = their year groups / teaching groups, plus any individual pupils added
   to them for a subject (Settings & data → Staff → Individual pupils, or Pupil settings) */
function staffPupils(s, list, hid){
  const extra = {};
  staffExtraPairs(s.id, hid).forEach(function(x){ extra[x.pid] = true; });
  return (list || state.pupils).filter(function(p){ return staffBaseHas(s, p) || extra[p.id]; });
}
/* does this teacher teach this pupil this subject (their subjects and groups, or added individually)? */
function staffTeaches(s, p, sid, hid){
  return ((s.subjects || []).indexOf(sid) >= 0 && staffBaseHas(s, p)) || !!flagStore(hid)["sx:" + s.id + "|" + p.id + "|" + sid];
}
/* ===== V41: individual pupils and subjects =====
   Kept as flags in the same store as hidden items ("pt:<pupil>|<subject>" = takes this subject
   outside its year groups; "sx:<staff>|<pupil>|<subject>" = in this teacher's grid for it), so they
   save to SharePoint, Excel and CSV with everything else and reach the Staff entry app. */
function flagStore(hid){ return hid || (state && state.hidden) || {}; }
function flagKeys(prefix, hid){ const h = flagStore(hid); return Object.keys(h).filter(function(k){ return h[k] && k.indexOf(prefix) === 0; }); }
function pupilExtraSubIds(pid, hid){ return flagKeys("pt:" + pid + "|", hid).map(function(k){ return k.split("|")[1]; }); }
function staffExtraPairs(staffId, hid){
  return flagKeys("sx:" + staffId + "|", hid).map(function(k){ const parts = k.slice(3).split("|"); return {pid:parts[1], sid:parts[2], key:k}; });
}
/* every pupil|subject added to some teacher individually, for takesSubject */
let sxIndexCache = {h:null, n:-1, idx:null};
function sxPairIndex(hid){
  const h = flagStore(hid), n = Object.keys(h).length;
  if(sxIndexCache.h === h && sxIndexCache.n === n) return sxIndexCache.idx;
  const idx = {};
  Object.keys(h).forEach(function(k){ if(h[k] && k.indexOf("sx:") === 0){ const parts = k.slice(3).split("|"); idx[parts[1] + "|" + parts[2]] = true; } });
  sxIndexCache = {h:h, n:n, idx:idx};
  return idx;
}
function setPupilTakes(pid, sid, on){ setHidden("pt:" + pid + "|" + sid, !!on); if(on) setHidden("ps:" + pid + "|" + sid, false); markDirty(); }
function setStaffExtra(staffId, pid, sid, on){ setHidden("sx:" + staffId + "|" + pid + "|" + sid, !!on); if(on) setHidden("ps:" + pid + "|" + sid, false); markDirty(); }
/* Add a single pupil to a teacher's levelling and sign-off grids for one subject. Opened from
   Settings & data → Staff (teacher chosen) or from Pupil settings (pupil chosen). */
function openAddToTeacher(staffId, pupilId){
  const staff = staffList().slice().sort(function(a,b){ return String(a.name).localeCompare(String(b.name)); });
  if(!staff.length){ alert("Add staff first, in Settings & data → Staff."); return; }
  const pupils = state.pupils.slice().sort(function(a,b){ return yearSortKey(a.year)-yearSortKey(b.year) || String(a.name).localeCompare(String(b.name)); });
  const subs = (state.subjects||[]).filter(function(x){ return x.active; });
  const t0 = staffId ? byId(staff, staffId) : null;
  const subOpts = function(t){
    const mine = t ? (t.subjects || []) : [];
    return subs.slice().sort(function(a,b){ return (mine.indexOf(b.id) >= 0) - (mine.indexOf(a.id) >= 0) || (a.order||0)-(b.order||0); })
      .map(function(su){ return '<option value="'+esc(su.id)+'">'+esc(su.name)+(mine.indexOf(su.id) >= 0 ? '' : ' (not one of their subjects)')+'</option>'; }).join("");
  };
  openModal({title:"Add a pupil to a teacher’s grids",
    body:'<p class="hint" style="margin-top:0">The pupil appears in this teacher’s Levels, GCSE and Sign off grids for this subject (and in Staff entry), on top of the teacher’s own year groups and teaching groups. Nothing else about the pupil changes.</p>'+
      '<div class="row">'+
        '<label class="fld">Teacher<select id="sxStaff">'+staff.map(function(t){ return '<option value="'+esc(t.id)+'"'+(t0 && t0.id===t.id ? ' selected' : '')+'>'+esc(t.name || t.initials || 'Unnamed')+'</option>'; }).join("")+'</select></label>'+
        '<label class="fld" style="flex:1;min-width:220px">Pupil<input id="sxFind" placeholder="Type to filter…" autocomplete="off" style="margin-bottom:4px"><select id="sxPupil" size="6">'+pupils.map(function(p){ return '<option value="'+esc(p.id)+'"'+(pupilId===p.id ? ' selected' : '')+'>'+esc(p.name)+(p.year!=="" ? ' (Y'+esc(p.year)+')' : '')+(p.group ? ' · '+esc(p.group) : '')+'</option>'; }).join("")+'</select></label>'+
        '<label class="fld">Subject<select id="sxSubject">'+subOpts(t0 || staff[0])+'</select></label>'+
      '</div><div id="sxMsg" class="hint"></div>',
    buttons:[["Cancel", null, "ghost"], ["Add", function(){
      const sid = (document.getElementById("sxStaff")||{}).value, pid = (document.getElementById("sxPupil")||{}).value, su = (document.getElementById("sxSubject")||{}).value;
      const msg = document.getElementById("sxMsg");
      if(!sid || !pid || !su){ if(msg) msg.textContent = "Choose a teacher, a pupil and a subject."; return false; }
      const t = byId(staffList(), sid), p = byId(state.pupils, pid);
      if(t && p && staffTeaches(t, p, su)){ if(msg) msg.textContent = (p.name)+" is already in "+(t.name||"their")+"’s grid for that subject."; return false; }
      setStaffExtra(sid, pid, su, true);
      if(document.activeElement && document.activeElement.blur) document.activeElement.blur();
      renderAll(); renderStaffSettings();
      toast("Added " + (p ? p.name : "pupil") + " to " + (t ? (t.name || t.initials) : "the teacher") + "’s " + (byId(state.subjects, su) || {}).name + " grid.", "ok");
    }, ""]],
    onOpen:function(scrim){
      const ss = scrim.querySelector("#sxStaff"), sub = scrim.querySelector("#sxSubject"), f = scrim.querySelector("#sxFind"), ps = scrim.querySelector("#sxPupil");
      if(ss) ss.addEventListener("change", function(){ sub.innerHTML = subOpts(byId(staff, ss.value)); });
      if(f) f.addEventListener("input", function(){ const q = f.value.toLowerCase().trim(); Array.prototype.forEach.call(ps.options, function(o){ o.hidden = !!q && o.textContent.toLowerCase().indexOf(q) < 0; }); });
      if(pupilId && ps) ps.disabled = false;
    }});
}
/* Settings list rows hold up to 255 characters: keep each member short */
/* One SharePoint cell holds 255 characters. A long subject list is saved in extra 240-character
   pieces ("stsub_<id>_000"...) and the main record says "@" in its place. */
function staffToSetting(s, outSettings){
  const subs = (s.subjects||[]).map(function(x){ return String(x).replace(/^su_/,""); }).join("|");
  const rec = function(sv, extra){ return JSON.stringify(Object.assign({n:s.name||"", i:s.initials||"", s:sv, y:s.years||"", g:s.groups||"", r:s.role==="slt" ? "s" : "t", e:s.email||""}, extra || {})); };
  let v = rec(subs);
  /* V42: k = how many pieces, h = fingerprint (older copies ignore both) */
  if(v.length > 255){ v = rec("@", {k:chunkCount(subs), h:fnv32(subs)}); if(outSettings) chunkSetting(outSettings, "stsub_" + s.id, subs); }
  return v.length > 255 ? v.slice(0, 255) : v;   /* only if the name, email, years and groups alone are too long; the page warns first */
}
function staffFromSetting(key, v, set){
  let o = null; try { o = JSON.parse(v); } catch(e){}
  if(!o) return null;
  const sid = key.replace(/^staff_/,"");
  let damaged = false;
  if(o.s === "@"){
    if(set && +o.k > 0){
      const whole = unchunkChecked(set, "stsub_" + sid, +o.k, o.h);
      if(whole != null) o.s = whole;
      else { damaged = true; o.s = ENTRY_MODE ? "" : (unchunkChecked(set, "stsub_" + sid, +o.k, "") || unchunkSetting(set, "stsub_" + sid)); }
    } else o.s = set ? unchunkSetting(set, "stsub_" + sid) : "";
  }
  const out = {id:sid, name:o.n||"", initials:o.i||"", subjects:String(o.s||"").split("|").filter(Boolean).map(function(x){ return /^su_/.test(x) ? x : "su_"+x; }),
          years:o.y||"", groups:o.g||"", role:o.r==="s" ? "slt" : "teacher", email:o.e||""};
  if(damaged) out.damaged = true;
  return out;
}
function renderStaffSettings(){
  const host = document.getElementById("staffList");
  if(!host || host.contains(document.activeElement)) return;
  const subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const list = staffList();
  host.innerHTML = list.length ? '<table><thead><tr><th>Name</th><th>Initials</th><th>School email <small class="muted">for Staff entry</small></th><th>Subjects</th><th>Year groups <small class="muted">e.g. 7, 8</small></th><th>Teaching groups <small class="muted">e.g. 9A</small></th><th>Role</th><th title="Single pupils in this teacher’s levelling and sign-off grids for one subject, outside their year groups and teaching groups">Individual pupils</th><th class="num">Pupils</th><th></th></tr></thead><tbody>'+
    list.map(function(s){
      const long = staffToSetting(s).length >= 255;
      const ex = staffExtraPairs(s.id).map(function(x){ const p = byId(state.pupils, x.pid), su = byId(state.subjects||[], x.sid); return p && su ? {x:x, p:p, su:su} : null; }).filter(Boolean);
      return '<tr><td><input data-st="'+s.id+'" data-f="name" value="'+esc(s.name)+'" style="width:170px"></td>'+
        '<td><input data-st="'+s.id+'" data-f="initials" value="'+esc(s.initials)+'" style="width:60px"></td>'+
        '<td><input data-st="'+s.id+'" data-f="email" type="email" value="'+esc(s.email||"")+'" placeholder="name@school.org" style="width:190px" autocomplete="off"></td>'+
        '<td><details><summary style="cursor:pointer">'+((s.subjects||[]).length ? esc((s.subjects||[]).map(function(id){ const x = byId(state.subjects||[], id); return x ? x.name : ""; }).filter(Boolean).join(", ")) : '<span class="muted">choose…</span>')+'</summary>'+
          '<div style="display:grid;grid-template-columns:repeat(2,minmax(120px,1fr));gap:2px 10px;padding:6px 0">'+subs.map(function(su){
            return '<label style="display:flex;gap:6px;align-items:center;font-size:13px"><input type="checkbox" data-stsub="'+s.id+'" value="'+su.id+'"'+((s.subjects||[]).indexOf(su.id)>=0?' checked':'')+'>'+esc(su.name)+'</label>';
          }).join("")+'</div></details>'+(long ? '<span class="delta bad">Too long to save: shorten the name, email, years or groups</span>' : '')+'</td>'+
        '<td><input data-st="'+s.id+'" data-f="years" value="'+esc(s.years)+'" style="width:90px"></td>'+
        '<td><input data-st="'+s.id+'" data-f="groups" value="'+esc(s.groups)+'" style="width:110px"></td>'+
        '<td><select data-st="'+s.id+'" data-f="role"><option value="teacher"'+(s.role!=="slt"?' selected':'')+'>Teacher</option><option value="slt"'+(s.role==="slt"?' selected':'')+'>SLT</option></select></td>'+
        '<td style="min-width:180px"><div class="chips" style="margin-bottom:4px">'+ex.map(function(e){ return '<span class="chip">'+esc(e.p.name)+' · '+esc(e.su.name)+' <button class="linkbtn" data-sx-del="'+esc(e.x.key)+'" title="Remove '+esc(e.p.name)+' from '+esc(s.name||'this teacher')+'’s '+esc(e.su.name)+' grid" aria-label="Remove">✕</button></span>'; }).join("")+'</div>'+
          '<button class="btn ghost sm" data-sx-add="'+s.id+'">+ Add a pupil</button></td>'+
        '<td class="num">'+staffPupils(s).length+'</td>'+
        '<td><button class="btn subtle sm" data-del-st="'+s.id+'" title="Remove"><svg class="ic sm"><use href="#i-delete"/></svg></button></td></tr>';
    }).join("")+'</tbody></table>' : '<div class="empty">No staff yet. Add each teacher with their subjects and classes.</div>';
}
function renderStaffArea(){
  const host = document.getElementById("staffBody");
  if(!host) return;
  const list = staffList().slice().sort(function(a,b){ return String(a.name).localeCompare(String(b.name)); });
  const sel = document.getElementById("staffMe");
  let me = byId(list, myStaffId());
  if(sel) sel.innerHTML = '<option value="">Choose your name…</option>'+list.map(function(s){ return '<option value="'+s.id+'"'+(me && me.id===s.id?' selected':'')+'>'+esc(s.name)+(s.initials ? ' ('+esc(s.initials)+')' : '')+'</option>'; }).join("");
  if(!list.length){ host.innerHTML = '<div class="empty">No staff set up yet. SLT: add staff, their subjects and classes in Settings &amp; data → Staff.</div>'; return; }
  if(!me){ host.innerHTML = '<div class="empty">Choose your name above to see your classes.</div>'; return; }
  const subIds = (me.subjects||[]).slice(); staffExtraPairs(me.id).forEach(function(x){ if(subIds.indexOf(x.sid) < 0) subIds.push(x.sid); });
  const subs = subIds.map(function(id){ return byId(state.subjects||[], id); }).filter(function(s){ return s && s.active; });
  const pupils = staffPupils(me);
  const idx = curIndex();
  const drop = latestStartedDrop() || orderedDataPoints().slice(-1)[0];
  const ay = drop ? (acYearOf(drop.date) || currentAY()) : currentAY();
  if(!subs.length){ host.innerHTML = '<div class="empty">No subjects are set for you yet. Ask SLT to add them in Settings &amp; data → Staff.</div>'; return; }
  /* one card per subject and class */
  const groupsOf = function(su){
    const ps = pupils.filter(function(p){ return takesSubject(p, su, ay) && staffTeaches(me, p, su.id); });
    const by = {};
    ps.forEach(function(p){ const k = p.group ? p.group : "Year " + p.year; (by[k] = by[k] || []).push(p); });
    return Object.keys(by).sort().map(function(k){ return {name:k, pupils:by[k], year:by[k][0].year, group:by[k][0].group || ""}; });
  };
  let todoTotal = 0;
  const cards = subs.map(function(su){
    return groupsOf(su).map(function(g){
      const ks4 = g.pupils.every(function(p){ return usesGcse(p, ay, su.id); });
      const kind = ks4 ? "predicted" : "level";
      const done = drop ? g.pupils.filter(function(p){ return curGet(idx, p.id, su.id, drop.id, kind); }).length : 0;
      todoTotal += g.pupils.length - done;
      const rows = subjectRows(su, null, idx).filter(function(r){ return g.pupils.indexOf(r.p) >= 0; });
      const k = statusCounts(rows);
      const behind = rows.filter(function(r){ return r.status==="behind" || r.status==="well"; }).map(function(r){ return r.p.name; });
      const go = drillAttr({s:su.id, d:drop ? drop.id : "", y:g.group ? "" : String(g.year), g:g.group, k:kind});
      return '<div class="panel" style="margin:0"><div class="row" style="align-items:center;margin:0"><h2 style="margin:0">'+esc(su.name)+' · '+esc(g.name)+'</h2><span class="spacer"></span>'+
          '<span class="chip">'+g.pupils.length+' pupils</span></div>'+
        '<p class="hint" style="margin:6px 0">'+(drop ? esc(drop.name)+': <strong>'+done+' of '+g.pupils.length+'</strong> entered' : 'No data drop yet')+'</p>'+
        '<div class="bar" style="margin:0 0 8px"><span style="width:'+(g.pupils.length ? done/g.pupils.length*100 : 0).toFixed(0)+'%;background:var(--brand)"></span></div>'+
        (k.judged ? curBar(k)+'<p class="hint" style="margin:6px 0 0">'+Math.round((k.ahead+k.ontrack)/k.judged*100)+'% on track'+(behind.length ? ' · behind: '+esc(behind.slice(0,6).join("; "))+(behind.length>6?' …':'') : '')+'</p>' : '')+
        '<div class="row" style="margin-top:10px"><button class="btn" data-staffgo="'+go+'"><svg class="ic sm"><use href="#i-edit"/></svg>'+(done < g.pupils.length ? 'Enter '+(ks4 ? 'predicted grades' : 'levels') : 'Review entries')+'</button>'+
        '<button class="btn ghost" data-curgo="'+drillAttr({s:su.id, st:"all"})+'">See progress</button></div></div>';
    }).join("");
  }).join("");
  /* my pupils */
  const showM = MARKERS.filter(function(m){ return SENSITIVE_MARKERS.indexOf(m[0]) < 0 && m[3] && markerShown(m[0]); });
  const table = '<div class="panel" style="margin-top:16px"><h2>My pupils</h2><p class="hint">Latest level, against age and likely GCSE in your subjects. Click a name for the profile.</p>'+
    '<div class="tablewrap"><table class="sortable"><thead><tr><th>Pupil</th><th>Yr</th><th>Group</th><th>Pathway</th><th>Needs</th>'+
    subs.map(function(su){ return '<th>'+esc(su.name)+'</th>'; }).join("")+'</tr></thead><tbody>'+
    pupils.slice().sort(function(a,b){ return yearSortKey(a.year)-yearSortKey(b.year) || String(a.name).localeCompare(String(b.name)); }).map(function(p){
      return '<tr><td style="white-space:nowrap"><button class="linkbtn" data-goto-pupil="'+p.id+'">'+esc(p.name)+'</button></td><td>'+esc(p.year)+'</td><td>'+esc(p.group||"")+'</td>'+
        '<td style="white-space:nowrap">'+pathwayTag(p.pathway, true)+'</td>'+
        '<td>'+showM.filter(function(m){ return p[m[0]]; }).map(function(m){ return '<span class="chip">'+esc(m[2])+'</span>'; }).join(" ")+'</td>'+
        subs.map(function(su){
          if(!takesSubject(p, su, ay)) return '<td><span class="cell-na">—</span></td>';
          if(usesGcse(p, ay, su.id)){ const g = gcseJudge(p.id, su.id, idx); return '<td>'+(g.pred ? esc(g.pred.value)+' <span class="muted">pred</span>' : '—')+(g.target ? '<br><span class="muted">target '+esc(g.target.value)+'</span>' : '')+'</td>'; }
          const m = subjectMetrics(p, su, idx);
          return '<td>'+(m.last ? '<strong>'+esc(resultLabel(m.last.r))+'</strong> '+behindHtml(m.behindNow)+(m.gcse!=null ? '<br><span class="muted">likely GCSE '+esc(m.gcse)+'</span>' : '') : '<span class="muted">—</span>')+'</td>';
        }).join("")+'</tr>';
    }).join("")+'</tbody></table></div></div>';
  document.getElementById("staffStats").innerHTML =
    '<div class="stat brand"><div class="n">'+pupils.length+'</div><div class="l">My pupils</div></div>'+
    '<div class="stat"><div class="n">'+subs.length+'</div><div class="l">My subjects</div></div>'+
    '<div class="stat'+(todoTotal ? ' watch' : '')+'"><div class="n">'+todoTotal+'</div><div class="l">Still to enter'+(drop ? ' for '+esc(drop.name) : '')+'</div></div>';
  host.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px">'+cards+'</div>'+table;
}
