function applyStaffMode(){
  if(ENTRY_MODE){
    document.body.classList.add("entrymode");
    Array.prototype.forEach.call(document.querySelectorAll("#tabs button[data-group]"), function(b){ b.hidden = b.getAttribute("data-group") !== "enter"; });
    Array.prototype.forEach.call(document.querySelectorAll("#tabs .navhead"), function(h){ h.hidden = true; });
    const nb = document.querySelector('#tabs button[data-group="enter"]'); if(nb) nb.setAttribute("data-tab", "curentry");
    lsSet(LS_SETUP, "1"); lsSet(LS_TOUR, "1");
    const lt = lsGet(LS_NS + "lastTab");
    switchTab(lt && ENTRY_TABS.indexOf(lt) >= 0 ? lt : "curentry");     /* V42: where this teacher left off */
    return;
  }
  if(!STAFF_MODE) return;
  document.body.classList.add("staffmode");
  Array.prototype.forEach.call(document.querySelectorAll("#tabs button[data-group]"), function(b){
    const g = NAV_GROUPS.filter(function(x){ return x.id===b.getAttribute("data-group"); })[0];
    const tabs = g ? visibleTabs(g) : [];
    b.hidden = !tabs.length;
    if(tabs.length) b.setAttribute("data-tab", tabs[0][0]);
  });
  Array.prototype.forEach.call(document.querySelectorAll("#tabs .navhead"), function(h){
    let n = h.nextElementSibling, any = false;
    while(n && !n.classList.contains("navhead") && !n.classList.contains("navfoot")){ if(!n.hidden) any = true; n = n.nextElementSibling; }
    h.hidden = !any;
  });
  switchTab("staff");
}

/* ======================= SORT ANY TABLE =======================
   Click a column heading to sort by it; click again to reverse. Tables with
   entry boxes, and the heat-map matrices, are left alone. The choice is
   remembered for the session and put back when the table is redrawn. */
const sortMemo = {};
function sortSig(table){ return (table.closest(".tabpane") ? table.closest(".tabpane").id : "") + "|" + Array.prototype.map.call(table.tHead ? table.tHead.rows[0].cells : [], function(c){ return c.textContent.trim(); }).join("|"); }
function sortable(table){
  if(!table || !table.tHead || !table.tBodies.length || table.classList.contains("matrix") || table.classList.contains("cegrid")) return false;
  if(table.closest("#ceTable, #entryTable, #pupilTable, #subjectList, #staffList, #dpList")) return false;
  return table.tHead.rows.length === 1;
}
function sortKey(text){
  const s = String(text||"").trim();
  if(!s || s==="—" || s==="·") return {e:1};
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if(m) return {n:parseInt(m[3]+m[2].padStart(2,"0")+m[1].padStart(2,"0"),10)};
  m = s.match(/^([1-9])([EDS])\b/);
  if(m) return {n:parseInt(m[1],10) + "EDS".indexOf(m[2])/3};
  m = s.match(/^([+\-−]?\d+(?:\.\d+)?)/);
  if(m){
    let n = parseFloat(m[1].replace("−","-"));
    if(/yrs ahead/.test(s)) n = -n;
    return {n:n};
  }
  if(/^at ARE/.test(s)) return {n:0};
  if(/^U\b/.test(s)) return {n:0};
  return {t:s.toLowerCase()};
}
function sortTable(table, col, dir){
  const body = table.tBodies[0];
  const rows = Array.prototype.slice.call(body.rows);
  if(rows.some(function(r){ return r.cells.length !== rows[0].cells.length; })) return;
  const keyed = rows.map(function(r, i){ return {r:r, i:i, k:sortKey(r.cells[col] ? r.cells[col].textContent : "")}; });
  keyed.sort(function(a, b){
    if(a.k.e && b.k.e) return a.i - b.i;
    if(a.k.e) return 1; if(b.k.e) return -1;
    let d;
    if(a.k.n!=null && b.k.n!=null) d = a.k.n - b.k.n;
    else if(a.k.n!=null) d = -1; else if(b.k.n!=null) d = 1;
    else d = a.k.t.localeCompare(b.k.t);
    return (d || (a.i - b.i)) * (d ? dir : 1);
  });
  keyed.forEach(function(x){ body.appendChild(x.r); });
  Array.prototype.forEach.call(table.tHead.rows[0].cells, function(c, i){
    c.classList.toggle("sorted-asc", i===col && dir===1);
    c.classList.toggle("sorted-desc", i===col && dir===-1);
  });
  table.setAttribute("data-sorted", col+":"+dir);
}
function reapplySorts(){
  Array.prototype.forEach.call(document.querySelectorAll("main table"), function(t){
    if(!sortable(t)) return;
    t.classList.add("sortable");
    const memo = sortMemo[sortSig(t)];
    if(memo && t.getAttribute("data-sorted") !== memo.col+":"+memo.dir) sortTable(t, memo.col, memo.dir);
  });
}

/* Home: the headline curriculum and AAA numbers, each a link to the page behind it */
function rmsSummary(subs, idx){
  const pre = [], rms = []; let faster = 0;
  state.pupils.forEach(function(p){
    const m = pupilMetrics(p, idx, subs);
    if(m.preRate==null || m.rmsRate==null) return;
    pre.push(m.preRate); rms.push(m.rmsRate); if(m.rmsRate > m.preRate * 1.1) faster++;
  });
  return {n:pre.length, pre:avgOf(pre), rms:avgOf(rms), faster:faster};
}
function renderDashRms(){
  const host = document.getElementById("dashRms");
  if(!host) return;
  const idx = curIndex(), all = (state.subjects||[]).filter(function(s){ return s.active; });
  const find = function(re){ return all.filter(function(s){ return re.test(s.name); })[0]; };
  const groups = [["Whole school (all subjects)", all, true]];
  [[/^english\b/i,"English"],[/^(maths?|mathematics)\b/i,"Maths"],[/^science\b/i,"Science"]].forEach(function(x){ const s = find(x[0]); if(s) groups.push([s.name, [s], false]); });
  const cards = groups.map(function(g){
    const r = rmsSummary(g[1], idx);
    if(!r.n) return '<div class="stat"><div class="n">—</div><div class="l"><strong>'+esc(g[0])+'</strong><br>Not enough data yet</div></div>';
    const x = r.pre ? r.rms / r.pre : null;
    return '<button class="stat'+(g[2] ? ' brand' : '')+'" data-tab-go="rms" style="text-align:left;cursor:pointer;font:inherit;border:0">'+
      '<div class="n" style="font-size:24px"><span class="muted" style="font-weight:400">'+fmtRate(r.pre)+'</span> → '+fmtRate(r.rms)+'</div>'+
      '<div class="l"><strong>'+esc(g[0])+'</strong><br>'+(x!=null ? (x >= 1.05 ? (Math.round(x*10)/10)+'× faster at Red Moor' : (x > 0.95 ? 'About the same rate' : 'Slower at Red Moor')) : '')+
      ' · '+r.faster+' of '+r.n+' pupils faster<br>'+paceWord(r.rms)+'</div></button>';
  }).join("");
  document.getElementById("dashRmsPanel").hidden = !groups.some(function(g){ return rmsSummary(g[1], idx).n; });
  host.innerHTML = cards;
}
function renderGlance(){
  if(heroTimer) return;   /* drawn with the home summary, a moment after the page appears */
  drawGlance();
}
function drawGlance(){
  renderDashRms();
  const host = document.getElementById("dashGlance");
  if(!host) return;
  const idx = curIndex(), subs = (state.subjects||[]).filter(function(s){ return s.active; });
  let n = 0, atAre = 0, nb = 0, close = 0, ng = 0, gains = [], exps = [], on = 0, judged = 0, pres = [], rmss = [], fast = 0;
  state.pupils.forEach(function(p){ subs.forEach(function(su){
    const m = subjectMetrics(p, su, idx);
    if(!m.last) return;
    n++;
    if(m.behindNow!=null){ nb++; if(m.behindNow <= 0.34) atAre++; }
    if(m.gapChange!=null){ ng++; if(m.gapChange < -0.05) close++; }
    if(m.gain!=null){ gains.push(m.gain); exps.push(m.expGain); }
    if(m.preRate!=null && m.rmsRate!=null){ pres.push(m.preRate); rmss.push(m.rmsRate); if(m.rmsRate > m.preRate) fast++; }
    const jst = subjStatus(p, su, idx).st;
    if(["ahead","ontrack","behind","well"].indexOf(jst) >= 0){ judged++; if(jst==="ahead" || jst==="ontrack") on++; }
  }); });
  const core = coreSubjects();
  let ready = 0, readyN = 0;
  state.pupils.forEach(function(p){
    const cs = core.map(function(su){ return coreCell(p, su, idx); }).filter(function(c){ return c.likely!=null; });
    if(core.length && cs.length===core.length){ readyN++; if(cs.every(function(c){ return gcseRank(c.likely) >= 4; })) ready++; }
  });
  const cnt = {}; state.pupils.forEach(function(p){ cnt[p.pathway||""] = (cnt[p.pathway||""]||0) + 1; });
  const start = ayStartDate(currentAY());
  const mv = (state.pathwayLogs||[]).filter(function(l){ return isRealMove(l) && String(l.ts).slice(0,10) >= start; });
  const up = mv.filter(function(l){ return moveDir(l)==="up"; }).length;
  const tile = function(nv, l, go, cls){ return '<button class="stat'+(cls?' '+cls:'')+'" data-tab-go="'+go+'" style="text-align:left;cursor:pointer;font:inherit;border:0"><div class="n">'+nv+'</div><div class="l">'+l+'</div></button>'; };
  if(!n && !(state.pathwayLogs||[]).length){ document.getElementById("dashGlancePanel").hidden = true; return; }
  document.getElementById("dashGlancePanel").hidden = false;
  host.innerHTML =
    tile(judged ? Math.round(on/judged*100)+'%' : '—', 'On track this year ('+c0(judged)+' pupil-subjects)', "cur", "brand")+
    tile(nb ? Math.round(atAre/nb*100)+'%' : '—', 'At or above age-related level', "core", "")+
    tile(ng ? Math.round(close/ng*100)+'%' : '—', 'Closing the gap to age since baseline', "core", ng && close/ng < 0.3 ? "watch" : "")+
    tile(readyN ? ready+' of '+readyN : '—', 'Likely 4+ in every core subject', "core", "")+
    tile((cnt.attain||0)+' / '+(cnt.attune_learn||0)+' / '+(cnt.attune_school||0)+' / '+(cnt.attend||0), 'Attain / Attune to Learn / Attune to School / Attend', "aaa", "")+
    tile('<span style="color:var(--secure)">↑'+up+'</span> <span style="color:var(--concern)">↓'+(mv.length-up)+'</span>', 'Pathway moves this year', "aaa", "");
}
function c0(n){ return String(n); }
/* Combine data drops that share a name (e.g. four "Autumn 2022"s made by imports) into one */
function mergeDuplicateDrops(){
  const groups = {};
  state.settings.dataPoints.forEach(function(d){ (groups[ioKey(d.name)] = groups[ioKey(d.name)] || []).push(d); });
  const dupes = Object.keys(groups).filter(function(k){ return groups[k].length > 1; });
  if(!dupes.length){ alert("No duplicate data drops: every drop name is used once."); return; }
  const count = function(d){ return state.results.filter(function(r){ return r.dataPointId===d.id; }).length + (state.curResults||[]).filter(function(r){ return r.dataPointId===d.id; }).length; };
  if(!confirm("Merge "+dupes.map(function(k){ return groups[k].length+" × "+groups[k][0].name; }).join(", ")+"?\n\nResults move into one drop per name. Where a pupil has a result in two copies, the one in the drop with most data is kept.")) return;
  let moved = 0, clashes = 0, removed = 0;
  dupes.forEach(function(k){
    const g = groups[k].slice().sort(function(a,b){ return count(b) - count(a); });
    const keep = g[0];
    g.slice(1).forEach(function(d){
      const have = {};
      state.results.forEach(function(r){ if(r.dataPointId===keep.id) have["s|"+r.pupilId+"|"+r.assessmentId] = true; });
      (state.curResults||[]).forEach(function(r){ if(r.dataPointId===keep.id) have["c|"+r.pupilId+"|"+r.subjectId+"|"+r.kind] = true; });
      state.results = state.results.filter(function(r){
        if(r.dataPointId!==d.id) return true;
        if(have["s|"+r.pupilId+"|"+r.assessmentId]){ clashes++; return false; }
        r.dataPointId = keep.id; have["s|"+r.pupilId+"|"+r.assessmentId] = true; moved++; return true;
      });
      state.curResults = (state.curResults||[]).filter(function(r){
        if(r.dataPointId!==d.id) return true;
        const kk = "c|"+r.pupilId+"|"+r.subjectId+"|"+r.kind;
        if(have[kk]){ clashes++; return false; }
        r.dataPointId = keep.id; have[kk] = true; moved++; return true;
      });
      state.settings.dataPoints = state.settings.dataPoints.filter(function(x){ return x.id!==d.id; });
      removed++;
    });
  });
  markDirty(); renderAll();
  alert("Merged: "+removed+" duplicate drop"+(removed===1?"":"s")+" removed, "+moved+" result"+(moved===1?"":"s")+" moved"+(clashes ? ", "+clashes+" duplicate result"+(clashes===1?"":"s")+" dropped" : "")+". Check the dates in Settings & data → Data drops.");
}
function fmtRate(r){ return r==null || isNaN(r) ? "—" : (Math.round(r*100)/100).toFixed(2); }
/* the at-RMS rate is coloured against age: 1.00 a year keeps pace (gap stays the same),
   more closes the gap, less widens it, however it compares with the rate before joining */
function paceWord(rms){ return rms==null ? "" : (rms >= 1.05 ? "closing the gap" : (rms >= 0.95 ? "keeping pace with age" : "gap still widening")); }
function rateCompareHtml(pre, rms){
  if(pre==null && rms==null) return '<span class="muted">—</span>';
  const x = (pre && rms!=null && pre > 0.01) ? rms / pre : null;
  const cls = rms==null ? 'same' : (rms >= 1.05 ? 'good' : (rms >= 0.95 ? 'same' : 'bad'));
  return '<span class="muted">'+fmtRate(pre)+'</span> → <strong class="delta '+cls+'">'+fmtRate(rms)+'</strong>'+
    (x!=null ? ' <span class="muted">('+(x >= 1.05 ? (Math.round(x*10)/10)+'× faster' : (x > 0.95 ? 'same rate' : (x > 0 ? (Math.round(x*100))+'% of the rate' : 'going backwards')))+')</span>' : '')+
    (rms!=null ? '<br><span class="muted" style="font-size:12px">'+paceWord(rms)+'</span>' : '');
}
/* profile, per subject: GCSE grades from Year 10 (usual), early from a chosen year, or kept on levels */
function gsubSelect(p, su){
  const v = (state.gcseBySub||{})[p.id + "|" + su.id] || "";
  const s = ayStart(currentAY()), ays = []; for(let i=-3;i<=1;i++) ays.push((s+i)+"-"+String(s+i+1).slice(2));
  return '<br><select class="noprint" data-gsub="'+p.id+'|'+su.id+'" style="font-size:12px;margin-top:4px;max-width:170px" title="When '+esc(su.name)+' moves to GCSE grades for this pupil">'+
    '<option value="">GCSE from Year '+curCfg().gcseFrom+'</option>'+
    ays.map(function(a){ return '<option value="'+a+'"'+(v===a?' selected':'')+'>GCSE from '+a+' (early)</option>'; }).join("")+
    '<option value="levels"'+(v==="levels"?' selected':'')+'>Keep on levels</option></select>';
}
/* profile control: move a pupil onto GCSE grades before Year 10 */
let gearlyOpen = "";
function gcseEarlyHtml(p){
  const e = (state.gcseEarly||{})[p.id] || null;
  const cur = currentAY(), s = ayStart(cur);
  const ays = []; for(let i=-3;i<=1;i++) ays.push((s+i)+"-"+String(s+i+1).slice(2));
  const subs = (state.subjects||[]).filter(function(x){ return x.active; });
  return '<span class="noprint" style="display:inline-flex;gap:8px;align-items:center;flex-wrap:wrap"><label class="fld" style="flex-direction:row;align-items:center;gap:6px;margin:0">All subjects: GCSE grades'+
    '<select data-gearly="'+p.id+'"><option value="">From Year '+curCfg().gcseFrom+' (usual)</option>'+
    ays.map(function(a){ return '<option value="'+a+'"'+(e && e.mode!=="levels" && e.from===a ? ' selected' : '')+'>Early, from '+a+'</option>'; }).join("")+
    '<option value="levels"'+(e && e.mode==="levels" ? ' selected' : '')+'>Never: keep on curriculum levels</option></select></label>'+
    (e && (e.subs||[]).length ? '<details style="display:inline-block"'+(gearlyOpen===p.id ? ' open' : '')+'><summary style="cursor:pointer;font-size:13px">'+((e.subs||[]).length ? esc(e.subs.map(function(id){ const x = byId(state.subjects||[], id); return x ? x.name : ""; }).filter(Boolean).join(", ")) : 'All subjects')+'</summary>'+
      '<div style="position:absolute;z-index:5;background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:8px;box-shadow:var(--shadow8);display:grid;grid-template-columns:repeat(2,minmax(110px,1fr));gap:2px 10px">'+
      '<span class="hint" style="grid-column:1/-1;margin:0 0 4px">'+(e.mode==="levels" ? 'Tick the subjects kept on levels' : 'Tick the subjects on GCSE grades')+' (none ticked = all)</span>'+
      subs.map(function(su){ return '<label style="display:flex;gap:6px;align-items:center;font-size:13px"><input type="checkbox" data-gearlysub="'+p.id+'" value="'+su.id+'"'+((e.subs||[]).indexOf(su.id)>=0?' checked':'')+'>'+esc(su.name)+'</label>'; }).join("")+'</div></details>' : '')+'</span>';
}
/* profile: choose where progress is measured from for one subject */
function basePickHtml(p, su, idx, b){
  const ser = levelSeries(p.id, su.id, idx);
  const set = (state.baselines||[]).filter(function(x){ return x.pupilId===p.id && x.subjectId===su.id; })[0];
  if(!ser.length && !set) return "";
  const cur = !b ? "" : (b.source==="set" ? "set" : (b.source==="drop" ? "drop:"+b.dp.id : "earliest"));
  const opts = [];
  if(set && !/^drop:/.test(String(set.source||""))) opts.push(['set', 'Entry baseline '+set.value+' ('+fmtDate(set.date)+')']);
  if(ser.length) opts.push(['earliest', (set ? 'Ignore the baseline: ' : '')+'earliest result ('+resultLabel(ser[0].r)+', '+ser[0].dp.name+')']);
  ser.forEach(function(x){ opts.push(['drop:'+x.dp.id, 'Start from '+x.dp.name+' ('+resultLabel(x.r)+')']); });
  return '<br><select class="noprint" data-basepick="'+p.id+'|'+su.id+'" style="max-width:190px;font-size:12px;margin-top:4px" title="Where progress is measured from">'+
    opts.map(function(o){ return '<option value="'+esc(o[0])+'"'+(o[0]===cur ? ' selected' : '')+'>'+esc(o[1])+'</option>'; }).join("")+'</select>';
}
/* ======================= BEFORE vs AT RED MOOR =======================
   Levels a year before joining (level on entry / years of schooling before it)
   against levels a year since joining, by subject, year group, pathway and pupil. */
let rmsYear = "", rmsSub = "core", rmsPw = "";
function rmsVerdict(pre, rms){
  if(pre==null || rms==null) return '<span class="muted">—</span>';
  if(rms > pre * 1.1) return '<span class="tag t-secure">Faster at RMS</span>';
  if(rms < pre * 0.9) return '<span class="tag t-concern">Slower at RMS</span>';
  return '<span class="tag t-none">About the same</span>';
}
function renderRms(){
  const host = document.getElementById("rmsBody");
  if(!host) return;
  const subsAll = (state.subjects||[]).filter(function(s){ return s.active; });
  const yrs = {}; state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) yrs[String(p.year)] = true; });
  const yl = Object.keys(yrs).sort(function(a,b){ return yearSortKey(b)-yearSortKey(a); });
  document.getElementById("rmsYears").innerHTML = ['<button data-rmsyear=""'+(rmsYear===""?' class="on"':'')+'>Whole school</button>']
    .concat(yl.map(function(y){ return '<button data-rmsyear="'+esc(y)+'"'+(rmsYear===y?' class="on"':'')+'>Year '+esc(y)+'</button>'; })).join("");
  const sSel = document.getElementById("rmsSub");
  sSel.innerHTML = '<option value="core"'+(rmsSub==="core"?' selected':'')+'>Core subjects</option><option value="all"'+(rmsSub==="all"?' selected':'')+'>All subjects</option>'+
    subsAll.map(function(s){ return '<option value="'+s.id+'"'+(rmsSub===s.id?' selected':'')+'>'+esc(s.name)+'</option>'; }).join("");
  document.getElementById("rmsPw").innerHTML = '<option value="">All pathways</option>'+PATHWAYS.map(function(k){ return '<option value="'+k+'"'+(rmsPw===k?' selected':'')+'>'+esc(PATHWAY_LABELS[k])+'</option>'; }).join("");
  const subs = rmsSub==="core" ? coreSubjects() : (rmsSub==="all" ? subsAll : subsAll.filter(function(s){ return s.id===rmsSub; }));
  const idx = curIndex();
  const pupils = state.pupils.filter(function(p){ return (!rmsYear || String(p.year)===rmsYear) && (!rmsPw || (p.pathway||"")===rmsPw); });
  const pm = {};
  pupils.forEach(function(p){ pm[p.id] = pupilMetrics(p, idx, subs); });
  const both = pupils.filter(function(p){ return pm[p.id].preRate!=null && pm[p.id].rmsRate!=null; });
  const faster = both.filter(function(p){ return pm[p.id].rmsRate > pm[p.id].preRate * 1.1; }).length;
  const slower = both.filter(function(p){ return pm[p.id].rmsRate < pm[p.id].preRate * 0.9; }).length;
  const aPre = avgOf(both.map(function(p){ return pm[p.id].preRate; })), aRms = avgOf(both.map(function(p){ return pm[p.id].rmsRate; }));
  document.getElementById("rmsStats").innerHTML =
    '<div class="stat"><div class="n">'+fmtRate(aPre)+'</div><div class="l">Levels a year <strong>before</strong> joining (average)</div></div>'+
    '<div class="stat brand"><div class="n">'+fmtRate(aRms)+'</div><div class="l">Levels a year <strong>at Red Moor</strong> (average)'+(aPre ? '<br>'+(Math.round(aRms/aPre*10)/10)+'× the rate before' : '')+'</div></div>'+
    '<div class="stat"><div class="n">'+(both.length ? Math.round(faster/both.length*100) : 0)+'%</div><div class="l">Pupils progressing faster at RMS ('+faster+' of '+both.length+')</div></div>'+
    '<div class="stat'+(slower ? ' watch' : '')+'"><div class="n">'+slower+'</div><div class="l">Slower at RMS than before</div></div>';
  if(!both.length){
    host.innerHTML = '<div class="empty">Not enough data yet. This needs each pupil’s date of birth, a baseline (their level on entry) and at least half a year of results since.</div>';
    return;
  }
  /* by subject */
  const bySub = subs.map(function(su){
    const ms = pupils.map(function(p){ return subjectMetrics(p, su, idx); }).filter(function(m){ return m.preRate!=null && m.rmsRate!=null; });
    if(!ms.length) return "";
    const f = ms.filter(function(m){ return m.rmsRate > m.preRate * 1.1; }).length;
    const pre = avgOf(ms.map(function(m){ return m.preRate; })), rms = avgOf(ms.map(function(m){ return m.rmsRate; }));
    return '<tr><td><strong>'+esc(su.name)+'</strong></td><td class="num">'+ms.length+'</td><td class="num">'+fmtRate(pre)+'</td><td class="num"><strong>'+fmtRate(rms)+'</strong></td>'+
      '<td class="num">'+(pre ? (Math.round(rms/pre*10)/10)+'×' : '—')+'</td><td class="num">'+f+' of '+ms.length+'</td>'+
      '<td style="min-width:160px"><div class="bar"><span style="width:'+(f/ms.length*100).toFixed(0)+'%;background:var(--secure-strong)"></span></div></td></tr>';
  }).join("");
  /* by year group and by pathway */
  const groupTable = function(title, keyFn, keys, label){
    return '<div class="panel" style="margin:0"><h2>'+title+'</h2><div class="tablewrap"><table><thead><tr><th></th><th class="num">Pupils</th><th class="num">Before</th><th class="num">At RMS</th><th class="num">Faster</th></tr></thead><tbody>'+
      keys.map(function(k){
        const ps = both.filter(function(p){ return keyFn(p)===k; });
        if(!ps.length) return "";
        const pre = avgOf(ps.map(function(p){ return pm[p.id].preRate; })), rms = avgOf(ps.map(function(p){ return pm[p.id].rmsRate; }));
        const f = ps.filter(function(p){ return pm[p.id].rmsRate > pm[p.id].preRate * 1.1; }).length;
        return '<tr><td>'+label(k)+'</td><td class="num">'+ps.length+'</td><td class="num">'+fmtRate(pre)+'</td><td class="num"><strong>'+fmtRate(rms)+'</strong></td><td class="num">'+f+' of '+ps.length+'</td></tr>';
      }).join("")+'</tbody></table></div></div>';
  };
  const yk = yl.slice().reverse();
  const groups = '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px;margin-top:16px">'+
    groupTable("By year group", function(p){ return String(p.year); }, yk, function(y){ return 'Year '+esc(y); })+
    groupTable("By AAA pathway", function(p){ return p.pathway||""; }, PATHWAYS.concat([""]), function(k){ return k ? pathwayTag(k, true) : '<span class="muted">No pathway</span>'; })+'</div>';
  /* pupil by pupil */
  const list = pupils.slice().sort(function(a,b){ const x = pm[a.id], y = pm[b.id];
    const ra = x.preRate && x.rmsRate!=null ? x.rmsRate/x.preRate : -1, rb = y.preRate && y.rmsRate!=null ? y.rmsRate/y.preRate : -1; return rb - ra; });
  const pupilHtml = '<div class="panel" style="margin-top:16px"><h2>Pupil by pupil</h2>'+
    '<p class="hint">Averaged over '+(rmsSub==="core" ? 'the core subjects' : (rmsSub==="all" ? 'all subjects' : esc(subs[0] ? subs[0].name : '')))+' with a baseline and results. Click a heading to sort, or a name for the profile.</p>'+
    '<div class="tablewrap"><table class="sortable"><thead><tr><th>Pupil</th><th>Yr</th><th>Pathway</th><th>Joined</th><th>Age on entry</th><th>Level on entry</th><th class="num">Before RMS (levels a year)</th><th class="num">At RMS (levels a year)</th><th class="num">Change</th><th></th></tr></thead><tbody>'+
    list.map(function(p){
      const m = pm[p.id];
      const ent = m.per.map(function(x){ return x.m.base ? x.su.name.slice(0,3)+' '+baseLabel(x.m.base) : ""; }).filter(Boolean).join(", ");
      const age = p.dob && p.startDate ? yearsBetween(p.dob, p.startDate) : null;
      return '<tr><td style="white-space:nowrap"><button class="linkbtn" data-goto-pupil="'+p.id+'">'+esc(p.name)+'</button></td><td>'+esc(p.year)+'</td><td style="white-space:nowrap">'+pathwayTag(p.pathway, true)+'</td>'+
        '<td>'+(p.startDate ? esc(fmtDate(p.startDate)) : '<span class="muted">—</span>')+'</td><td>'+(age!=null ? Math.floor(age)+'y '+Math.round((age%1)*12)+'m' : '—')+'</td>'+
        '<td class="evidence">'+esc(ent)+'</td><td class="num">'+fmtRate(m.preRate)+'</td><td class="num"><strong>'+fmtRate(m.rmsRate)+'</strong></td>'+
        '<td class="num">'+(m.preRate && m.rmsRate!=null ? (Math.round(m.rmsRate/m.preRate*10)/10)+'×' : '—')+'</td><td>'+rmsVerdict(m.preRate, m.rmsRate)+'</td></tr>';
    }).join("")+'</tbody></table></div></div>';
  host.innerHTML = '<div class="panel"><h2>By subject</h2><p class="hint">Before = level on entry ÷ years of schooling before joining (age on entry − 5). At RMS = levels moved since the baseline ÷ years since. Faster means at least 10% quicker than before.</p>'+
    '<div class="tablewrap"><table><thead><tr><th>Subject</th><th class="num">Pupils</th><th class="num">Before RMS</th><th class="num">At RMS</th><th class="num">Change</th><th class="num">Faster at RMS</th><th></th></tr></thead><tbody>'+bySub+'</tbody></table></div></div>'+
    groups + pupilHtml;
}
function exportRmsCsv(){
  const idx = curIndex(), subs = (state.subjects||[]).filter(function(s){ return s.active; });
  const lines = [["Pupil","Year","Pathway","Joined","Subject","Baseline","Baseline date","Levels a year before joining","Levels a year at RMS","Change (x)"].map(csvCell).join(",")];
  state.pupils.forEach(function(p){ subs.forEach(function(su){
    const m = subjectMetrics(p, su, idx);
    if(m.preRate==null && m.rmsRate==null) return;
    lines.push([p.name, p.year, PATHWAY_LABELS[p.pathway]||"", p.startDate||"", su.name, m.base ? baseLabel(m.base) : "", m.base ? m.base.date : "",
      fmtRate(m.preRate), fmtRate(m.rmsRate), m.preRate && m.rmsRate!=null ? (Math.round(m.rmsRate/m.preRate*10)/10) : ""].map(csvCell).join(","));
  }); });
  downloadBlob("before_vs_at_red_moor.csv", lines.join("\n"), "text/csv;charset=utf-8");
}

/* ======================= AAA x PROGRESS =======================
   Joins the AAA log to curriculum levels and summative results:
   how each pathway is doing academically, whether moves were followed by
   better or worse progress, where pupils started the year and where they
   are now, and pupils whose pathway and academic picture don't agree. */
const PW_RANK = {attend:0, attune_school:1, attune_learn:2, attain:3};
let progYear = "", progPw = "", progMoveDir = "all", progMoveOpen = false;

function isRealMove(l){ return l.from && l.to && l.from!==l.to && l.reason!=="imported" && PW_RANK[l.from]!=null && PW_RANK[l.to]!=null; }
function moveDir(l){ return PW_RANK[l.to] > PW_RANK[l.from] ? "up" : "down"; }
function ayStartDate(ay){ const s = ayStart(ay); return s==null ? null : s + "-09-01"; }

/* a pupil's curriculum picture now, across every active subject */
function pupilCurStats(p, idx){
  const o = {judged:0, ahead:0, ontrack:0, behind:0, well:0, gains:[], exps:[], gN:0, gOn:0, subjects:[]};
  (state.subjects||[]).forEach(function(su){
    if(!su.active) return;
    const S = subjStatus(p, su, idx);
    const g = S.g, j = S.last ? S.j : null, st = S.st;
    if(g.status!=="none" && !S.stale){ o.gN++; if(g.status==="ahead" || g.status==="ontrack") o.gOn++; }
    if(j && j.gain!=null){ o.gains.push(j.gain); o.exps.push(j.expGain); }
    if(st==="ahead" || st==="ontrack" || st==="behind" || st==="well"){ o.judged++; o[st]++; o.subjects.push({su:su, status:st}); }
  });
  o.onPct = o.judged ? Math.round((o.ahead+o.ontrack)/o.judged*100) : null;
  o.gain = avgOf(o.gains); o.expGain = avgOf(o.exps);
  return o;
}
/* when the pupil went on to their current pathway */
function pathwaySince(p){
  const logs = logsFor(p.id).slice().reverse();
  let since = null, cur = null;
  logs.forEach(function(l){ if(l.to!==cur){ cur = l.to; since = l.ts; } });
  return cur===p.pathway ? since : null;
}
/* level points for a subject, the baseline included, oldest first */
function levelPoints(pid, sid, idx){
  const pts = levelSeries(pid, sid, idx).map(function(x){ return {d:x.dp.date, v:resultScore(x.r)}; }).filter(function(x){ return x.v!=null && x.d; });
  const b = baselineOf(pid, sid, idx);
  if(b && b.source==="set" && lvlValue(b.value)!=null && b.date && (!pts.length || b.date < pts[0].d)) pts.unshift({d:b.date, v:levelToScore(lvlValue(b.value))});
  return pts;
}
/* levels gained before a date and since it, with what was expected over each span,
   averaged over subjects that have data both sides of the date */
function rateAround(pid, dateIso, idx){
  const cut = String(dateIso).slice(0,10), c = curCfg();
  const o = {gb:[], eb:[], ga:[], ea:[], mb:[], ma:[]};
  (state.subjects||[]).forEach(function(su){
    if(!su.active) return;
    const pts = levelPoints(pid, su.id, idx);
    const pre = pts.filter(function(x){ return x.d <= cut; }), post = pts.filter(function(x){ return x.d > cut; });
    if(pre.length >= 2){
      const a = pre[0], b = pre[pre.length-1], y = yearsBetween(a.d, b.d);
      if(y > 0){ o.gb.push(b.v - a.v); o.eb.push(c.rate * y); o.mb.push(y * 12); }
    }
    if(pre.length && post.length){
      const a = pre[pre.length-1], b = post[post.length-1], y = yearsBetween(a.d, b.d);
      if(y > 0){ o.ga.push(b.v - a.v); o.ea.push(c.rate * y); o.ma.push(y * 12); }
    }
  });
  return {before:avgOf(o.gb), expBefore:avgOf(o.eb), mBefore:avgOf(o.mb), after:avgOf(o.ga), expAfter:avgOf(o.ea), mAfter:avgOf(o.ma), nb:o.gb.length, na:o.ga.length};
}
/* progress against expected, as a share: 1 = exactly what was expected */
function paceOf(g, e){ return (g==null || !e) ? null : g / e; }
function paceVerdict(b, a){
  if(b==null || a==null) return '<span class="muted">—</span>';
  const d = a - b;
  return d > 0.25 ? '<span class="delta good">Faster</span>' : (d < -0.25 ? '<span class="delta bad">Slower</span>' : '<span class="delta same">Similar</span>');
}
function spanHtml(g, e, m){
  if(g==null) return '<span class="muted">—</span>';
  return gainHtml(g, e)+(m!=null ? '<br><span class="muted">over '+Math.max(1, Math.round(m))+' month'+(Math.round(m)===1?'':'s')+'</span>' : '');
}
/* summative: for each assessment, the last result before the date against the latest after */
function summativeAround(p, dateIso){
  const cut = String(dateIso).slice(0,10);
  const out = {better:0, worse:0, same:0};
  const dps = orderedDataPoints();
  state.assessments.forEach(function(a){
    if(!a.active) return;
    let pre = null, post = null;
    dps.forEach(function(d){
      const r = resultFor(p.id, a.id, d.id);
      if(!r || r.value==="") return;
      const m = metricOf(p, a, r, d);
      if(m==null) return;
      if(String(d.date) <= cut) pre = m; else post = m;
    });
    if(pre==null || post==null) return;
    const diff = (post - pre) * (metricBetterHigher(a) ? 1 : -1);
    if(Math.abs(diff) < 1e-9) out.same++; else if(diff > 0) out.better++; else out.worse++;
  });
  return out;
}
function pwHead(pw){
  const col = PATHWAY_COLOURS[pw] || ["var(--ink-soft)","var(--hover)","var(--line)"];
  return '<th style="border-top:3px solid '+col[0]+'"><span style="color:'+col[0]+'">'+esc(pw ? PATHWAY_LABELS[pw] : "No pathway")+'</span></th>';
}
function pctCell(n, d, goodHigh){
  if(!d) return '<td><span class="cell-na">—</span></td>';
  const pc = Math.round(n/d*100);
  const good = goodHigh ? pc >= 70 : pc <= 15, mid = goodHigh ? pc >= 50 : pc <= 30;
  const bg = good ? "var(--secure-bg)" : (mid ? "var(--watch-bg)" : "var(--concern-bg)");
  const bd = good ? "var(--secure-line)" : (mid ? "var(--watch-line)" : "var(--concern-line)");
  return '<td><div class="heat" style="background:'+bg+';border:1px solid '+bd+'"><b>'+pc+'%</b><br>'+n+' of '+d+'</div></td>';
}
function rmsCell(r, n){
  if(r==null) return '<td><span class="cell-na">—</span></td>';
  const k = r >= 1.05 ? "good" : (r >= 0.95 ? "same" : "bad");
  const bg = k==="good" ? "var(--secure-bg)" : (k==="same" ? "var(--watch-bg)" : "var(--concern-bg)");
  const bd = k==="good" ? "var(--secure-line)" : (k==="same" ? "var(--watch-line)" : "var(--concern-line)");
  return '<td><div class="heat" style="background:'+bg+';border:1px solid '+bd+'"><b>'+fmtRate(r)+'</b> a year<br>'+paceWord(r)+(n!=null ? ' · n '+n : '')+'</div></td>';
}
function gainCell(g, e, n){
  if(g==null) return '<td><span class="cell-na">—</span></td>';
  const k = gainClass(g, e);
  const bg = k==="good" ? "var(--secure-bg)" : (k==="same" ? "var(--watch-bg)" : "var(--concern-bg)");
  const bd = k==="good" ? "var(--secure-line)" : (k==="same" ? "var(--watch-line)" : "var(--concern-line)");
  return '<td><div class="heat" style="background:'+bg+';border:1px solid '+bd+'"><b>'+fmtGain(g)+'</b> levels<br>expected '+fmtGain(e)+(n!=null ? ' · n '+n : '')+'</div></td>';
}
function signRate(x){ return x==null ? '<span class="muted">—</span>' : rateHtml(x); }

function renderAaaProgress(){
  const host = document.getElementById("progBody");
  if(!host) return;
  const c = curCfg();
  const ay = currentAY();
  const yrs = {};
  state.pupils.forEach(function(p){ if(p.year!=="" && p.year!=null) yrs[String(p.year)] = true; });
  const yl = Object.keys(yrs).sort(function(a,b){ return yearSortKey(b)-yearSortKey(a); });
  document.getElementById("progYears").innerHTML = ['<button data-progyear=""'+(progYear===""?' class="on"':'')+'>Whole school</button>']
    .concat(yl.map(function(y){ return '<button data-progyear="'+esc(y)+'"'+(progYear===y?' class="on"':'')+'>Year '+esc(y)+'</button>'; })).join("");
  const pupils = state.pupils.filter(function(p){ return !progYear || String(p.year)===progYear; });
  const inSet = {}; pupils.forEach(function(p){ inSet[p.id] = true; });
  if(!(state.pathwayLogs||[]).length && !pupils.some(function(p){ return p.pathway; })){
    document.getElementById("progStats").innerHTML = "";
    host.innerHTML = '<div class="empty"><p style="margin:0 0 10px"><strong>No AAA pathways yet.</strong></p>'+
      '<p style="margin:0 0 12px">Import your AAA backup (Settings &amp; data → AAA pathways), or log pupils on the AAA board. This page then compares each pathway’s academic progress.</p>'+
      '<button class="btn" data-tab-go="aaa">Open the AAA board</button></div>';
    return;
  }
  const idx = curIndex();
  const sums = pupilSummaries(buildFlagRows());
  const stats = {};
  pupils.forEach(function(p){ stats[p.id] = pupilCurStats(p, idx); });
  const keys = PATHWAYS.concat(pupils.some(function(p){ return !p.pathway; }) ? [""] : []);

  const rmsOf = {};
  pupils.forEach(function(p){ rmsOf[p.id] = pupilMetrics(p, idx).rmsRate; });
  /* ---- 1. pathway by pathway, now ---- */
  const agg = {};
  keys.forEach(function(pw){
    const ps = pupils.filter(function(p){ return (p.pathway||"")===pw; });
    const a = {n:ps.length, judged:0, on:0, well:0, gains:[], exps:[], rmsList:[], gN:0, gOn:0, pri:0, conc:0, withCur:0, withSum:0, stepUp:0, review:0};
    ps.forEach(function(p){
      const s = stats[p.id];
      a.judged += s.judged; a.on += s.ahead + s.ontrack; a.well += s.well;
      if(s.judged) a.withCur++;
      if(s.gain!=null){ a.gains.push(s.gain); a.exps.push(s.expGain); }
      if(rmsOf[p.id]!=null) a.rmsList.push(rmsOf[p.id]);
      a.gN += s.gN; a.gOn += s.gOn;
      const sm = sums[p.id];
      if(sm){ a.withSum++; if(sm.priority) a.pri++; if(sm.concerns) a.conc++; }
    });
    a.gain = avgOf(a.gains); a.expGain = avgOf(a.exps); a.rms = avgOf(a.rmsList); a.nRms = a.rmsList.length;
    agg[pw] = a;
  });
  document.getElementById("progStats").innerHTML = PATHWAYS.map(function(pw){
    const a = agg[pw], col = PATHWAY_COLOURS[pw];
    return '<div class="stat" style="border-top-color:'+col[0]+'"><div class="n" style="color:'+col[0]+'">'+(a.judged ? Math.round(a.on/a.judged*100)+'%' : '—')+'</div>'+
      '<div class="l"><strong>'+esc(PATHWAY_LABELS[pw])+'</strong> · '+a.n+' pupil'+(a.n===1?'':'s')+'<br>on track or ahead'+
      (a.rms!=null ? ' · '+fmtRate(a.rms)+' levels a year at RMS' : '')+'</div></div>';
  }).join("");

  const T = function(label, fn){ return '<tr><td><strong>'+label+'</strong></td>'+keys.map(function(pw){ return fn(agg[pw]); }).join("")+'</tr>'; };
  const sideBySide = '<div class="panel"><h2>Pathways side by side</h2>'+
    '<p class="hint">Each pupil’s current pathway against their latest curriculum and summative picture. Curriculum counts pupil-subjects; summative counts pupils.</p>'+
    '<div class="tablewrap"><table class="matrix"><thead><tr><th></th>'+keys.map(pwHead).join("")+'</tr></thead><tbody>'+
    T("Pupils", function(a){ return '<td class="num"><b>'+a.n+'</b></td>'; })+
    T("Curriculum: on track or ahead", function(a){ return pctCell(a.on, a.judged, true); })+
    T("Curriculum: well behind", function(a){ return pctCell(a.well, a.judged, false); })+
    T("Levels a year at Red Moor (1.00 keeps pace)", function(a){ return rmsCell(a.rms, a.nRms); })+
    T("GCSE predicted on target", function(a){ return pctCell(a.gOn, a.gN, true); })+
    T("Summative: any concern flag", function(a){ return pctCell(a.conc, a.withSum, false); })+
    T("Summative: priority pupils", function(a){ return pctCell(a.pri, a.withSum, false); })+
    T("No curriculum data yet", function(a){ return '<td class="num">'+(a.n - a.withCur ? '<span class="delta bad">'+(a.n - a.withCur)+'</span>' : '<span class="muted">0</span>')+'</td>'; })+
    '</tbody></table></div></div>';

  /* ---- 2. summative assessments by pathway at the time, this year ---- */
  const dpsAy = ayDrops(ay);
  const assRows = state.assessments.filter(function(a){ return a.active && a.type!=="passfail"; }).map(function(a){
    const cells = {};
    keys.forEach(function(pw){ cells[pw] = {sum:0, n:0, conc:0}; });
    let any = 0;
    dpsAy.forEach(function(d){
      pupils.forEach(function(p){
        const r = resultFor(p.id, a.id, d.id);
        if(!r || r.value==="") return;
        const m = metricOf(p, a, r, d);
        const pw = contextOf(r, p, d).pw || "";
        const cl = cells[pw];
        if(!cl) return;
        if(m!=null){ cl.sum += m; cl.n++; any++; }
        if(evaluate(p, a, r, d).status==="concern") cl.conc++;
      });
    });
    if(!any) return "";
    const best = keys.map(function(pw){ return cells[pw].n ? cells[pw].sum/cells[pw].n : null; });
    return '<tr><td><strong>'+esc(a.name)+'</strong><br><span class="muted">'+esc(a.subject||"")+'</span></td>'+keys.map(function(pw, i){
      const cl = cells[pw];
      if(!cl.n) return '<td><span class="cell-na">—</span></td>';
      const cp = Math.round(cl.conc/cl.n*100);
      const bg = cp <= 15 ? "var(--secure-bg)" : (cp <= 30 ? "var(--watch-bg)" : "var(--concern-bg)");
      const bd = cp <= 15 ? "var(--secure-line)" : (cp <= 30 ? "var(--watch-line)" : "var(--concern-line)");
      return '<td><div class="heat" style="background:'+bg+';border:1px solid '+bd+'"><b>'+esc(fmtMetric(a, best[i]))+'</b> avg<br>'+cp+'% concern · n '+cl.n+'</div></td>';
    }).join("")+'</tr>';
  }).join("");
  const summative = '<div class="panel" style="margin-top:16px"><h2>Summative results by pathway ('+esc(ay)+')</h2>'+
    '<p class="hint">Every result this academic year, grouped by the pathway the pupil was on when they sat it. The average is the score, or for reading ages the months ahead or behind.</p>'+
    (assRows ? '<div class="tablewrap"><table class="matrix"><thead><tr><th>Assessment</th>'+keys.map(pwHead).join("")+'</tr></thead><tbody>'+assRows+'</tbody></table></div>'
             : '<div class="empty">No summative results entered for '+esc(ay)+' yet.</div>')+'</div>';

  /* ---- 3. start of year -> now ---- */
  const start = ayStartDate(ay);
  const trans = {}, fromKeys = PATHWAYS.concat([""]);
  fromKeys.forEach(function(f){ trans[f] = {}; keys.forEach(function(t){ trans[f][t] = 0; }); });
  let up = 0, down = 0, stay = 0;
  pupils.forEach(function(p){
    /* pathway on 1 September, or when first logged if that was later in the year */
    const f = logsFor(p.id).length ? (pathwayAt(p.id, start) || "") : "";
    const t = p.pathway || "";
    if(!trans[f]) trans[f] = {};
    trans[f][t] = (trans[f][t]||0) + 1;
    if(PW_RANK[f]!=null && PW_RANK[t]!=null){ if(PW_RANK[t] > PW_RANK[f]) up++; else if(PW_RANK[t] < PW_RANK[f]) down++; else stay++; }
  });
  const transHtml = '<div class="panel" style="margin-top:16px"><h2>Where pupils started the year, and where they are now</h2>'+
    '<p class="hint">Rows: pathway on 1 September '+esc(String(ayStart(ay)))+' (or when first logged, if later). Columns: pathway today. Green cells moved towards Attain, red away from it. '+
    '<strong>'+up+'</strong> up, <strong>'+stay+'</strong> unchanged, <strong>'+down+'</strong> down.</p>'+
    '<div class="tablewrap"><table class="matrix"><thead><tr><th>Start of year ↓ / Now →</th>'+keys.map(pwHead).join("")+'</tr></thead><tbody>'+
    fromKeys.filter(function(f){ return keys.some(function(t){ return trans[f][t]; }); }).map(function(f){
      return '<tr><td><strong>'+esc(f ? PATHWAY_LABELS[f] : "Not logged yet")+'</strong></td>'+keys.map(function(t){
        const n = trans[f][t] || 0;
        if(!n) return '<td><span class="cell-na">·</span></td>';
        let bg = "var(--panel)", bd = "var(--line)";
        if(PW_RANK[f]!=null && PW_RANK[t]!=null && f!==t){
          const isUp = PW_RANK[t] > PW_RANK[f];
          bg = isUp ? "var(--secure-bg)" : "var(--concern-bg)"; bd = isUp ? "var(--secure-line)" : "var(--concern-line)";
        }
        return '<td><div class="heat" style="background:'+bg+';border:1px solid '+bd+';text-align:center"><b>'+n+'</b></div></td>';
      }).join("")+'</tr>';
    }).join("")+'</tbody></table></div></div>';

  /* ---- 4. did the move help? ---- */
  const moves = (state.pathwayLogs||[]).filter(function(l){ return inSet[l.pupilId] && isRealMove(l); })
    .sort(function(a,b){ return String(b.ts).localeCompare(String(a.ts)); });
  const mv = moves.map(function(l){
    const p = byId(state.pupils, l.pupilId);
    return {l:l, p:p, dir:moveDir(l), cur:rateAround(l.pupilId, l.ts, idx), sum:summativeAround(p, l.ts)};
  });
  const grp = function(dir){
    const xs = mv.filter(function(m){ return m.dir===dir; });
    const both = xs.filter(function(m){ return m.cur.before!=null && m.cur.after!=null; });
    const av = function(k){ return avgOf(both.map(function(m){ return m.cur[k]; })); };
    const sb = xs.reduce(function(a,m){ return a + m.sum.better; }, 0), sw = xs.reduce(function(a,m){ return a + m.sum.worse; }, 0);
    return {n:xs.length, both:both.length, before:av("before"), expBefore:av("expBefore"), mBefore:av("mBefore"),
            after:av("after"), expAfter:av("expAfter"), mAfter:av("mAfter"), sb:sb, sw:sw};
  };
  const gu = grp("up"), gd = grp("down");
  const gRow = function(label, g){
    return '<tr><td><strong>'+label+'</strong></td><td class="num">'+g.n+'</td>'+
      '<td class="num">'+spanHtml(g.before, g.expBefore, g.mBefore)+'</td><td class="num">'+spanHtml(g.after, g.expAfter, g.mAfter)+'</td>'+
      '<td class="num">'+paceVerdict(paceOf(g.before, g.expBefore), paceOf(g.after, g.expAfter))+'</td>'+
      '<td class="num">'+(g.both ? g.both : '<span class="muted">0</span>')+'</td>'+
      '<td class="num">'+(g.sb||g.sw ? '<span class="delta good">'+g.sb+' up</span> · <span class="delta bad">'+g.sw+' down</span>' : '<span class="muted">—</span>')+'</td></tr>';
  };
  const mvList = mv.filter(function(m){ return progMoveDir==="all" || m.dir===progMoveDir; }).slice(0, 60);
  const movesHtml = '<div class="panel" style="margin-top:16px"><h2>Did the move make a difference?</h2>'+
    '<p class="hint">For every logged pathway change: levels gained before the move and since it (averaged over subjects; 2D to 3D is +1.0), each with what '+c.rate+' a year would expect over the same months, and summative scores before against since. '+
    '<em>Faster</em> or <em>slower</em> compares progress against expected before and after. This fills in as data drops come in.</p>'+
    (mv.length ? '<div class="tablewrap"><table><thead><tr><th>Moves</th><th class="num">Number</th><th class="num">Levels gained before the move</th><th class="num">Since the move</th><th class="num">Pace after the move</th><th class="num">With data both sides</th><th class="num">Summative scores since</th></tr></thead><tbody>'+
      gRow("Towards Attain", gu)+gRow("Away from Attain", gd)+'</tbody></table></div>'+
      '<details'+(progMoveOpen?' open':'')+' id="progMoveDet" style="margin-top:12px"><summary style="cursor:pointer;font-weight:600">Show each move ('+mv.length+')</summary>'+
      '<div class="pillrow noprint" style="margin-top:12px"><button data-progmove="all"'+(progMoveDir==="all"?' class="on"':'')+'>All moves</button>'+
      '<button data-progmove="up"'+(progMoveDir==="up"?' class="on"':'')+'>Towards Attain</button><button data-progmove="down"'+(progMoveDir==="down"?' class="on"':'')+'>Away from Attain</button></div>'+
      '<div class="tablewrap"><table><thead><tr><th>When</th><th>Pupil</th><th>Move</th><th>Reason</th><th class="num">Before</th><th class="num">Since</th><th class="num">Pace</th><th class="num">Summative since</th></tr></thead><tbody>'+
      mvList.map(function(m){
        return '<tr><td>'+esc(fmtDate(m.l.ts))+'</td><td><button class="linkbtn" data-goto-pupil="'+m.p.id+'">'+esc(m.p.name)+'</button> <span class="muted">Y'+esc(m.p.year)+'</span></td>'+
          '<td style="white-space:nowrap">'+pathwayTag(m.l.from, true)+' → '+pathwayTag(m.l.to, true)+'</td><td class="evidence">'+esc(reasonLabel(m.l.reason))+'</td>'+
          '<td class="num">'+spanHtml(m.cur.before, m.cur.expBefore, m.cur.mBefore)+'</td><td class="num">'+spanHtml(m.cur.after, m.cur.expAfter, m.cur.mAfter)+'</td>'+
          '<td class="num">'+paceVerdict(paceOf(m.cur.before, m.cur.expBefore), paceOf(m.cur.after, m.cur.expAfter))+'</td>'+
          '<td class="num">'+(m.sum.better||m.sum.worse||m.sum.same ? '<span class="delta good">'+m.sum.better+'↑</span> <span class="delta bad">'+m.sum.worse+'↓</span>' : '<span class="muted">—</span>')+'</td></tr>';
      }).join("")+'</tbody></table></div></details>'
    : '<div class="empty">No pathway changes logged for these pupils yet.</div>')+'</div>';

  /* ---- 5. pathway and progress don't agree ---- */
  const review = [];
  pupils.forEach(function(p){
    const s = stats[p.id], sm = sums[p.id], pw = p.pathway || "";
    const behind = s.behind + s.well;
    /* V41: Attain = on track for core GCSEs, so a likely grade below 4 in English or maths is also a reason to review */
    const emLow = pw==="attain" ? emLikely(p, idx).filter(function(x){ return x.likely!=null && gcseRank(x.likely) < 4; }) : [];
    if(pw==="attain" && emLow.length && !((s.judged >= 2 && behind >= Math.max(2, Math.ceil(s.judged/2))) || (sm && sm.priority)))
      review.push({p:p, kind:"down", why:'Likely GCSE below 4 in '+emLow.map(function(x){ return x.su.name+' ('+x.likely+')'; }).join(' and ')});
    else if(pw==="attain" && ((s.judged >= 2 && behind >= Math.max(2, Math.ceil(s.judged/2))) || (sm && sm.priority)))
      review.push({p:p, kind:"down", why:(behind ? 'Behind in '+behind+' of '+s.judged+' subjects' : '')+(sm && sm.priority ? (behind?'; ':'')+'summative priority ('+sm.concerns+' concern'+(sm.concerns===1?'':'s')+')' : '')});
    else if(pw && pw!=="attain" && s.judged >= 2 && (s.ahead+s.ontrack)/s.judged >= 0.75 && (s.gain==null || gainClass(s.gain, s.expGain)==="good") && !(sm && sm.priority))
      review.push({p:p, kind:"up", why:'On track or ahead in '+(s.ahead+s.ontrack)+' of '+s.judged+' subjects'+(s.gain!=null ? ', '+fmtGain(s.gain)+' levels gained (expected '+fmtGain(s.expGain)+')' : '')});
    const lastAc = logsFor(p.id).filter(function(l){ return l.reason==="academic_concern"; })[0];
    if(lastAc){
      const cut = String(lastAc.ts).slice(0,10);
      const since = (state.curResults||[]).some(function(r){ const d = byId(state.settings.dataPoints, r.dataPointId); return r.pupilId===p.id && d && d.date > cut; }) ||
                    state.results.some(function(r){ const d = byId(state.settings.dataPoints, r.dataPointId); return r.pupilId===p.id && d && d.date > cut; });
      if(!since) review.push({p:p, kind:"nodata", why:'Academic concern logged '+fmtDate(lastAc.ts)+'; no levels or results since'});
    }
  });
  const kindLbl = {down:["Attain, but the data says otherwise","t-concern"], up:["Could be ready to step up","t-secure"], nodata:["Academic concern, nothing to check it against","t-watch"]};
  const reviewHtml = '<div class="panel" style="margin-top:16px"><h2>Pathway and progress don’t agree</h2>'+
    '<p class="hint">Worth discussing at the next pathway review. Attain pupils behind in at least half their subjects (and at least 2), a summative priority, or likely below grade 4 in English or maths; pupils on other pathways on track in three-quarters or more of their subjects, with levels gained at or near expected; and academic concerns with no data since.</p>'+
    (review.length ? '<div class="tablewrap"><table><thead><tr><th>Pupil</th><th>Yr</th><th>Pathway</th><th>Flag</th><th>Evidence</th><th></th></tr></thead><tbody>'+
      review.sort(function(a,b){ return a.kind.localeCompare(b.kind) || String(a.p.name).localeCompare(String(b.p.name)); }).map(function(r){
        return '<tr><td><button class="linkbtn" data-goto-pupil="'+r.p.id+'">'+esc(r.p.name)+'</button></td><td>'+esc(r.p.year)+'</td><td>'+pathwayTag(r.p.pathway, true)+'</td>'+
          '<td><span class="tag '+kindLbl[r.kind][1]+'">'+kindLbl[r.kind][0]+'</span></td><td class="evidence">'+esc(r.why)+'</td>'+
          '<td><button class="btn ghost sm noprint" data-aaa-pupil="'+r.p.id+'">Log update</button></td></tr>';
      }).join("")+'</tbody></table></div>'
      : '<div class="empty">Nothing to flag: pathways and academic data agree, or there isn’t enough curriculum data yet.</div>')+'</div>';

  /* ---- 6. pupil by pupil ---- */
  const ayStartIso = start;
  let list = pupils.filter(function(p){ return progPw==="" || (progPw==="none" ? !p.pathway : p.pathway===progPw); });
  list.sort(function(a,b){ return ((PW_RANK[b.pathway]==null?-1:PW_RANK[b.pathway]) - (PW_RANK[a.pathway]==null?-1:PW_RANK[a.pathway])) ||
    ((stats[b.id].behind+stats[b.id].well) - (stats[a.id].behind+stats[a.id].well)) || String(a.name).localeCompare(String(b.name)); });
  const pupilRows = list.map(function(p){
    const s = stats[p.id], sm = sums[p.id], since = pathwaySince(p);
    const nMoves = logsFor(p.id).filter(function(l){ return isRealMove(l) && String(l.ts).slice(0,10) >= ayStartIso; }).length;
    return '<tr><td style="white-space:nowrap"><button class="linkbtn" data-goto-pupil="'+p.id+'">'+esc(p.name)+'</button></td><td>'+esc(p.year)+'</td>'+
      '<td style="white-space:nowrap">'+pathwayTag(p.pathway, true)+'</td><td>'+(since ? esc(fmtDate(since)) : '<span class="muted">—</span>')+'</td>'+
      '<td class="num">'+(nMoves ? (nMoves >= 3 ? '<span class="delta bad">'+nMoves+'</span>' : nMoves) : '<span class="muted">0</span>')+'</td>'+
      '<td class="num">'+(s.judged ? s.judged : '<span class="muted">0</span>')+'</td>'+
      '<td class="num">'+(s.onPct!=null ? s.onPct+'%' : '<span class="muted">—</span>')+'</td>'+
      '<td class="num">'+(s.behind ? '<span class="delta same">'+s.behind+'</span>' : '<span class="muted">0</span>')+'</td>'+
      '<td class="num">'+(s.well ? '<span class="delta bad">'+s.well+'</span>' : '<span class="muted">0</span>')+'</td>'+
      '<td class="num" style="white-space:nowrap">'+(rmsOf[p.id]==null ? '<span class="muted">—</span>' : '<span class="delta '+(rmsOf[p.id] >= 1.05 ? 'good' : (rmsOf[p.id] >= 0.95 ? 'same' : 'bad'))+'">'+fmtRate(rmsOf[p.id])+'</span>')+'</td>'+
      '<td class="num">'+(s.gN ? s.gOn+' of '+s.gN : '<span class="muted">—</span>')+'</td>'+
      '<td>'+(sm && sm.priority ? '<span class="tag t-concern">Priority</span>' : (sm && sm.concerns ? '<span class="tag t-watch">'+sm.concerns+' concern'+(sm.concerns===1?'':'s')+'</span>' : (sm ? '<span class="tag t-secure">Clear</span>' : '<span class="muted">—</span>')))+'</td></tr>';
  }).join("");
  const pwOpts = '<option value="">All pathways</option>'+PATHWAYS.map(function(k){ return '<option value="'+k+'"'+(progPw===k?' selected':'')+'>'+esc(PATHWAY_LABELS[k])+'</option>'; }).join("")+
    '<option value="none"'+(progPw==="none"?' selected':'')+'>No pathway</option>';
  const pupilHtml = '<div class="panel" style="margin-top:16px"><div class="row" style="align-items:flex-end"><h2 style="margin:0">Pupil by pupil</h2><span class="spacer"></span>'+
    '<label class="fld noprint">Pathway<select id="progPwSel">'+pwOpts+'</select></label></div>'+
    '<p class="hint">Current pathway, how long they have been on it, moves this year, and their academic picture. Three or more moves in a year is shown in red.</p>'+
    (list.length ? '<div class="tablewrap"><table><thead><tr><th>Pupil</th><th>Yr</th><th>Pathway</th><th>Since</th><th class="num">Moves this year</th><th class="num">Subjects</th><th class="num">On track</th><th class="num">Behind</th><th class="num">Well behind</th><th class="num">Levels a year at RMS</th><th class="num">GCSE on target</th><th>Summative</th></tr></thead><tbody>'+
      pupilRows+'</tbody></table></div>' : '<div class="empty">No pupils match.</div>')+'</div>';

  host.innerHTML = sideBySide + summative + transHtml + movesHtml + reviewHtml + pupilHtml;
  const det = document.getElementById("progMoveDet");
  if(det) det.addEventListener("toggle", function(){ progMoveOpen = det.open; });
}

function exportAaaProgressCsv(){
  const idx = curIndex(), sums = pupilSummaries(buildFlagRows());
  const start = ayStartDate(currentAY());
  const lines = [["Pupil","Year","Pathway","On pathway since","Moves this year","Subjects judged","Ahead","On track","Behind","Well behind","Avg levels gained","Expected gain","GCSE on target","GCSE judged","Summative concerns","Summative priority"].map(csvCell).join(",")];
  state.pupils.filter(function(p){ return !progYear || String(p.year)===progYear; }).forEach(function(p){
    const s = pupilCurStats(p, idx), sm = sums[p.id], since = pathwaySince(p);
    const nMoves = logsFor(p.id).filter(function(l){ return isRealMove(l) && String(l.ts).slice(0,10) >= start; }).length;
    lines.push([p.name, p.year, PATHWAY_LABELS[p.pathway]||"", since ? fmtDate(since) : "", nMoves, s.judged, s.ahead, s.ontrack, s.behind, s.well,
      s.gain!=null ? fmtGain(s.gain) : "", s.expGain!=null ? fmtGain(s.expGain) : "", s.gOn, s.gN, sm ? sm.concerns : "", sm && sm.priority ? "Yes" : ""].map(csvCell).join(","));
  });
  downloadBlob("aaa_progress.csv", lines.join("\n"), "text/csv;charset=utf-8");
}

/* ======================= CURRICULUM =======================
   Levels 1-9, each in three steps: E(merging), D(eveloping), S(ecure). A step is
   a third of a level, so 4E = 4.00, 4D = 4.33, 4S = 4.67. From Year 10 (setting
   gcseFrom) pupils have GCSE grades instead: Target, Predicted each drop, Actual.
   Expected level now = baseline + rate (0.8) x years since the baseline date. */
const LEVEL_STEPS = ["E","D","S"];
const LEVEL_OPTIONS = (function(){ const o = []; for(let f=1;f<=10;f++) o.push("FLS"+f); for(let l=1;l<=9;l++) LEVEL_STEPS.forEach(function(s){ o.push(l + s); }); return o; })();
const GCSE_OPTIONS = ["9","8","7","6","5","4","3","2","1","U"];
const CUR_KINDS = {level:"Level", predicted:"GCSE grade now (working at / predicted)", target:"GCSE target", actual:"GCSE exam result (final)"};
const CUR_STATUS = {
  ahead:   {label:"Ahead", cls:"t-above", rank:4},
  ontrack: {label:"On track", cls:"t-secure", rank:3},
  behind:  {label:"Behind", cls:"t-watch", rank:2},
  well:    {label:"Well behind", cls:"t-concern", rank:1},
  baseline:{label:"Baseline", cls:"t-none", rank:0},
  early:   {label:"Too early", cls:"t-none", rank:0},
  noresult:{label:"No result this year", cls:"t-none", rank:0},
  nobase:  {label:"No baseline", cls:"t-none", rank:0},
  none:    {label:"—", cls:"t-none", rank:0}
};
